def _is_loopback_bind(host: str) -> bool:
    value = (host or "").strip().lower()
    if value == "localhost":
        return True
    try:
        return ipaddress.ip_address(value).is_loopback
    except ValueError:
        return False


def _optional_env_bool(name: str) -> bool | None:
    value = os.getenv(name)
    if value is None or not value.strip():
        return None
    return value.strip().lower() in {"1", "true", "yes", "on"}


def _validate_http_url_shape(url: str) -> str:
    value = str(url or "").strip()
    if not value or len(value) > MAX_URL_LENGTH:
        raise WebError(HTTPStatus.BAD_REQUEST, "URL is missing or too long.")
    parsed = urlparse(value)
    if parsed.scheme not in {"http", "https"} or not parsed.hostname:
        raise WebError(HTTPStatus.BAD_REQUEST, "Only absolute HTTP(S) URLs are allowed.")
    if parsed.username is not None or parsed.password is not None:
        raise WebError(HTTPStatus.BAD_REQUEST, "URL credentials are not allowed.")
    try:
        _ = parsed.port or (443 if parsed.scheme == "https" else 80)
    except ValueError as exc:
        raise WebError(HTTPStatus.BAD_REQUEST, "URL port is invalid.") from exc
    return value


def _validate_proxy_url(url: str) -> str:
    value = str(url or "").strip()
    if not value or len(value) > MAX_PROXY_URL_LENGTH:
        raise WebError(HTTPStatus.BAD_REQUEST, "Proxy URL is missing or too long.")
    parsed = urlparse(value)
    if parsed.scheme.lower() not in PROXY_SCHEMES or not parsed.hostname:
        raise WebError(
            HTTPStatus.BAD_REQUEST,
            "Proxy URL must use HTTP, HTTPS, SOCKS5, or SOCKS5H.",
            "invalid_proxy_url",
        )
    try:
        _ = parsed.port
    except ValueError as exc:
        raise WebError(
            HTTPStatus.BAD_REQUEST, "Proxy port is invalid.", "invalid_proxy_url"
        ) from exc
    if parsed.path not in {"", "/"} or parsed.query or parsed.fragment:
        raise WebError(
            HTTPStatus.BAD_REQUEST,
            "Proxy URL must not contain a path, query, or fragment.",
            "invalid_proxy_url",
        )
    return value


def _proxy_url_from_fields(body: Mapping[str, Any]) -> str | None:
    """Build a validated proxy URL from separate form fields.

    ``proxyUrl`` remains accepted for older clients. New clients send the
    structured fields so credentials never need to be manually URL-encoded.
    """
    if body.get("proxyEnabled") is False:
        return None
    legacy_url = str(body.get("proxyUrl") or "").strip()
    field_keys = {
        "proxyScheme",
        "proxyHost",
        "proxyPort",
        "proxyUsername",
        "proxyPassword",
    }
    if not any(key in body for key in field_keys):
        return legacy_url or None

    scheme = str(body.get("proxyScheme") or "http").strip().lower()
    host = str(body.get("proxyHost") or "").strip()
    port_raw = str(body.get("proxyPort") or "").strip()
    username = str(body.get("proxyUsername") or "").strip()
    password = str(body.get("proxyPassword") or "")
    if not any((host, port_raw, username, password)):
        return legacy_url or None
    if scheme not in PROXY_SCHEMES:
        raise WebError(
            HTTPStatus.BAD_REQUEST,
            "Proxy type must be HTTP, HTTPS, SOCKS5, or SOCKS5H.",
            "invalid_proxy_setting",
        )
    if not host or len(host) > MAX_PROXY_HOST_LENGTH:
        raise WebError(
            HTTPStatus.BAD_REQUEST,
            "Proxy host is required or too long.",
            "invalid_proxy_setting",
        )
    if any(char.isspace() for char in host) or any(
        marker in host for marker in ("://", "/", "?", "#", "@")
    ):
        raise WebError(
            HTTPStatus.BAD_REQUEST,
            "Enter only the proxy host, without protocol, path, or credentials.",
            "invalid_proxy_setting",
        )
    try:
        port = int(port_raw)
    except ValueError as exc:
        raise WebError(
            HTTPStatus.BAD_REQUEST,
            "Proxy port must be a number from 1 to 65535.",
            "invalid_proxy_setting",
        ) from exc
    if not 1 <= port <= 65535:
        raise WebError(
            HTTPStatus.BAD_REQUEST,
            "Proxy port must be a number from 1 to 65535.",
            "invalid_proxy_setting",
        )
    if len(username) > MAX_PROXY_USERNAME_LENGTH:
        raise WebError(
            HTTPStatus.BAD_REQUEST,
            "Proxy username is too long.",
            "invalid_proxy_setting",
        )
    if len(password) > MAX_PROXY_PASSWORD_LENGTH or "\x00" in password:
        raise WebError(
            HTTPStatus.BAD_REQUEST,
            "Proxy password is invalid or too long.",
            "invalid_proxy_setting",
        )

    host_value = host[1:-1] if host.startswith("[") and host.endswith("]") else host
    try:
        address = ipaddress.ip_address(host_value)
        encoded_host = f"[{address.compressed}]" if address.version == 6 else str(address)
    except ValueError:
        try:
            encoded_host = host_value.encode("idna").decode("ascii").lower()
        except UnicodeError as exc:
            raise WebError(
                HTTPStatus.BAD_REQUEST,
                "Proxy host is invalid.",
                "invalid_proxy_setting",
            ) from exc
        if not re.fullmatch(r"[a-z0-9](?:[a-z0-9._-]{0,251}[a-z0-9])?", encoded_host):
            raise WebError(
                HTTPStatus.BAD_REQUEST,
                "Proxy host is invalid.",
                "invalid_proxy_setting",
            ) from None

    credentials = ""
    if username or password:
        credentials = f"{quote(username, safe='')}:{quote(password, safe='')}@"
    return _validate_proxy_url(f"{scheme}://{credentials}{encoded_host}:{port}")


def _line_config_for_proxy(proxy_url: str | None) -> LineConfig | None:
    if not proxy_url:
        return None
    value = _validate_proxy_url(proxy_url)
    return LineConfig(proxies={"http": value, "https": value})


def _public_http_target(url: str) -> tuple[str, tuple[str, ...]]:
    value = _validate_http_url_shape(url)
    parsed = urlparse(value)
    port = parsed.port or (443 if parsed.scheme == "https" else 80)
    try:
        addresses = {
            ipaddress.ip_address(str(item[4][0]).split("%", 1)[0])
            for item in socket.getaddrinfo(parsed.hostname, port, type=socket.SOCK_STREAM)
        }
    except (OSError, ValueError) as exc:
        raise WebError(HTTPStatus.BAD_GATEWAY, "URL host could not be resolved.") from exc
    if not addresses or any(not address.is_global for address in addresses):
        raise WebError(
            HTTPStatus.BAD_REQUEST,
            "Private, loopback, link-local, and reserved network addresses are not allowed.",
            "unsafe_url",
        )
    return value, tuple(sorted(str(address) for address in addresses))


def _validate_public_http_url(url: str) -> str:
    value, _ = _public_http_target(url)
    return value


class _PinnedAddressAdapter(HTTPAdapter):
    def __init__(self, url: str, address: str) -> None:
        self.target = urlparse(url)
        self.address = address
        super().__init__(pool_connections=1, pool_maxsize=1, max_retries=0)

    def get_connection_with_tls_context(
        self,
        request: requests.PreparedRequest,
        verify: Any,
        proxies: Mapping[str, str] | None = None,
        cert: Any = None,
    ) -> HTTPConnectionPool:
        port = self.target.port or (443 if self.target.scheme == "https" else 80)
        if self.target.scheme == "https":
            _, raw_pool_kwargs = self.build_connection_pool_key_attributes(
                request, verify, cert
            )
            pool_kwargs: dict[str, Any] = dict(raw_pool_kwargs)
            pool_kwargs["assert_hostname"] = self.target.hostname
            pool_kwargs["server_hostname"] = self.target.hostname
            return HTTPSConnectionPool(self.address, port, **pool_kwargs)
        return HTTPConnectionPool(self.address, port)

    def send(
        self,
        request: requests.PreparedRequest,
        *args: Any,
        **kwargs: Any,
    ) -> requests.Response:
        host = str(self.target.hostname or "")
        port = self.target.port
        default_port = 443 if self.target.scheme == "https" else 80
        request.headers["Host"] = f"{host}:{port}" if port and port != default_port else host
        return super().send(request, *args, **kwargs)


def _request_public_address(
    method: str,
    url: str,
    *,
    timeout: int | float,
    headers: dict[str, str],
    json_data: Any,
    data: Any,
    params: dict[str, Any] | None,
) -> requests.Response:
    current, addresses = _public_http_target(url)
    last_error: requests.RequestException | None = None
    for address in addresses:
        session = requests.Session()
        session.trust_env = False
        session.mount(
            f"{urlparse(current).scheme}://", _PinnedAddressAdapter(current, address)
        )
        try:
            response = session.request(
                method,
                current,
                timeout=timeout,
                headers=headers,
                json=json_data,
                data=data,
                params=params,
                allow_redirects=False,
                stream=True,
            )
        except requests.RequestException as exc:
            last_error = exc
            session.close()
            continue
        original_close = response.close

        def close_response(
            close: Callable[[], None] = original_close,
            close_session: Callable[[], None] = session.close,
        ) -> None:
            try:
                close()
            finally:
                close_session()

        response.close = close_response  # type: ignore[method-assign]
        return response
    raise WebError(
        HTTPStatus.BAD_GATEWAY,
        f"Upstream connection failed: {_safe_log_detail(last_error, 500)}",
    ) from last_error


def _open_public_response(
    method: str,
    url: str,
    *,
    timeout: int | float,
    headers: dict[str, str] | None = None,
    json_data: Any = None,
    data: Any = None,
    params: dict[str, Any] | None = None,
) -> tuple[requests.Response, str]:
    current = _validate_public_http_url(url)
    current_method = method.upper()
    current_headers = dict(headers or {})
    current_json = json_data
    current_data = data
    current_params = params
    for redirect_count in range(MAX_REDIRECTS + 1):
        response = _request_public_address(
            current_method,
            current,
            timeout=timeout,
            headers=current_headers,
            json_data=current_json,
            data=current_data,
            params=current_params,
        )
        if response.status_code not in {301, 302, 303, 307, 308}:
            return response, current
        location = response.headers.get("location")
        response.close()
        if not location:
            raise WebError(HTTPStatus.BAD_GATEWAY, "Upstream redirect has no destination.")
        if redirect_count >= MAX_REDIRECTS:
            raise WebError(HTTPStatus.BAD_GATEWAY, "Upstream returned too many redirects.")
        current = _validate_public_http_url(urljoin(current, location))
        current_params = None
        if response.status_code == 303 or (
            response.status_code in {301, 302} and current_method == "POST"
        ):
            current_method = "GET"
            current_json = None
            current_data = None
            current_headers.pop("content-type", None)
            current_headers.pop("Content-Type", None)
    raise WebError(HTTPStatus.BAD_GATEWAY, "Upstream returned too many redirects.")


def _read_limited_response(response: requests.Response, max_bytes: int) -> bytes:
    declared = response.headers.get("content-length")
    if declared:
        try:
            if int(declared) > max_bytes:
                raise WebError(HTTPStatus.BAD_GATEWAY, "Upstream response is too large.")
        except ValueError:
            pass
    chunks: list[bytes] = []
    total = 0
    for chunk in response.iter_content(chunk_size=64 * 1024):
        if not chunk:
            continue
        total += len(chunk)
        if total > max_bytes:
            raise WebError(HTTPStatus.BAD_GATEWAY, "Upstream response is too large.")
        chunks.append(chunk)
    return b"".join(chunks)


def _buffer_response_limited(response: requests.Response, max_bytes: int) -> requests.Response:
    """Buffer a streamed response with a hard cap while preserving .json()/.text APIs."""
    if hasattr(response, "iter_content"):
        try:
            raw = _read_limited_response(response, max_bytes)
        finally:
            response.close()
        response._content = raw
        response._content_consumed = True  # type: ignore[attr-defined]
        return response
    raw = getattr(response, "content", b"")
    if not raw:
        raw = str(getattr(response, "text", "") or "").encode("utf-8")
    if len(raw) > max_bytes:
        raise WebError(HTTPStatus.BAD_GATEWAY, "Upstream response is too large.")
    return response


