def _now_iso() -> str:
    return _dt.datetime.now().replace(microsecond=0).isoformat()


def _strip_account_from_user(user: Any, account_ids: set[str]) -> bool:
    """Remove owned and shared access to ``account_ids``; True when changed."""
    if not isinstance(user, dict):
        return False
    changed = False
    for key in ("accountIds", "staffAccountIds"):
        current = list(user.get(key) or [])
        kept = [item for item in current if item not in account_ids]
        if len(kept) != len(current):
            user[key] = kept
            changed = True
    if changed:
        user["updatedAt"] = _now_iso()
    return changed


def _safe_slug(value: str, fallback: str = "account") -> str:
    slug = re.sub(r"[^A-Za-z0-9_.-]+", "-", value.strip()).strip("-._").lower()
    return slug[:42] or fallback


def _read_json_file(path: str, default: Any) -> Any:
    try:
        with open(path, encoding="utf-8") as fh:
            return json.load(fh)
    except FileNotFoundError:
        return default
    except ValueError:
        return default


def _write_json_file(path: str, value: Any) -> None:
    parent = os.path.dirname(path)
    if parent:
        os.makedirs(parent, exist_ok=True)
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as fh:
        json.dump(value, fh, ensure_ascii=False, indent=2)
        fh.flush()
        os.fsync(fh.fileno())
    try:
        os.chmod(tmp, 0o600)
    except OSError:
        pass
    os.replace(tmp, path)
    try:
        os.chmod(path, 0o600)
    except OSError:
        pass


def _write_private_bytes(path: str, value: bytes) -> None:
    parent = os.path.dirname(path)
    if parent:
        _ensure_private_directory(parent)
    tmp = f"{path}.tmp-{os.getpid()}-{threading.get_ident()}"
    with open(tmp, "wb") as fh:
        fh.write(value)
        fh.flush()
        os.fsync(fh.fileno())
    try:
        os.chmod(tmp, 0o600)
    except OSError:
        pass
    os.replace(tmp, path)
    try:
        os.chmod(path, 0o600)
    except OSError:
        pass


def _ensure_private_directory(path: str) -> None:
    if not path:
        return
    os.makedirs(path, exist_ok=True)
    try:
        os.chmod(path, 0o700)
    except OSError:
        pass


class StateStore:
    def get(self, key: str, default: Any) -> Any:
        raise NotImplementedError

    def set(self, key: str, value: Any) -> None:
        raise NotImplementedError

    def set_many(self, values: dict[str, Any]) -> None:
        for key, value in values.items():
            self.set(key, value)

    def label(self) -> str:
        raise NotImplementedError

    def close(self) -> None:
        return


class FileStateStore(StateStore):
    def __init__(self, config: WebConfig) -> None:
        self.config = config
        self.lock = threading.RLock()
        self.paths = {
            "accounts": config.accounts_file,
            "schedules": config.schedules_file,
            "auth": config.auth_file,
            "patterns": str(Path(config.schedules_file).parent / "patterns.json"),
            "ai_settings": str(Path(config.schedules_file).parent / "ai_settings.json"),
            "global_ai": str(Path(config.schedules_file).parent / "global_ai.json"),
            "bot_logs": str(Path(config.schedules_file).parent / "bot_logs.json"),
            "incoming_api": str(Path(config.schedules_file).parent / "incoming_api.json"),
            "ai_auto_reply": str(
                Path(config.schedules_file).parent / "ai_auto_reply.json"
            ),
        }

    def _path(self, key: str) -> str:
        known = self.paths.get(key)
        if known:
            return known
        # Dynamic keys such as ``room_state:<accountId>`` live in their own files.
        if not re.fullmatch(r"[a-z_]{1,40}(:[A-Za-z0-9_.-]{1,120})?", key):
            raise KeyError(key)
        name = key.replace(":", "__")
        return str(Path(self.config.schedules_file).parent / "kv" / f"{name}.json")

    def get(self, key: str, default: Any) -> Any:
        with self.lock:
            return _read_json_file(self._path(key), default)

    def set(self, key: str, value: Any) -> None:
        with self.lock:
            path = self._path(key)
            Path(path).parent.mkdir(parents=True, exist_ok=True)
            _write_json_file(path, value)

    def set_many(self, values: dict[str, Any]) -> None:
        with self.lock:
            backups: dict[str, bytes | None] = {}
            for key in values:
                path = self._path(key)
                Path(path).parent.mkdir(parents=True, exist_ok=True)
                backups[key] = Path(path).read_bytes() if os.path.exists(path) else None
            try:
                for key, value in values.items():
                    _write_json_file(self._path(key), value)
            except Exception:
                for key, raw in reversed(list(backups.items())):
                    path = self._path(key)
                    try:
                        if raw is None:
                            if os.path.exists(path):
                                os.remove(path)
                        else:
                            tmp = path + ".rollback.tmp"
                            with open(tmp, "wb") as fh:
                                fh.write(raw)
                                fh.flush()
                                os.fsync(fh.fileno())
                            try:
                                os.chmod(tmp, 0o600)
                            except OSError:
                                pass
                            os.replace(tmp, path)
                    except OSError:
                        traceback.print_exc()
                raise

    def label(self) -> str:
        return "file"


class PostgresStateStore(StateStore):
    def __init__(self, database_url: str, config: WebConfig) -> None:
        self.database_url = database_url
        self._instance_lock_conn = None
        self._ensure_schema()
        self._acquire_instance_lock()
        try:
            self._migrate_legacy_files(config)
        except Exception:
            self.close()
            raise

    def _connect(self):
        try:
            import psycopg
        except ImportError as exc:
            raise WebError(
                HTTPStatus.INTERNAL_SERVER_ERROR,
                "PostgreSQL support requires psycopg. Run: pip install 'psycopg[binary]>=3.1'",
            ) from exc
        return psycopg.connect(self.database_url)

    def _ensure_schema(self) -> None:
        with self._connect() as conn, conn.cursor() as cur:
            cur.execute(
                """
                CREATE TABLE IF NOT EXISTS okline_web_state (
                  key text PRIMARY KEY,
                  value jsonb NOT NULL,
                  updated_at timestamptz NOT NULL DEFAULT now()
                )
                """
            )

    def _acquire_instance_lock(self) -> None:
        conn = self._connect()
        conn.autocommit = True
        try:
            with conn.cursor() as cur:
                cur.execute("SELECT pg_try_advisory_lock(%s)", (1280332624,))
                row = cur.fetchone()
            if not row or not bool(row[0]):
                raise WebError(
                    HTTPStatus.SERVICE_UNAVAILABLE,
                    "Another LinePassport instance is already using this database. Run one replica only.",
                    "instance_already_running",
                )
        except Exception:
            conn.close()
            raise
        self._instance_lock_conn = conn

    def _migrate_legacy_files(self, config: WebConfig) -> None:
        legacy: dict[str, tuple[str, Any]] = {
            "accounts": (config.accounts_file, {"accounts": []}),
            "schedules": (config.schedules_file, {"schedules": []}),
            "auth": (config.auth_file, {}),
            "patterns": (
                str(Path(config.schedules_file).parent / "patterns.json"),
                {"patterns": []},
            ),
            "ai_settings": (str(Path(config.schedules_file).parent / "ai_settings.json"), {}),
            "global_ai": (str(Path(config.schedules_file).parent / "global_ai.json"), {}),
            "bot_logs": (
                str(Path(config.schedules_file).parent / "bot_logs.json"),
                {"logs": []},
            ),
            "incoming_api": (
                str(Path(config.schedules_file).parent / "incoming_api.json"),
                {"links": []},
            ),
            "ai_auto_reply": (
                str(Path(config.schedules_file).parent / "ai_auto_reply.json"),
                {"accounts": {}},
            ),
        }
        for key, (path, default) in legacy.items():
            if self.get(key, None) is not None or not os.path.exists(path):
                continue
            self.set(key, _read_json_file(path, default))

    def get(self, key: str, default: Any) -> Any:
        with self._connect() as conn, conn.cursor() as cur:
            cur.execute("SELECT value FROM okline_web_state WHERE key = %s", (key,))
            row = cur.fetchone()
        if row is None:
            return default
        value = row[0]
        if isinstance(value, str):
            try:
                return json.loads(value)
            except ValueError:
                return default
        return value

    def set(self, key: str, value: Any) -> None:
        self.set_many({key: value})

    def set_many(self, values: dict[str, Any]) -> None:
        with self._connect() as conn, conn.cursor() as cur:
            for key, value in values.items():
                raw = json.dumps(value, ensure_ascii=False, default=_json_default)
                cur.execute(
                    """
                    INSERT INTO okline_web_state (key, value, updated_at)
                    VALUES (%s, %s::jsonb, now())
                    ON CONFLICT (key)
                    DO UPDATE SET value = EXCLUDED.value, updated_at = now()
                    """,
                    (key, raw),
                )

    def label(self) -> str:
        return "postgresql"

    def close(self) -> None:
        conn = self._instance_lock_conn
        self._instance_lock_conn = None
        if conn is not None:
            conn.close()


def _make_state_store(config: WebConfig) -> StateStore:
    database_url = (
        config.database_url or os.getenv("OKLINE_DATABASE_URL") or os.getenv("DATABASE_URL")
    )
    if database_url:
        return PostgresStateStore(database_url, config)
    return FileStateStore(config)


def _make_crm_database(config: WebConfig) -> CrmDatabase:
    """Customer records live next to the web state: PostgreSQL when configured."""
    database_url = (
        config.database_url or os.getenv("OKLINE_DATABASE_URL") or os.getenv("DATABASE_URL")
    )
    if database_url:
        return CrmDatabase(database_url=database_url)
    return CrmDatabase(sqlite_path=os.path.join(config.state_dir, "crm.sqlite3"))


class WebAuth:
    cookie_name = "okline_web_session"
    god_cookie_name = "okline_god_session"
    legacy_iterations = 240_000
    iterations = 600_000
    login_window_seconds = 15 * 60
    login_max_failures = 5
    registration_window_seconds = 60 * 60
    registration_max_attempts = 5

    def __init__(self, store: StateStore | str) -> None:
        self.lock = threading.RLock()
        self.login_failures: dict[str, list[float]] = {}
        self.registration_attempts: dict[str, list[float]] = {}
        if isinstance(store, str):
            self.store: StateStore = FileStateStore(
                WebConfig(auth_file=store, accounts_file="", schedules_file="")
            )
        else:
            self.store = store
        self.data = self._load()

    def _load(self) -> dict[str, Any]:
        data = self.store.get("auth", {})
        if not isinstance(data, dict):
            data = {}
        if data.get("salt") and data.get("passwordHash"):
            data = {
                "users": [
                    {
                        "id": uuid.uuid4().hex,
                        "username": "admin",
                        "displayName": "Admin",
                        "role": "admin",
                        "salt": data["salt"],
                        "passwordHash": data["passwordHash"],
                        "accountIds": [],
                        "active": True,
                        "createdAt": data.get("createdAt") or _now_iso(),
                        "updatedAt": _now_iso(),
                    }
                ],
                "sessions": {},
                "createdAt": data.get("createdAt") or _now_iso(),
                "updatedAt": _now_iso(),
            }
            self._save(data)
        data.setdefault("users", [])
        data.setdefault("sessions", {})
        migrated = False
        for user in data["users"]:
            if not isinstance(user, dict) or user.get("email"):
                continue
            email = self._email_or_empty(str(user.get("username") or ""))
            if email:
                user["email"] = email
                user["username"] = email
                migrated = True
        if migrated:
            data["updatedAt"] = _now_iso()
            self._save(data)
        return data

    def _save(self, data: dict[str, Any] | None = None) -> None:
        if data is not None:
            self.data = data
        self.store.set("auth", self.data)

    def configured(self) -> bool:
        return any(self._is_active_user(user) for user in self.data.get("users", []))

    def simple_mode(self) -> bool:
        """True when the app is running unsecured with the auto-provisioned
        local user (no password prompt).  Cleared the moment a real user or a
        password is added via the Advanced panel."""
        return bool(self.data.get("simpleMode"))

    def ensure_simple_mode(self) -> str | None:
        """First run: silently provision a single local admin so a solo,
        non-technical user lands straight on QR login / chat instead of a
        "create admin" wall.  Returns a fresh session token when it just
        provisioned (so the caller can set the cookie), else ``None``."""
        with self.lock:
            if self.configured():
                return None
            password = secrets.token_urlsafe(24)
            user = self._new_user("local", password, "admin", [], "Local User")
            user["simple"] = True
            self.data = {
                "users": [user],
                "sessions": {},
                "simpleMode": True,
                "createdAt": _now_iso(),
                "updatedAt": _now_iso(),
            }
            token = self.create_session(user["id"])
            self._save()
            return token

    def secure_with_password(self, username: str, password: str) -> None:
        """Graduate out of simple mode: give the local user a real
        username/password so future visitors must sign in."""
        username = self._normalize_email(username)
        self._validate_password(password)
        with self.lock:
            users = self.data.get("users", [])
            target = next((u for u in users if u.get("simple")), None) or (
                users[0] if users else None
            )
            if target is None:
                raise WebError(HTTPStatus.BAD_REQUEST, "No user to secure.")
            other = self._find_user_by_username(username)
            if other and other.get("id") != target.get("id"):
                raise WebError(HTTPStatus.CONFLICT, "Username already exists.")
            salt = secrets.token_hex(16)
            target["username"] = username
            target["email"] = username
            target["salt"] = salt
            target["passwordHash"] = self._hash_password(password, salt)
            target["passwordIterations"] = self.iterations
            target["role"] = "admin"
            target["active"] = True
            target.pop("simple", None)
            target["updatedAt"] = _now_iso()
            self.data.pop("simpleMode", None)
            self._save()

    def setup(self, username: str, password: str) -> str:
        username = self._normalize_email(username)
        self._validate_password(password)
        with self.lock:
            if self.configured():
                raise WebError(HTTPStatus.CONFLICT, "Web auth is already configured.")
            user = self._new_user(username, password, "admin", [], "Admin")
            self.data = {
                "users": [user],
                "sessions": {},
                "createdAt": _now_iso(),
                "updatedAt": _now_iso(),
            }
            token = self.create_session(user["id"])
            self._save()
            return token

    def login(self, username: str, password: str, source: str = "") -> str:
        return self._login_for_portal(username, password, god_only=False, source=source)

    def login_god(self, username: str, password: str, source: str = "") -> str:
        return self._login_for_portal(username, password, god_only=True, source=source)

    def _login_for_portal(
        self, username: str, password: str, *, god_only: bool, source: str = ""
    ) -> str:
        # Sign-in lockouts are intentionally disabled. Invalid credentials still
        # receive the same generic response without blocking later valid logins.
        with self.lock:
            if not self.configured():
                raise WebError(HTTPStatus.BAD_REQUEST, "Web auth is not configured.")
            user = self._find_user_by_username(username)
            if user is None or not self._is_active_user(user):
                raise WebError(HTTPStatus.UNAUTHORIZED, "Invalid username or password.")
            is_god = self._is_god(user)
            if is_god != god_only:
                raise WebError(HTTPStatus.UNAUTHORIZED, "Invalid username or password.")
            if not self._password_matches(user, password or ""):
                raise WebError(HTTPStatus.UNAUTHORIZED, "Invalid username or password.")
            if int(user.get("passwordIterations") or self.legacy_iterations) < self.iterations:
                salt = secrets.token_hex(16)
                user["salt"] = salt
                user["passwordHash"] = self._hash_password(password or "", salt)
                user["passwordIterations"] = self.iterations
                user["updatedAt"] = _now_iso()
            token = self.create_session(str(user["id"]))
            self._save()
            return token

    def register(
        self, username: str, password: str, display_name: str = "", source: str = ""
    ) -> str:
        username = self._normalize_email(username)
        self._validate_password(password)
        if len(display_name) > 80:
            raise WebError(HTTPStatus.BAD_REQUEST, "Display name is too long.")
        with self.lock:
            self._record_registration_attempt(source)
            if not self.configured() or self.simple_mode():
                raise WebError(
                    HTTPStatus.BAD_REQUEST,
                    "Registration is available after LinePassport auth is secured.",
                    "register_unavailable",
                )
            if self._find_user_by_username(username):
                raise WebError(HTTPStatus.CONFLICT, "Email already exists.", "email_exists")
            if len(self.data.get("users", [])) >= MAX_USERS:
                raise WebError(HTTPStatus.CONFLICT, "User limit reached.", "user_quota")
            user = self._new_user(username, password, "member", [], display_name or username)
            self.data.setdefault("users", []).append(user)
            token = self.create_session(str(user["id"]))
            self._save()
            return token

    def ensure_god(self, username: str, password: str) -> dict[str, Any]:
        username = self._normalize_username(username)
        self._validate_password(password)
        with self.lock:
            user = self._find_user_by_username(username)
            if user is None:
                user = self._new_user(username, password, "god", [], "God")
                self.data.setdefault("users", []).append(user)
            else:
                salt = secrets.token_hex(16)
                user["salt"] = salt
                user["passwordHash"] = self._hash_password(password, salt)
                user["passwordIterations"] = self.iterations
                user["role"] = "god"
                user["active"] = True
                user["displayName"] = user.get("displayName") or "God"
                user["updatedAt"] = _now_iso()
            self.data.pop("simpleMode", None)
            self._save()
            return self._public_user_strict(user)

    def create_session(self, user_id: str) -> str:
        self._prune_sessions()
        token = secrets.token_urlsafe(32)
        self.data.setdefault("sessions", {})[token] = {
            "userId": user_id,
            "expiresAt": time.time() + 12 * 60 * 60,
            "createdAt": _now_iso(),
        }
        return token

    def logout(self, cookie_header: str | None, *, cookie_name: str | None = None) -> None:
        token = self._token_from_cookie(cookie_header, cookie_name=cookie_name)
        if token:
            with self.lock:
                self.data.setdefault("sessions", {}).pop(token, None)
                self._save()

    def is_authenticated(
        self, cookie_header: str | None, *, cookie_name: str | None = None
    ) -> bool:
        return self.current_user(cookie_header, cookie_name=cookie_name) is not None

    def current_user(
        self, cookie_header: str | None, *, cookie_name: str | None = None
    ) -> dict[str, Any] | None:
        token = self._token_from_cookie(cookie_header, cookie_name=cookie_name)
        if not token:
            return None
        now = time.time()
        with self.lock:
            session = self.data.setdefault("sessions", {}).get(token)
            if not isinstance(session, dict):
                return None
            if float(session.get("expiresAt") or 0) <= now:
                self.data["sessions"].pop(token, None)
                self._save()
                return None
            user = self._find_user(str(session.get("userId") or ""))
            if user is None or not self._is_active_user(user):
                self.data["sessions"].pop(token, None)
                self._save()
                return None
            return dict(user)

    def require_user(
        self, cookie_header: str | None, *, cookie_name: str | None = None
    ) -> dict[str, Any]:
        user = self.current_user(cookie_header, cookie_name=cookie_name)
        if user is None:
            raise WebError(
                HTTPStatus.UNAUTHORIZED, "Web authentication required.", "auth_required"
            )
        return user

    def status(
        self, cookie_header: str | None, *, cookie_name: str | None = None
    ) -> dict[str, Any]:
        user = self.current_user(cookie_header, cookie_name=cookie_name)
        return {
            "configured": self.configured(),
            "authenticated": user is not None,
            "simpleMode": self.simple_mode(),
            "user": self.public_user(user) if user else None,
            "roles": self.roles_payload(),
        }

    def has_permission(self, user: dict[str, Any] | None, permission: str) -> bool:
        if not user:
            return False
        role = str(user.get("role") or "")
        return permission in ROLE_DEFINITIONS.get(role, {}).get("permissions", [])

    def can_access_account(self, user: dict[str, Any] | None, account_id: str) -> bool:
        if not user or not account_id:
            return False
        if self._is_god(user):
            return True
        return account_id in set(user.get("accountIds") or []) or account_id in set(
            user.get("staffAccountIds") or []
        )

    def allowed_account_ids(self, user: dict[str, Any] | None) -> set[str] | None:
        if self._is_god(user):
            return None
        if not user:
            return set()
        return set(user.get("accountIds") or []) | set(user.get("staffAccountIds") or [])

    def owns_account(self, user: dict[str, Any] | None, account_id: str) -> bool:
        """True when ``user`` is the account owner rather than shared staff."""
        if not user or not account_id:
            return False
        if self._is_god(user):
            return True
        return account_id in set(user.get("accountIds") or [])

    # -- team (staff sharing a LINE account with its owner) -------------------
    def list_staff(self, owner: dict[str, Any]) -> list[dict[str, Any]]:
        owner_id = str(owner.get("id") or "")
        return [
            self._public_user_strict(user)
            for user in self.data.get("users", [])
            if isinstance(user, dict) and str(user.get("teamOwnerId") or "") == owner_id
        ]

    def _validated_staff_accounts(
        self, owner: dict[str, Any], account_ids: list[str]
    ) -> list[str]:
        stored_owner = self._find_user(str(owner.get("id") or "")) or owner
        owned = set(stored_owner.get("accountIds") or [])
        requested = sorted({str(item) for item in account_ids if item})
        if any(item not in owned for item in requested):
            raise WebError(
                HTTPStatus.FORBIDDEN,
                "Staff can only be given LINE accounts you own.",
                "staff_account_not_owned",
            )
        return requested

    def create_staff(
        self,
        owner: dict[str, Any],
        username: str,
        password: str,
        display_name: str,
        account_ids: list[str],
    ) -> dict[str, Any]:
        username = self._normalize_email(username)
        self._validate_password(password)
        if len(display_name) > 80:
            raise WebError(HTTPStatus.BAD_REQUEST, "Display name is too long.")
        with self.lock:
            staff_accounts = self._validated_staff_accounts(owner, account_ids)
            if self._find_user_by_username(username):
                raise WebError(HTTPStatus.CONFLICT, "Email already exists.", "email_exists")
            if len(self.data.get("users", [])) >= MAX_USERS:
                raise WebError(HTTPStatus.CONFLICT, "User limit reached.", "user_quota")
            if len(self.list_staff(owner)) >= MAX_STAFF_PER_OWNER:
                raise WebError(HTTPStatus.CONFLICT, "Staff limit reached.", "staff_quota")
            user = self._new_user(username, password, "operator", [], display_name or username)
            user["teamOwnerId"] = str(owner.get("id") or "")
            user["staffAccountIds"] = staff_accounts
            self.data.setdefault("users", []).append(user)
            self.data.pop("simpleMode", None)
            self._save()
            return self._public_user_strict(user)

    def _owned_staff(self, owner: dict[str, Any], staff_id: str) -> dict[str, Any]:
        staff = self._find_user(staff_id)
        if staff is None or str(staff.get("teamOwnerId") or "") != str(owner.get("id") or ""):
            raise WebError(HTTPStatus.NOT_FOUND, "Staff member not found.")
        return staff

    def update_staff(
        self,
        owner: dict[str, Any],
        staff_id: str,
        *,
        display_name: str | None = None,
        account_ids: list[str] | None = None,
        active: bool | None = None,
        password: str | None = None,
    ) -> dict[str, Any]:
        with self.lock:
            staff = self._owned_staff(owner, staff_id)
            if display_name is not None:
                if len(display_name) > 80:
                    raise WebError(HTTPStatus.BAD_REQUEST, "Display name is too long.")
                staff["displayName"] = display_name.strip() or staff["username"]
            if account_ids is not None:
                staff["staffAccountIds"] = self._validated_staff_accounts(owner, account_ids)
            if active is not None:
                staff["active"] = bool(active)
            if password:
                self._validate_password(password)
                salt = secrets.token_hex(16)
                staff["salt"] = salt
                staff["passwordHash"] = self._hash_password(password, salt)
                staff["passwordIterations"] = self.iterations
            staff["updatedAt"] = _now_iso()
            if password or active is False:
                self._revoke_user_sessions(staff_id)
            self._save()
            return self._public_user_strict(staff)

    def delete_staff(self, owner: dict[str, Any], staff_id: str) -> None:
        with self.lock:
            self._owned_staff(owner, staff_id)
            self.data["users"] = [
                user
                for user in self.data.get("users", [])
                if not isinstance(user, dict) or user.get("id") != staff_id
            ]
            self._revoke_user_sessions(staff_id)
            self._save()

    def grant_account_access(self, user_id: str, account_id: str) -> None:
        with self.lock:
            user = self._find_user(user_id)
            if user is None:
                raise WebError(HTTPStatus.NOT_FOUND, "User not found.")
            self._ensure_accounts_unassigned([account_id], exclude_user_id=user_id)
            account_ids = set(user.get("accountIds") or [])
            account_ids.add(account_id)
            user["accountIds"] = sorted(account_ids)
            user["updatedAt"] = _now_iso()
            self._save()

    def user_for_account(self, account_id: str) -> dict[str, Any] | None:
        for user in self.data.get("users", []):
            if isinstance(user, dict) and account_id in set(user.get("accountIds") or []):
                return dict(user)
        return None

    def require_permission(self, user: dict[str, Any] | None, permission: str) -> None:
        if not self.has_permission(user, permission):
            raise WebError(HTTPStatus.FORBIDDEN, "Permission denied.", "forbidden")

    def list_users(self) -> list[dict[str, Any]]:
        return [self._public_user_strict(user) for user in self.data.get("users", [])]

    def create_user(
        self,
        username: str,
        password: str,
        role: str,
        account_ids: list[str],
        display_name: str = "",
        actor: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        username = self._normalize_email(username)
        self._validate_password(password)
        self._validate_role(role)
        if len(display_name) > 80:
            raise WebError(HTTPStatus.BAD_REQUEST, "Display name is too long.")
        if account_ids:
            raise WebError(
                HTTPStatus.BAD_REQUEST,
                "Users must add their own LINE accounts.",
                "account_self_service_only",
            )
        if role == "god" and not self._is_god(actor):
            raise WebError(HTTPStatus.FORBIDDEN, "Only God can create God users.")
        with self.lock:
            self._ensure_accounts_unassigned(account_ids)
            if self._find_user_by_username(username):
                raise WebError(HTTPStatus.CONFLICT, "Email already exists.", "email_exists")
            if len(self.data.get("users", [])) >= MAX_USERS:
                raise WebError(HTTPStatus.CONFLICT, "User limit reached.", "user_quota")
            user = self._new_user(
                username, password, role, account_ids, display_name or username
            )
            self.data.setdefault("users", []).append(user)
            # Adding a real user means multi-user access is now in play: leave
            # simple (unsecured) mode so future visitors are prompted to sign in.
            self.data.pop("simpleMode", None)
            self._save()
            return self._public_user_strict(user)

    def update_user(
        self,
        user_id: str,
        *,
        username: str | None = None,
        email: str | None = None,
        display_name: str | None = None,
        role: str | None = None,
        account_ids: list[str] | None = None,
        active: bool | None = None,
        password: str | None = None,
        actor: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        with self.lock:
            user = self._find_user(user_id)
            if user is None:
                raise WebError(HTTPStatus.NOT_FOUND, "User not found.")
            actor_is_god = self._is_god(actor)
            if user.get("role") == "god" and not actor_is_god:
                raise WebError(HTTPStatus.FORBIDDEN, "Only God can manage God users.")
            if role == "god" and not actor_is_god:
                raise WebError(HTTPStatus.FORBIDDEN, "Only God can assign the God role.")
            if actor_is_god and user_id == str((actor or {}).get("id") or ""):
                if role is not None and role != "god":
                    raise WebError(HTTPStatus.BAD_REQUEST, "God cannot demote itself.")
                if active is False:
                    raise WebError(HTTPStatus.BAD_REQUEST, "God cannot disable itself.")
            original = dict(user)
            requested_email = email if email is not None else username
            if requested_email is not None:
                normalized = self._normalize_email(requested_email)
                existing = self._find_user_by_username(normalized)
                if existing and existing.get("id") != user_id:
                    raise WebError(
                        HTTPStatus.CONFLICT, "Email already exists.", "email_exists"
                    )
                user["username"] = normalized
                user["email"] = normalized
            if display_name is not None:
                if len(display_name) > 80:
                    raise WebError(HTTPStatus.BAD_REQUEST, "Display name is too long.")
                user["displayName"] = (display_name or "").strip() or user["username"]
            if role is not None:
                self._validate_role(role)
                user["role"] = role
            if account_ids is not None:
                requested_accounts = {str(a) for a in account_ids if a}
                if requested_accounts != set(user.get("accountIds") or []):
                    raise WebError(
                        HTTPStatus.BAD_REQUEST,
                        "LINE account ownership is managed by each user.",
                        "account_self_service_only",
                    )
            if active is not None:
                user["active"] = bool(active)
            if password:
                self._validate_password(password)
                salt = secrets.token_hex(16)
                user["salt"] = salt
                user["passwordHash"] = self._hash_password(password, salt)
                user["passwordIterations"] = self.iterations
            user["updatedAt"] = _now_iso()
            if not self._has_active_administrator(self.data.get("users", [])):
                user.clear()
                user.update(original)
                raise WebError(
                    HTTPStatus.BAD_REQUEST,
                    "At least one active God or Admin is required.",
                )
            if any(
                item.get("role") == "god" for item in self.data.get("users", [])
            ) and not any(
                item.get("role") == "god" and item.get("active", True)
                for item in self.data.get("users", [])
            ):
                user.clear()
                user.update(original)
                raise WebError(HTTPStatus.BAD_REQUEST, "At least one active God is required.")
            if password or active is False:
                self._revoke_user_sessions(user_id)
            self._save()
            return self._public_user_strict(user)

    def delete_user(
        self,
        user_id: str,
        current_user_id: str | None = None,
        actor: dict[str, Any] | None = None,
    ) -> None:
        with self.lock:
            updated = self.data_after_user_delete(user_id, current_user_id, actor)
            previous = self.data
            self.data = updated
            try:
                self._save()
            except Exception:
                self.data = previous
                raise

    def data_after_user_delete(
        self,
        user_id: str,
        current_user_id: str | None = None,
        actor: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        with self.lock:
            if user_id == current_user_id:
                raise WebError(HTTPStatus.BAD_REQUEST, "You cannot delete your own user.")
            target = self._find_user(user_id)
            if target and target.get("role") == "god" and not self._is_god(actor):
                raise WebError(HTTPStatus.FORBIDDEN, "Only God can delete God users.")
            users = [
                copy.deepcopy(user)
                for user in self.data.get("users", [])
                if user.get("id") != user_id
            ]
            if len(users) == len(self.data.get("users", [])):
                raise WebError(HTTPStatus.NOT_FOUND, "User not found.")
            if not self._has_active_administrator(users):
                raise WebError(
                    HTTPStatus.BAD_REQUEST,
                    "At least one active God or Admin is required.",
                )
            had_god = any(item.get("role") == "god" for item in self.data.get("users", []))
            has_active_god = any(
                item.get("role") == "god" and item.get("active", True) for item in users
            )
            if had_god and not has_active_god:
                raise WebError(HTTPStatus.BAD_REQUEST, "At least one active God is required.")
            updated = copy.deepcopy(self.data)
            updated["users"] = users
            updated["sessions"] = {
                token: copy.deepcopy(session)
                for token, session in self.data.get("sessions", {}).items()
                if session.get("userId") != user_id
            }
            return updated

    def change_password(
        self, user: dict[str, Any], current_password: str, new_password: str
    ) -> str:
        self._validate_password(new_password)
        with self.lock:
            stored = self._find_user(str(user.get("id") or ""))
            if stored is None:
                raise WebError(HTTPStatus.NOT_FOUND, "User not found.")
            if not self._password_matches(stored, current_password or ""):
                raise WebError(HTTPStatus.UNAUTHORIZED, "Current password is incorrect.")
            new_salt = secrets.token_hex(16)
            stored["salt"] = new_salt
            stored["passwordHash"] = self._hash_password(new_password, new_salt)
            stored["passwordIterations"] = self.iterations
            stored["updatedAt"] = _now_iso()
            self._revoke_user_sessions(str(stored.get("id") or ""))
            token = self.create_session(str(stored.get("id") or ""))
            self._save()
            return token

    def remove_account_access(self, account_id: str) -> None:
        with self.lock:
            changed = False
            for user in self.data.get("users", []):
                if _strip_account_from_user(user, {account_id}):
                    changed = True
            if changed:
                self._save()

    @classmethod
    def cookie_header(
        cls, token: str, *, cookie_name: str | None = None, secure: bool = False
    ) -> str:
        name = cookie_name or cls.cookie_name
        secure_part = "; Secure" if secure else ""
        return f"{name}={token}; Path=/; HttpOnly; SameSite=Lax; Max-Age=43200{secure_part}"

    @classmethod
    def clear_cookie_header(
        cls, *, cookie_name: str | None = None, secure: bool = False
    ) -> str:
        name = cookie_name or cls.cookie_name
        secure_part = "; Secure" if secure else ""
        return f"{name}=; Path=/; HttpOnly; SameSite=Lax; Max-Age=0{secure_part}"

    @classmethod
    def _token_from_cookie(
        cls, cookie_header: str | None, *, cookie_name: str | None = None
    ) -> str:
        if not cookie_header:
            return ""
        cookie = SimpleCookie()
        try:
            cookie.load(cookie_header)
        except Exception:
            return ""
        morsel = cookie.get(cookie_name or cls.cookie_name)
        return morsel.value if morsel else ""

    @classmethod
    def _hash_password(cls, password: str, salt: str, iterations: int | None = None) -> str:
        digest = hashlib.pbkdf2_hmac(
            "sha256",
            password.encode("utf-8"),
            salt.encode("ascii"),
            iterations or cls.iterations,
        )
        return digest.hex()

    def _password_matches(self, user: dict[str, Any], password: str) -> bool:
        expected = str(user.get("passwordHash") or "")
        salt = str(user.get("salt") or "")
        iterations = int(user.get("passwordIterations") or self.legacy_iterations)
        actual = self._hash_password(password, salt, iterations)
        return bool(expected and salt and hmac.compare_digest(expected, actual))

    def _prune_sessions(self) -> None:
        now = time.time()
        sessions = self.data.setdefault("sessions", {})
        self.data["sessions"] = {
            token: session
            for token, session in sessions.items()
            if isinstance(session, dict) and float(session.get("expiresAt") or 0) > now
        }

    def _revoke_user_sessions(self, user_id: str) -> None:
        self.data["sessions"] = {
            token: session
            for token, session in self.data.setdefault("sessions", {}).items()
            if not isinstance(session, dict) or str(session.get("userId") or "") != user_id
        }

    def _check_login_rate_limit(self, key: str) -> None:
        cutoff = time.time() - self.login_window_seconds
        failures = [stamp for stamp in self.login_failures.get(key, []) if stamp > cutoff]
        self.login_failures[key] = failures
        if len(failures) >= self.login_max_failures:
            raise WebError(
                HTTPStatus.TOO_MANY_REQUESTS,
                "Too many failed sign-in attempts. Try again later.",
                "login_rate_limited",
            )

    def _record_login_failure(self, key: str) -> None:
        self.login_failures.setdefault(key, []).append(time.time())

    def _record_registration_attempt(self, source: str) -> None:
        if not source:
            return
        key = (source or "local").strip().casefold()
        cutoff = time.time() - self.registration_window_seconds
        attempts = [
            stamp for stamp in self.registration_attempts.get(key, []) if stamp > cutoff
        ]
        if len(attempts) >= self.registration_max_attempts:
            raise WebError(
                HTTPStatus.TOO_MANY_REQUESTS,
                "Too many registration attempts. Try again later.",
                "rate_limited",
            )
        attempts.append(time.time())
        self.registration_attempts[key] = attempts

    @classmethod
    def roles_payload(cls) -> dict[str, Any]:
        return {
            role: {
                "label": data["label"],
                "permissions": list(data["permissions"]),
            }
            for role, data in ROLE_DEFINITIONS.items()
        }

    @classmethod
    def _public_user_strict(cls, user: dict[str, Any]) -> dict[str, Any]:
        result = cls.public_user(user)
        assert result is not None  # a concrete user always yields a payload
        return result

    @classmethod
    def public_user(cls, user: dict[str, Any] | None) -> dict[str, Any] | None:
        if user is None:
            return None
        return {
            "id": user.get("id"),
            "username": user.get("username"),
            "email": user.get("email") or cls._email_or_empty(str(user.get("username") or "")),
            "displayName": user.get("displayName") or user.get("username"),
            "role": user.get("role"),
            "permissions": list(
                ROLE_DEFINITIONS.get(str(user.get("role")), {}).get("permissions", [])
            ),
            "accountIds": list(user.get("accountIds") or []),
            "staffAccountIds": list(user.get("staffAccountIds") or []),
            "teamOwnerId": user.get("teamOwnerId") or "",
            "active": bool(user.get("active", True)),
            "createdAt": user.get("createdAt"),
            "updatedAt": user.get("updatedAt"),
        }

    def _new_user(
        self,
        username: str,
        password: str,
        role: str,
        account_ids: list[str],
        display_name: str,
    ) -> dict[str, Any]:
        salt = secrets.token_hex(16)
        return {
            "id": uuid.uuid4().hex,
            "username": username,
            "email": self._email_or_empty(username),
            "displayName": display_name.strip() or username,
            "role": role,
            "salt": salt,
            "passwordHash": self._hash_password(password, salt),
            "passwordIterations": self.iterations,
            "accountIds": sorted({str(a) for a in account_ids if a}),
            "active": True,
            "createdAt": _now_iso(),
            "updatedAt": _now_iso(),
        }

    def _find_user(self, user_id: str) -> dict[str, Any] | None:
        for user in self.data.get("users", []):
            if isinstance(user, dict) and user.get("id") == user_id:
                return user
        return None

    def _ensure_accounts_unassigned(
        self, account_ids: list[str], *, exclude_user_id: str | None = None
    ) -> None:
        requested = {str(account_id) for account_id in account_ids if account_id}
        if not requested:
            return
        for user in self.data.get("users", []):
            if not isinstance(user, dict) or user.get("id") == exclude_user_id:
                continue
            if requested.intersection(user.get("accountIds") or []):
                raise WebError(
                    HTTPStatus.CONFLICT,
                    "A LINE account can belong to only one user.",
                    "account_already_owned",
                )

    def _find_user_by_username(self, username: str) -> dict[str, Any] | None:
        normalized = (username or "").strip().lower()
        for user in self.data.get("users", []):
            if not isinstance(user, dict):
                continue
            if str(user.get("username") or "").lower() == normalized:
                return user
            if str(user.get("email") or "").lower() == normalized:
                return user
        return None

    @staticmethod
    def _is_active_user(user: dict[str, Any]) -> bool:
        return bool(
            user.get("active", True) and user.get("username") and user.get("passwordHash")
        )

    @staticmethod
    def _is_god(user: dict[str, Any] | None) -> bool:
        return bool(user and user.get("role") == "god" and user.get("active", True))

    @staticmethod
    def _has_active_administrator(users: list[dict[str, Any]]) -> bool:
        return any(
            user.get("role") in {"god", "admin"} and user.get("active", True) for user in users
        )

    @staticmethod
    def _normalize_username(username: str) -> str:
        username = (username or "").strip().lower()
        if not re.fullmatch(r"[a-z0-9_.@-]{3,64}", username):
            raise WebError(
                HTTPStatus.BAD_REQUEST,
                "Username must be 3-64 characters: letters, numbers, dot, dash, underscore, or @.",
            )
        return username

    @staticmethod
    def _normalize_email(email: str) -> str:
        email = (email or "").strip().lower()
        if len(email) > 254 or email.count("@") != 1:
            raise WebError(
                HTTPStatus.BAD_REQUEST, "Enter a valid email address.", "email_invalid"
            )
        local, domain = email.split("@", 1)
        local_ok = bool(
            local
            and len(local) <= 64
            and not local.startswith(".")
            and not local.endswith(".")
            and ".." not in local
            and re.fullmatch(r"[a-z0-9.!#$%&'*+/=?^_`{|}~-]+", local)
        )
        domain_ok = bool(
            re.fullmatch(
                r"(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}",
                domain,
            )
        )
        if not local_ok or not domain_ok:
            raise WebError(
                HTTPStatus.BAD_REQUEST, "Enter a valid email address.", "email_invalid"
            )
        return email

    @classmethod
    def _email_or_empty(cls, value: str) -> str:
        try:
            return cls._normalize_email(value)
        except WebError:
            return ""

    @staticmethod
    def _validate_password(password: str) -> None:
        if len(password or "") < 8:
            raise WebError(
                HTTPStatus.BAD_REQUEST,
                "Password must be at least 8 characters.",
                "password_too_short",
            )
        if len(password) > 128:
            raise WebError(
                HTTPStatus.BAD_REQUEST,
                "Password must not exceed 128 characters.",
                "password_too_long",
            )

    @staticmethod
    def _validate_role(role: str) -> None:
        if role not in ROLE_DEFINITIONS:
            raise WebError(HTTPStatus.BAD_REQUEST, "Unknown role.")


class AccountStore:
    def __init__(self, config: WebConfig, store: StateStore) -> None:
        self.config = config
        self.store = store
        self.lock = threading.RLock()
        self.data = self._load()
        self._bootstrap_legacy()

    def _load(self) -> dict[str, Any]:
        data = self.store.get("accounts", {"accounts": []})
        if not isinstance(data, dict):
            data = {"accounts": []}
        accounts = data.get("accounts")
        if not isinstance(accounts, list):
            data["accounts"] = []
        return data

    def _bootstrap_legacy(self) -> None:
        with self.lock:
            accounts = self.data.setdefault("accounts", [])
            has_default = any(
                a.get("id") == "default" for a in accounts if isinstance(a, dict)
            )
            if os.path.exists(self.config.tokens_file) and not has_default:
                accounts.append(
                    {
                        "id": "default",
                        "label": "Default",
                        "tokenFile": self.config.tokens_file,
                        "mid": None,
                        "userid": None,
                        "createdAt": _now_iso(),
                        "updatedAt": _now_iso(),
                    }
                )
            if accounts and not self.data.get("activeAccountId"):
                self.data["activeAccountId"] = accounts[0].get("id")
            self.save()

    def save(self) -> None:
        self.store.set("accounts", self.data)

    def list_accounts(self, allowed_ids: set[str] | None = None) -> list[dict[str, Any]]:
        with self.lock:
            out = []
            for account in self.data.get("accounts", []):
                if not isinstance(account, dict):
                    continue
                if allowed_ids is not None and account.get("id") not in allowed_ids:
                    continue
                out.append(self._public_fields(dict(account), account))
            return out

    def active_id(self) -> str | None:
        with self.lock:
            active = self.data.get("activeAccountId")
            if active and self.get(active):
                return str(active)
            accounts = self.list_accounts()
            return accounts[0]["id"] if accounts else None

    def get(self, account_id: str | None) -> dict[str, Any] | None:
        if not account_id:
            return None
        with self.lock:
            for account in self.data.get("accounts", []):
                if isinstance(account, dict) and account.get("id") == account_id:
                    return dict(account)
        return None

    def set_active(self, account_id: str) -> dict[str, Any]:
        with self.lock:
            account = self.get(account_id)
            if account is None:
                raise WebError(HTTPStatus.NOT_FOUND, "Account not found.")
            self.data["activeAccountId"] = account_id
            self.save()
            return self._public_fields(dict(account), account)

    @staticmethod
    def _session_state(account: dict[str, Any]) -> str:
        explicit = str(account.get("sessionState") or "").strip().lower()
        if explicit == "reauth_required":
            return explicit
        token_file = str(account.get("tokenFile") or "")
        if _account_channel(account) != "line":
            token_file = str(account.get("credentialFile") or "")
        return "connected" if token_file and os.path.exists(token_file) else "missing"

    @staticmethod
    def _public_fields(item: dict[str, Any], account: dict[str, Any]) -> dict[str, Any]:
        """Add derived fields and drop anything secret from an account copy."""
        channel = _account_channel(account)
        secret_file = str(
            account.get("tokenFile") if channel == "line" else account.get("credentialFile")
        ) if (account.get("tokenFile") or account.get("credentialFile")) else ""
        item["channel"] = channel
        item["capabilities"] = list(ACCOUNT_CAPABILITIES.get(channel, []))
        item["tokenFileExists"] = bool(secret_file and os.path.exists(secret_file))
        item["sessionState"] = AccountStore._session_state(account)
        item["proxyConfigured"] = bool(item.pop("proxyUrl", None))
        item.pop("tokenFile", None)
        item.pop("credentialFile", None)
        return item

    def add_channel_account(self, record: dict[str, Any], owner_id: str) -> dict[str, Any]:
        """Append a non-LINE account (caller persists accounts + auth together)."""
        with self.lock:
            owned = sum(
                1
                for account in self.data.get("accounts", [])
                if isinstance(account, dict) and str(account.get("ownerId") or "") == owner_id
            )
            if owned >= MAX_ACCOUNTS_PER_USER:
                raise WebError(
                    HTTPStatus.CONFLICT,
                    f"Each user can have at most {MAX_ACCOUNTS_PER_USER} accounts.",
                    "account_quota",
                )
            existing = {
                a.get("id") for a in self.data.get("accounts", []) if isinstance(a, dict)
            }
            base = str(record["id"])
            account_id = base
            suffix = 2
            while account_id in existing:
                account_id = f"{base}-{suffix}"
                suffix += 1
            account = {**record, "id": account_id, "ownerId": owner_id}
            self.data.setdefault("accounts", []).append(account)
            return dict(account)

    def session_state(self, account_id: str) -> str:
        account = self.get(account_id)
        return self._session_state(account) if account is not None else "missing"

    def requires_reauth(self, account_id: str) -> bool:
        return self.session_state(account_id) == "reauth_required"

    def mark_session_reauth_required(self, account_id: str, detail: str = "") -> bool:
        """Persist a revoked-session marker; return True only on transition."""
        with self.lock:
            for account in self.data.get("accounts", []):
                if not isinstance(account, dict) or account.get("id") != account_id:
                    continue
                changed = account.get("sessionState") != "reauth_required"
                account["sessionState"] = "reauth_required"
                account["sessionError"] = _short_text(detail, 500)
                account["sessionErrorAt"] = _now_iso()
                account["updatedAt"] = _now_iso()
                self.save()
                return changed
        return False

    def mark_session_connected(self, account_id: str) -> None:
        with self.lock:
            for account in self.data.get("accounts", []):
                if not isinstance(account, dict) or account.get("id") != account_id:
                    continue
                changed = bool(
                    account.get("sessionState")
                    or account.get("sessionError")
                    or account.get("sessionErrorAt")
                )
                account["sessionState"] = "connected"
                account.pop("sessionError", None)
                account.pop("sessionErrorAt", None)
                if changed:
                    account["updatedAt"] = _now_iso()
                    self.save()
                return

    def update_profile(self, account_id: str, profile: dict[str, Any]) -> None:
        with self.lock:
            for account in self.data.get("accounts", []):
                if isinstance(account, dict) and account.get("id") == account_id:
                    account["label"] = profile.get("displayName") or account.get("label")
                    account["mid"] = profile.get("mid") or account.get("mid")
                    account["userid"] = profile.get("userid") or account.get("userid")
                    if "picturePath" in profile:
                        if profile.get("picturePath"):
                            account["picturePath"] = profile.get("picturePath")
                        else:
                            account.pop("picturePath", None)
                    if "pictureStatus" in profile:
                        if profile.get("pictureStatus"):
                            account["pictureStatus"] = profile.get("pictureStatus")
                        else:
                            account.pop("pictureStatus", None)
                    account["sessionState"] = "connected"
                    account.pop("sessionError", None)
                    account.pop("sessionErrorAt", None)
                    account["updatedAt"] = _now_iso()
                    self.save()
                    return

    def update_label(self, account_id: str, label: str) -> dict[str, Any]:
        label = (label or "").strip()
        if not label:
            raise WebError(HTTPStatus.BAD_REQUEST, "Account name is required.")
        if len(label) > MAX_NAME_LENGTH:
            raise WebError(HTTPStatus.BAD_REQUEST, "Account name is too long.")
        with self.lock:
            for account in self.data.get("accounts", []):
                if isinstance(account, dict) and account.get("id") == account_id:
                    account["label"] = label
                    account["updatedAt"] = _now_iso()
                    self.save()
                    return dict(account)
        raise WebError(HTTPStatus.NOT_FOUND, "Account not found.")

    def update_settings(
        self,
        account_id: str,
        label: str,
        *,
        proxy_enabled: bool | None = None,
        encrypted_proxy_url: str | None = None,
    ) -> dict[str, Any]:
        label = (label or "").strip()
        if not label:
            raise WebError(HTTPStatus.BAD_REQUEST, "Account name is required.")
        if len(label) > MAX_NAME_LENGTH:
            raise WebError(HTTPStatus.BAD_REQUEST, "Account name is too long.")
        with self.lock:
            for account in self.data.get("accounts", []):
                if not isinstance(account, dict) or account.get("id") != account_id:
                    continue
                account["label"] = label
                if proxy_enabled is False:
                    account.pop("proxyUrl", None)
                elif proxy_enabled is True:
                    if encrypted_proxy_url:
                        account["proxyUrl"] = encrypted_proxy_url
                    elif not account.get("proxyUrl"):
                        raise WebError(
                            HTTPStatus.BAD_REQUEST,
                            "Proxy URL is required when proxy is enabled.",
                            "proxy_url_required",
                        )
                account["updatedAt"] = _now_iso()
                self.save()
                return dict(account)
        raise WebError(HTTPStatus.NOT_FOUND, "Account not found.")

    def add_from_api(
        self,
        api: OkLine,
        profile: dict[str, Any],
        requested_label: str | None,
        owner_id: str,
        *,
        encrypted_proxy_url: str | None = None,
        persist: bool = True,
        token_writer: Callable[[OkLine, str], None] | None = None,
    ) -> dict[str, Any]:
        label = (requested_label or profile.get("displayName") or "Line Account").strip()
        if len(label) > MAX_NAME_LENGTH:
            label = label[:MAX_NAME_LENGTH]
        mid = str(profile.get("mid") or uuid.uuid4().hex)
        base = _safe_slug(label) + "-" + _safe_slug(mid[-8:], "line")
        with self.lock:
            owned = sum(
                1
                for account in self.data.get("accounts", [])
                if isinstance(account, dict) and str(account.get("ownerId") or "") == owner_id
            )
            if owned >= MAX_ACCOUNTS_PER_USER:
                raise WebError(
                    HTTPStatus.CONFLICT,
                    f"Each user can have at most {MAX_ACCOUNTS_PER_USER} LINE accounts.",
                    "account_quota",
                )
            existing = {
                a.get("id") for a in self.data.get("accounts", []) if isinstance(a, dict)
            }
            account_id = base
            suffix = 2
            while account_id in existing:
                account_id = f"{base}-{suffix}"
                suffix += 1
            os.makedirs(self.config.accounts_dir, exist_ok=True)
            token_file = str(Path(self.config.accounts_dir) / f"{account_id}.tokens.json")
            if token_writer is None:
                api.save_tokens(token_file)
            else:
                token_writer(api, token_file)
            account = {
                "id": account_id,
                "label": label,
                "tokenFile": token_file,
                "mid": profile.get("mid"),
                "userid": profile.get("userid"),
                "picturePath": profile.get("picturePath"),
                "pictureStatus": profile.get("pictureStatus"),
                "ownerId": owner_id,
                "sessionState": "connected",
                "createdAt": _now_iso(),
                "updatedAt": _now_iso(),
            }
            if encrypted_proxy_url:
                account["proxyUrl"] = encrypted_proxy_url
            self.data.setdefault("accounts", []).append(account)
            self.data["activeAccountId"] = account_id
            if persist:
                try:
                    self.save()
                except Exception:
                    self.data["accounts"].remove(account)
                    if os.path.exists(token_file):
                        os.remove(token_file)
                    raise
            return dict(account)

    def remove(self, account_id: str, *, delete_file: bool = True) -> dict[str, Any]:
        with self.lock:
            updated, found = self.data_after_remove(account_id)
            previous = self.data
            self.data = updated
            try:
                self.save()
            except Exception:
                self.data = previous
                raise
        token_file = found.get("tokenFile")
        if delete_file and token_file and os.path.exists(token_file):
            os.remove(token_file)
        return dict(found)

    def data_after_remove(self, account_id: str) -> tuple[dict[str, Any], dict[str, Any]]:
        with self.lock:
            updated = copy.deepcopy(self.data)
            accounts = updated.get("accounts", [])
            found = None
            kept = []
            for account in accounts:
                if isinstance(account, dict) and account.get("id") == account_id:
                    found = account
                else:
                    kept.append(account)
            if found is None:
                raise WebError(HTTPStatus.NOT_FOUND, "Account not found.")
            updated["accounts"] = kept
            if updated.get("activeAccountId") == account_id:
                updated["activeAccountId"] = kept[0].get("id") if kept else None
            return updated, found


class SessionKeeper:
    """Refreshes LINE access tokens before they expire (they last ~7 days)."""

    def __init__(self, state: WebState) -> None:
        self.state = state
        self.stop_event = threading.Event()
        self.thread = threading.Thread(
            target=self._run, name="linepassport-session-keeper", daemon=True
        )
        self.thread.start()

    def close(self) -> None:
        self.stop_event.set()
        self.thread.join(timeout=2.0)

    def _run(self) -> None:
        # Shortly after start-up (a deploy restarts the app), then periodically.
        delay = SESSION_KEEPER_FIRST_RUN_SECONDS
        while not self.stop_event.wait(delay):
            delay = SESSION_KEEPER_INTERVAL_SECONDS
            try:
                self.state.keep_sessions_fresh()
            except Exception:
                traceback.print_exc()


class ScheduleEngine:
    def __init__(self, state: WebState) -> None:
        self.state = state
        self.stop_event = threading.Event()
        self.thread = threading.Thread(
            target=self._run, name="okline-web-scheduler", daemon=True
        )
        self.thread.start()

    def close(self) -> None:
        self.stop_event.set()
        self.thread.join(timeout=2.0)

    def _run(self) -> None:
        while not self.stop_event.wait(10.0):
            try:
                self.state.run_due_schedules()
            except Exception:
                traceback.print_exc()


class OpsWatcher:
    """Follows one account's LINE operation stream and refreshes its inbox."""

    def __init__(self, state: WebState, account_id: str) -> None:
        self.state = state
        self.account_id = account_id
        self.stop_event = threading.Event()
        self.connected = False
        self.last_event_at = 0.0
        self.failures = 0
        self.disabled_until = 0.0
        self.thread = threading.Thread(
            target=self._run, name=f"linepassport-ops-{account_id[:12]}", daemon=True
        )
        self.thread.start()

    def healthy(self) -> bool:
        return self.connected and time.monotonic() - self.last_event_at < OPS_HEALTHY_SECONDS

    def stop(self) -> None:
        self.stop_event.set()

    def _run(self) -> None:
        while not self.stop_event.is_set():
            if time.monotonic() < self.disabled_until:
                self.stop_event.wait(30.0)
                continue
            try:
                api = self.state.get_api(self.account_id)
                for event in api.ops.stream(reconnect=False):
                    if self.stop_event.is_set():
                        return
                    self.connected = True
                    self.failures = 0
                    self.last_event_at = time.monotonic()
                    if event.event not in {"ping", "connInfoRevision"}:
                        self.state.request_inbox_refresh(self.account_id)
            except Exception:
                self.failures += 1
            finally:
                self.connected = False
            if self.failures >= OPS_FAILURE_LIMIT:
                # Fall back to plain polling for a while instead of hammering LINE.
                self.failures = 0
                self.disabled_until = time.monotonic() + OPS_DISABLE_SECONDS
            self.stop_event.wait(min(60.0, 5.0 * self.failures) or 2.0)


class AiAutoReplyEngine:
    def __init__(self, state: WebState) -> None:
        self.state = state
        self.stop_event = threading.Event()
        self.thread = threading.Thread(
            target=self._run, name="linepassport-ai-auto-reply", daemon=True
        )
        self.thread.start()

    def close(self) -> None:
        self.stop_event.set()
        self.thread.join(timeout=2.0)

    def _run(self) -> None:
        while not self.stop_event.wait(AI_AUTO_REPLY_POLL_SECONDS):
            try:
                self.state.poll_ai_auto_replies()
            except Exception:
                traceback.print_exc()


class WebState:
    def __init__(self, config: WebConfig) -> None:
        self.config = config
        _ensure_private_directory(config.state_dir)
        _ensure_private_directory(config.accounts_dir)
        self.lock = threading.RLock()
        self.api_locks: dict[str, threading.RLock] = {}
        self.inbox_snapshot_lock = threading.RLock()
        self.inbox_snapshots: dict[str, tuple[float, dict[str, Any]]] = {}
        self.api_rate_lock = threading.RLock()
        self.api_rate_events: dict[tuple[str, ...], list[float]] = {}
        self.store = _make_state_store(config)
        self.secret_cipher = self._load_secret_cipher()
        self._migrate_stored_secrets()
        self.web_auth = WebAuth(self.store)
        self.account_store = AccountStore(config, self.store)
        self._migrate_tenant_data()
        self.apis: dict[str, OkLine] = {}
        self.logins: dict[str, dict[str, Any]] = {"": {"state": "idle"}}
        self.schedule_lock = threading.RLock()
        self.incoming_api_lock = threading.RLock()
        self.ai_auto_reply_lock = threading.RLock()
        self.incoming_api_rate: dict[str, list[float]] = {}
        self.ai_auto_reply_inflight: set[tuple[str, str]] = set()
        self.ai_auto_reply_runtime: dict[str, dict[str, Any]] = {}
        self.ai_auto_reply_rate_events: dict[tuple[str, ...], list[float]] = {}
        self.ai_auto_reply_identity_cache: dict[
            tuple[str, str], tuple[float, str]
        ] = {}
        # Server-side inbox tracking shared by AI auto-reply, KPI and live events.
        self.room_state_lock = threading.RLock()
        self.outgoing_attribution: dict[tuple[str, str], tuple[float, str]] = {}
        self.inbox_refreshed_at: dict[str, float] = {}
        self.inbox_signatures: dict[str, str] = {}
        self.inbox_events = threading.Condition()
        self.inbox_versions: dict[str, int] = {}
        self.crm_versions: dict[str, int] = {}
        self.inbox_watchers: dict[str, float] = {}
        self.ops_watchers: dict[str, OpsWatcher] = {}
        self.ops_refresh_pending: set[str] = set()
        self.ops_refresh_executor = ThreadPoolExecutor(
            max_workers=2, thread_name_prefix="linepassport-ops-refresh"
        )
        self.push_lock = threading.RLock()
        self.vapid_keys: VapidKeys | None = None
        self.push_subscriptions_cache: list[dict[str, Any]] | None = None
        self.push_pending: dict[tuple[str, str], float] = {}
        self.push_last_sent: dict[tuple[str, str, str], float] = {}
        self.push_recent: dict[str, list[float]] = {}
        self.push_digest_at: dict[str, float] = {}
        self.push_executor = ThreadPoolExecutor(
            max_workers=2, thread_name_prefix="linepassport-push"
        )
        self.room_states_cache: dict[str, dict[str, dict[str, Any]]] = {}
        self.presence_cache: list[dict[str, Any]] | None = None
        self.presence_lock = threading.RLock()
        self.presence_current: dict[str, dict[str, Any]] = {}
        self.presence_saved_at: dict[str, float] = {}
        self.schedule_send_cache: dict[str, list[float]] = {}
        self.schedules: list[dict[str, Any]] = self._load_schedules()
        self.schedule_inflight: set[str] = set()
        self.schedule_executor = ThreadPoolExecutor(
            max_workers=4, thread_name_prefix="linepassport-schedule"
        )
        self.ai_auto_reply_executor = ThreadPoolExecutor(
            max_workers=2, thread_name_prefix="linepassport-ai-reply"
        )
        # Customer records (CRM): fed from the inbox, written by one worker thread.
        self.crm = CrmService(_make_crm_database(config), self)
        self.crm_cursors: dict[str, dict[str, int]] = {}
        self.crm_executor = ThreadPoolExecutor(
            max_workers=1, thread_name_prefix="linepassport-crm-ingest"
        )
        self.crm_engine = CrmEngine(self.crm, self)
        # Staff alerts on Telegram (one bot per shop, linked per person).
        self.staff_notifier = StaffNotifier(self)
        # Telegram bots added as customer chat accounts.
        self.telegram = TelegramChannels(self)
        # Personal Telegram accounts (MTProto), and their sign-ins in progress.
        self.telegram_users = TelegramUsers(self)
        for account in self.account_store.list_accounts():
            if account.get("sessionState") != "connected":
                continue
            if account.get("channel") == "telegram_bot":
                self.telegram.start(str(account["id"]))
            elif account.get("channel") == "telegram_user":
                self.telegram_users.start(str(account["id"]))
        self.scheduler = ScheduleEngine(self)
        self.ai_auto_reply_engine = AiAutoReplyEngine(self)
        self.session_refresh_attempts: dict[str, float] = {}
        self.session_keeper = SessionKeeper(self)

    def _consume_api_rate_limit(
        self,
        key: tuple[str, ...],
        *,
        limit: int,
        window_seconds: float,
    ) -> None:
        now = time.monotonic()
        cutoff = now - window_seconds
        with self.api_rate_lock:
            recent = [stamp for stamp in self.api_rate_events.get(key, []) if stamp > cutoff]
            if len(recent) >= limit:
                retry_after = max(1, math.ceil(recent[0] + window_seconds - now))
                self.api_rate_events[key] = recent
                raise WebError(
                    HTTPStatus.TOO_MANY_REQUESTS,
                    "API rate limit exceeded.",
                    "api_rate_limited",
                    headers=[("Retry-After", str(retry_after))],
                )
            recent.append(now)
            self.api_rate_events[key] = recent
            if len(self.api_rate_events) > 4096:
                stale_before = now - 300.0
                self.api_rate_events = {
                    item_key: stamps
                    for item_key, stamps in self.api_rate_events.items()
                    if stamps and stamps[-1] > stale_before
                }

    def enforce_api_rate_limit(
        self,
        user: dict[str, Any],
        method: str,
        path: str,
        account_id: str = "",
    ) -> None:
        user_id = str(user.get("id") or user.get("username") or "anonymous")
        self._consume_api_rate_limit(
            ("user", user_id),
            limit=MAX_AUTHENTICATED_API_REQUESTS_PER_MINUTE,
            window_seconds=60.0,
        )
        route_limit = AUTHENTICATED_API_RATE_LIMITS.get((method.upper(), path))
        if route_limit is None:
            return
        limit, window_seconds = route_limit
        self._consume_api_rate_limit(
            ("route", user_id, account_id or "-", method.upper(), path),
            limit=limit,
            window_seconds=window_seconds,
        )

    def setup_token_required(self) -> bool:
        return not _is_loopback_bind(self.config.host)

    def _load_secret_cipher(self) -> Fernet:
        configured = str(os.getenv("LINEPASSPORT_SECRET_KEY") or "").strip()
        key_path = Path(self.config.state_dir) / ".secrets.key"
        if configured:
            raw = configured.encode("ascii")
        elif key_path.exists():
            raw = key_path.read_bytes().strip()
        else:
            raw = Fernet.generate_key()
            key_path.parent.mkdir(parents=True, exist_ok=True)
            tmp = key_path.with_name(key_path.name + ".tmp")
            tmp.write_bytes(raw)
            try:
                os.chmod(tmp, 0o600)
            except OSError:
                pass
            os.replace(tmp, key_path)
            try:
                os.chmod(key_path, 0o600)
            except OSError:
                pass
        try:
            return Fernet(raw)
        except (TypeError, ValueError) as exc:
            raise WebError(
                HTTPStatus.INTERNAL_SERVER_ERROR,
                "LINEPASSPORT_SECRET_KEY is invalid.",
                "invalid_secret_key",
            ) from exc

    def _encrypt_secret(self, value: str) -> str:
        if not value:
            return ""
        if value.startswith("fernet:"):
            return value
        token = self.secret_cipher.encrypt(value.encode("utf-8")).decode("ascii")
        return f"fernet:{token}"

    def _migrate_stored_secrets(self) -> None:
        accounts_root = self.store.get("accounts", {})
        accounts_changed = False
        if isinstance(accounts_root, dict):
            for account in accounts_root.get("accounts", []):
                if not isinstance(account, dict):
                    continue
                proxy_url = str(account.get("proxyUrl") or "")
                if proxy_url and not proxy_url.startswith("fernet:"):
                    account["proxyUrl"] = self._encrypt_secret(proxy_url)
                    accounts_changed = True
            if accounts_changed:
                self.store.set("accounts", accounts_root)

        root = self.store.get("ai_settings", {})
        changed = False

        def encrypt_record(record: Any) -> None:
            nonlocal changed
            if not isinstance(record, dict):
                return
            key = str(record.get("apiKey") or "")
            if key and not key.startswith("fernet:"):
                record["apiKey"] = self._encrypt_secret(key)
                changed = True

        if isinstance(root, dict):
            encrypt_record(root)
            tenants = root.get("tenants")
            if isinstance(tenants, dict):
                for tenant in tenants.values():
                    if not isinstance(tenant, dict):
                        continue
                    encrypt_record(tenant)
                    for provider in AI_PROVIDERS:
                        encrypt_record(tenant.get(provider))
            if changed:
                self.store.set("ai_settings", root)

        global_ai = self.store.get("global_ai", {})
        if not isinstance(global_ai, dict):
            return
        global_changed = False

        def encrypt_global_record(record: Any) -> None:
            nonlocal global_changed
            if not isinstance(record, dict):
                return
            key = str(record.get("apiKey") or "")
            if key and not key.startswith("fernet:"):
                record["apiKey"] = self._encrypt_secret(key)
                global_changed = True

        encrypt_global_record(global_ai.get("settings"))
        for source in global_ai.get("apiSources", []):
            encrypt_global_record(source)
        knowledge_tenants = global_ai.get("tenants")
        if isinstance(knowledge_tenants, dict):
            for tenant in knowledge_tenants.values():
                if not isinstance(tenant, dict):
                    continue
                for source in tenant.get("apiSources", []):
                    encrypt_global_record(source)
        if global_changed:
            self.store.set("global_ai", global_ai)

    def _decrypt_secret(self, value: str) -> str:
        if not value or not value.startswith("fernet:"):
            return value
        try:
            return self.secret_cipher.decrypt(value[len("fernet:") :].encode("ascii")).decode(
                "utf-8"
            )
        except (InvalidToken, ValueError) as exc:
            raise WebError(
                HTTPStatus.INTERNAL_SERVER_ERROR,
                "Stored secret cannot be decrypted. Restore the original secret key.",
                "secret_decryption_failed",
            ) from exc

    def verify_setup_token(self, supplied: str, source: str = "") -> None:
        if not self.setup_token_required():
            return
        expected = (
            self.config.setup_token
            or os.getenv("LINEPASSPORT_SETUP_TOKEN")
            or os.getenv("OKLINE_SETUP_TOKEN")
            or ""
        )
        if not expected:
            raise WebError(
                HTTPStatus.SERVICE_UNAVAILABLE,
                "Initial setup is locked until LINEPASSPORT_SETUP_TOKEN is configured.",
                "setup_token_not_configured",
            )
        rate_key = f"setup:source:{(source or 'local').strip().casefold()}"
        with self.web_auth.lock:
            self.web_auth._check_login_rate_limit(rate_key)
            if not hmac.compare_digest(str(supplied or ""), expected):
                self.web_auth._record_login_failure(rate_key)
                raise WebError(
                    HTTPStatus.FORBIDDEN,
                    "Setup token is invalid.",
                    "invalid_setup_token",
                )
            self.web_auth.login_failures.pop(rate_key, None)

    def _migrate_tenant_data(self) -> None:
        users = [
            user for user in self.web_auth.data.get("users", []) if isinstance(user, dict)
        ]
        legacy_owner = next(
            (
                user
                for user in users
                if user.get("role") == "admin" and user.get("active", True)
            ),
            next((user for user in users if user.get("role") != "god"), None),
        )
        if legacy_owner is None:
            return
        owner_id = str(legacy_owner.get("id") or "")
        if not owner_id:
            return

        changed_auth = False
        assigned = {
            str(account_id)
            for user in users
            for account_id in (user.get("accountIds") or [])
            if account_id
        }
        accounts_changed = False
        for account in self.account_store.data.get("accounts", []):
            if not isinstance(account, dict):
                continue
            account_id = str(account.get("id") or "")
            if account_id and account_id not in assigned:
                account_ids = set(legacy_owner.get("accountIds") or [])
                account_ids.add(account_id)
                legacy_owner["accountIds"] = sorted(account_ids)
                assigned.add(account_id)
                changed_auth = True
            owner = self.web_auth.user_for_account(account_id)
            expected_owner = str((owner or legacy_owner).get("id") or "")
            if expected_owner and account.get("ownerId") != expected_owner:
                account["ownerId"] = expected_owner
                accounts_changed = True
        if changed_auth:
            legacy_owner["updatedAt"] = _now_iso()
            self.web_auth._save()
        if accounts_changed:
            self.account_store.save()

        pattern_data = self.store.get("patterns", {"patterns": []})
        patterns = pattern_data.get("patterns", []) if isinstance(pattern_data, dict) else []
        patterns_changed = False
        for pattern in patterns if isinstance(patterns, list) else []:
            if not isinstance(pattern, dict):
                continue
            if not pattern.get("ownerId"):
                pattern["ownerId"] = owner_id
                patterns_changed = True
            if not pattern.get("categoryId"):
                pattern["categoryId"] = DEFAULT_PATTERN_CATEGORY_ID
                patterns_changed = True
        if patterns_changed:
            self.store.set(
                "patterns",
                {
                    "patterns": patterns,
                    "categories": (
                        pattern_data.get("categories", [])
                        if isinstance(pattern_data, dict)
                        else []
                    ),
                },
            )

        ai_data = self.store.get("ai_settings", {})
        if isinstance(ai_data, dict) and "tenants" not in ai_data:
            tenants = {owner_id: ai_data} if ai_data else {}
            self.store.set("ai_settings", {"tenants": tenants})

        schedule_data = self.store.get("schedules", {"schedules": []})
        schedules = (
            schedule_data.get("schedules", []) if isinstance(schedule_data, dict) else []
        )
        schedules_changed = False
        for schedule in schedules if isinstance(schedules, list) else []:
            if not isinstance(schedule, dict) or schedule.get("ownerId"):
                continue
            owner = self.web_auth.user_for_account(str(schedule.get("accountId") or ""))
            schedule["ownerId"] = str((owner or legacy_owner).get("id") or owner_id)
            schedules_changed = True
        if schedules_changed:
            self.store.set("schedules", {"schedules": schedules})

    def close(self) -> None:
        self.telegram_users.close()
        self.telegram.close()
        self.staff_notifier.close()
        self.crm_engine.stop()
        self.crm_executor.shutdown(wait=True, cancel_futures=True)
        self.session_keeper.close()
        self.ai_auto_reply_engine.close()
        for watcher in list(self.ops_watchers.values()):
            watcher.stop()
        self.ops_refresh_executor.shutdown(wait=False, cancel_futures=True)
        self.push_executor.shutdown(wait=False, cancel_futures=True)
        with self.inbox_events:
            self.inbox_events.notify_all()
        try:
            self.flush_presence()
        except Exception:
            traceback.print_exc()
        self.scheduler.close()
        self.ai_auto_reply_executor.shutdown(wait=False, cancel_futures=True)
        self.schedule_executor.shutdown(wait=False, cancel_futures=True)
        with self.lock:
            apis = list(self.apis.values())
            self.apis = {}
        for api in apis:
            api.close()
        self.crm.close()
        self.store.close()

    def api_lock_for(self, account_id: str) -> threading.RLock:
        with self.lock:
            return self.api_locks.setdefault(account_id, threading.RLock())

    def invalidate_inbox_snapshot(self, account_id: str) -> None:
        with self.inbox_snapshot_lock:
            self.inbox_snapshots.pop(account_id, None)

    def inbox_message_boxes(
        self,
        account_id: str,
        api: OkLine,
        *,
        force: bool = False,
        max_age: float | None = None,
    ) -> dict[str, Any]:
        ttl = INBOX_SNAPSHOT_TTL_SECONDS if max_age is None else max_age

        def fresh_snapshot() -> dict[str, Any] | None:
            with self.inbox_snapshot_lock:
                cached = self.inbox_snapshots.get(account_id)
                if cached is None:
                    return None
                fetched_at, payload = cached
                if time.monotonic() - fetched_at >= ttl:
                    return None
                return payload

        if not force:
            cached = fresh_snapshot()
            if cached is not None:
                return cached

        with self.api_lock_for(account_id):
            if not force:
                cached = fresh_snapshot()
                if cached is not None:
                    return cached
            payload = api.get_message_boxes(
                limit=INBOX_SNAPSHOT_CHAT_LIMIT,
                last_messages_per_box=INBOX_SNAPSHOT_MESSAGES_PER_BOX,
            )
            if not isinstance(payload, dict):
                raise RuntimeError("LINE returned an invalid inbox response")
            with self.inbox_snapshot_lock:
                self.inbox_snapshots[account_id] = (time.monotonic(), payload)
            self.inbox_refreshed_at[account_id] = time.monotonic()
            self._after_inbox_fetch(account_id, payload, api)
            return payload

    def chat_summary_map(
        self, account_id: str, api: OkLine, limit: int = INBOX_SNAPSHOT_CHAT_LIMIT
    ) -> dict[str, dict[str, Any]]:
        try:
            message_boxes = self.inbox_message_boxes(account_id, api)
        except Exception:
            return {}
        return _chat_summary_map(
            api,
            limit,
            message_boxes=message_boxes,
        )

    @property
    def login(self) -> dict[str, Any]:
        """Compatibility view for the anonymous/local login slot."""
        return self.logins.setdefault("", {"state": "idle"})

    @login.setter
    def login(self, value: dict[str, Any]) -> None:
        self.logins[""] = value

    @staticmethod
    def _login_owner_key(user: dict[str, Any] | None) -> str:
        return str((user or {}).get("id") or "")

    def _proxy_url_for_account(self, account: dict[str, Any] | None) -> str | None:
        encrypted = str((account or {}).get("proxyUrl") or "")
        if not encrypted:
            return None
        return _validate_proxy_url(self._decrypt_secret(encrypted))

    def _new_api(self, account_id: str | None = None) -> OkLine:
        redact = not self.config.show_secrets
        if self.config.access_token and account_id in (None, "__manual__"):
            return OkLine(
                access_token=self.config.access_token,
                refresh_token=self.config.refresh_token,
                redact=redact,
            )
        account = self.account_store.get(account_id) if account_id else None
        proxy_url = self._proxy_url_for_account(account)
        line_config = _line_config_for_proxy(proxy_url)
        token_file = account.get("tokenFile") if account else None
        if token_file and os.path.exists(token_file):
            return self._api_from_account_tokens(
                str(token_file),
                account_id=str(account_id or ""),
                redact=redact,
                line_config=line_config,
            )
        return OkLine(config=line_config, redact=redact)

    def _api_from_account_tokens(
        self,
        token_file: str,
        *,
        redact: bool,
        account_id: str = "",
        line_config: LineConfig | None = None,
    ) -> OkLine:
        from .session import Session

        if os.path.getsize(token_file) > MAX_SESSION_FILE_BYTES:
            raise WebError(
                HTTPStatus.INTERNAL_SERVER_ERROR,
                "Stored LINE session file is too large.",
                "invalid_session_file",
            )
        raw = Path(token_file).read_bytes()
        if raw.startswith(b"fernet:"):
            try:
                payload = self.secret_cipher.decrypt(raw[len(b"fernet:") :])
                session = Session.from_dict(json.loads(payload.decode("utf-8")))
            except (InvalidToken, UnicodeError, ValueError, TypeError) as exc:
                raise WebError(
                    HTTPStatus.INTERNAL_SERVER_ERROR,
                    "Stored LINE session cannot be decrypted. Restore the original secret key.",
                    "session_decryption_failed",
                ) from exc
            api = OkLine(
                access_token=session.access_token,
                refresh_token=session.refresh_token,
                certificate=session.certificate,
                mid=session.mid,
                config=line_config,
                redact=redact,
            )
            if session.e2ee:
                try:
                    api.e2ee.load_from_export(session.e2ee)
                except Exception:
                    traceback.print_exc()
        else:
            session = Session.from_dict(json.loads(raw.decode("utf-8")))
            api = OkLine.from_tokens_file(token_file, config=line_config, redact=redact)
            api._session_path = None
            self._save_account_tokens(api, token_file, fallback_e2ee=session.e2ee)

        self._bind_account_session(api, account_id, token_file)
        return api

    def _bind_account_session(
        self, api: OkLine, account_id: str, token_file: str
    ) -> None:
        """Persist future refreshes and report terminal auth failures."""

        def persist_refreshed_session() -> None:
            self._save_account_tokens(api, token_file)
            if account_id:
                self.account_store.mark_session_connected(account_id)

        api._session_path = None
        api._session_save_hook = persist_refreshed_session
        if account_id:
            api.transport._auth_failure_hook = (
                lambda exc: self._handle_account_auth_failure(account_id, exc)
            )

    def _stored_session_e2ee(self, token_file: str) -> dict[str, Any] | None:
        from .session import Session

        try:
            raw = Path(token_file).read_bytes()
            if raw.startswith(b"fernet:"):
                raw = self.secret_cipher.decrypt(raw[len(b"fernet:") :])
                session = Session.from_dict(json.loads(raw.decode("utf-8")))
            else:
                session = Session.from_dict(json.loads(raw.decode("utf-8")))
        except (OSError, InvalidToken, UnicodeError, ValueError, TypeError):
            return None
        return session.e2ee if isinstance(session.e2ee, dict) else None

    def _save_account_tokens(
        self,
        api: OkLine,
        token_file: str,
        *,
        fallback_e2ee: dict[str, Any] | None = None,
    ) -> None:
        from .session import Session

        session = Session.from_tokens(api.transport.tokens)
        persisted_e2ee = (
            fallback_e2ee
            if isinstance(fallback_e2ee, dict)
            else self._stored_session_e2ee(token_file)
        )
        try:
            if api.e2ee.is_ready():
                exported_e2ee = api.e2ee.export_keys()
                if exported_e2ee.get("keys"):
                    persisted_e2ee = exported_e2ee
        except Exception:
            traceback.print_exc()
        session.e2ee = persisted_e2ee
        payload = json.dumps(
            session.to_dict(), ensure_ascii=False, separators=(",", ":")
        ).encode("utf-8")
        encrypted = b"fernet:" + self.secret_cipher.encrypt(payload)
        _write_private_bytes(token_file, encrypted)
        api._session_path = None

    def keep_sessions_fresh(self, now: float | None = None) -> list[str]:
        """Refresh tokens close to expiry and revive sessions that only expired.

        LINE access tokens last about 7 days while the refresh token lasts a
        year, so a session is renewed when fewer than two days remain. Accounts
        already marked for reconnect because the token expired (code 119) get
        one refresh attempt per hour before anyone has to scan a QR again.
        Returns the account ids that were refreshed.
        """
        now = time.time() if now is None else now
        refreshed: list[str] = []
        for account in self.account_store.list_accounts():
            account_id = str(account.get("id") or "")
            if not account_id or not account.get("tokenFileExists"):
                continue
            if account.get("channel") != "line":
                continue
            expired = account.get("sessionState") == "reauth_required"
            if expired and "code 119" not in str(account.get("sessionError") or ""):
                continue  # revoked (e.g. signed out on the phone): needs a QR
            last_try = self.session_refresh_attempts.get(account_id, 0.0)
            if now - last_try < SESSION_REFRESH_RETRY_SECONDS:
                continue
            try:
                api = self.get_api(account_id, require_auth=False)
            except Exception:
                continue
            tokens = api.transport.tokens
            if not tokens.refresh_token:
                continue
            if not expired:
                expires_at = _jwt_expiry(tokens.access_token)
                if expires_at is None or expires_at - now > SESSION_REFRESH_BEFORE_SECONDS:
                    continue
            self.session_refresh_attempts[account_id] = now
            if self._refresh_account_session(account_id, api, revived=expired):
                refreshed.append(account_id)
        return refreshed

    def _refresh_account_session(self, account_id: str, api: OkLine, *, revived: bool) -> bool:
        try:
            with self.api_lock_for(account_id), api._token_refresh_lock:
                api.auth.refresh_access_token()
                if api._session_save_hook is not None:
                    api._session_save_hook()
        except Exception as exc:
            self.append_bot_log(
                "line.session.refresh_failed",
                account_id=account_id,
                ok=False,
                detail=_short_text(str(exc), 300),
            )
            return False
        self.account_store.mark_session_connected(account_id)
        self.invalidate_inbox_snapshot(account_id)
        self.append_bot_log(
            "line.session.refreshed",
            account_id=account_id,
            detail="revived after expiry" if revived else "renewed before expiry",
        )
        return True

    def _handle_account_auth_failure(
        self, account_id: str, exc: LineAuthError
    ) -> None:
        code = f" (code {exc.code})" if exc.code is not None else ""
        detail = f"LINE session expired or was revoked{code}. Connect the account again."
        changed = self.account_store.mark_session_reauth_required(account_id, detail)
        self.invalidate_inbox_snapshot(account_id)
        self._set_ai_auto_reply_runtime(
            account_id,
            state="login_required",
            lastError=detail,
            lastPollAt=_now_iso(),
        )
        if changed:
            self.append_bot_log(
                "line.session.reauth_required",
                account_id=account_id,
                ok=False,
                detail=detail,
                data={"code": exc.code, "path": exc.path},
            )

    def get_api(self, account_id: str | None = None, *, require_auth: bool = True) -> OkLine:
        if self.config.access_token and account_id is None:
            cache_key = "__manual__"
        else:
            account_id = account_id or self.account_store.active_id()
            cache_key = account_id or "__anonymous__"
        if account_id and _account_channel(self.account_store.get(account_id)) != "line":
            # Telegram accounts have no LINE session; never fall into the QR flow.
            raise _line_only()
        if account_id and require_auth and self.account_store.requires_reauth(account_id):
            raise LineLoginRequired(
                "LINE session expired or was revoked; connect the account again"
            )
        with self.lock:
            if cache_key not in self.apis:
                self.apis[cache_key] = self._new_api(account_id)
            api = self.apis[cache_key]
        if require_auth and not api.tokens.access_token:
            raise WebError(
                HTTPStatus.UNAUTHORIZED, "No session. Start QR login first.", "no_session"
            )
        return api

    def replace_api(self, account_id: str, api: OkLine) -> None:
        self.invalidate_inbox_snapshot(account_id)
        with self.lock:
            old = self.apis.get(account_id)
            self.apis[account_id] = api
        if old is not None and old is not api:
            old.close()

    def close_api(self, account_id: str) -> None:
        self.invalidate_inbox_snapshot(account_id)
        with self.lock:
            api = self.apis.pop(account_id, None)
        if api is not None:
            api.close()

    def status(
        self, account_id: str | None = None, user: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        account_id = (account_id or "").strip()
        allowed_ids = self.web_auth.allowed_account_ids(user)
        api: OkLine | None = None
        authenticated = False
        profile: dict[str, Any] | None = None
        profile_error: str | None = None
        e2ee_ready = False
        session_state = "missing"
        session_error = ""
        if account_id:
            account = self.account_store.get(account_id)
            if not account:
                raise WebError(HTTPStatus.NOT_FOUND, "Account not found.")
            if not self.web_auth.can_access_account(user, account_id):
                raise WebError(
                    HTTPStatus.FORBIDDEN, "Permission denied for this LINE account."
                )
            if _account_channel(account) != "line":
                return self._telegram_status(account, allowed_ids)
            api = self.get_api(account_id, require_auth=False)
            session_state = self.account_store.session_state(account_id)
            session_error = str(account.get("sessionError") or "")
            authenticated = bool(
                api.tokens.access_token and session_state != "reauth_required"
            )
        if account_id and api and authenticated:
            try:
                with self.api_lock_for(account_id):
                    profile = api.get_profile()
                if isinstance(profile, dict):
                    self.account_store.update_profile(account_id, profile)
            except Exception as exc:
                profile_error = str(exc)
                session_state = self.account_store.session_state(account_id)
                if session_state == "reauth_required":
                    authenticated = False
                    latest = self.account_store.get(account_id) or {}
                    session_error = str(latest.get("sessionError") or profile_error)
            e2ee_ready = bool(getattr(api, "e2ee", None) and api.e2ee.is_ready())
        return {
            "version": __version__,
            "authenticated": authenticated,
            "activeAccountId": account_id,
            "accounts": self.account_store.list_accounts(allowed_ids),
            "storage": self.store.label(),
            "nodeAvailable": LtsmBridge.is_available(),
            "e2eeReady": e2ee_ready,
            "profile": profile,
            "profileError": profile_error,
            "sessionState": session_state,
            "sessionError": session_error,
            "loginRequired": session_state == "reauth_required",
        }

    def accounts(self, user: dict[str, Any] | None = None) -> dict[str, Any]:
        allowed_ids = self.web_auth.allowed_account_ids(user)
        accounts = self.account_store.list_accounts(allowed_ids)
        active_id = self.account_store.active_id()
        visible_ids = {str(account.get("id") or "") for account in accounts}
        if active_id not in visible_ids:
            active_id = accounts[0]["id"] if accounts else None
        return {
            "activeAccountId": active_id,
            "accounts": accounts,
        }

    def switch_account(
        self, account_id: str, user: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        if not self.web_auth.can_access_account(user, account_id):
            raise WebError(HTTPStatus.FORBIDDEN, "Permission denied for this LINE account.")
        account = self.account_store.set_active(account_id)
        return {"ok": True, "account": account, "status": self.status(account_id, user)}

    def start_login(
        self,
        wait_seconds: float = 180.0,
        account_name: str | None = None,
        user: dict[str, Any] | None = None,
        *,
        proxy_url: str | None = None,
        reconnect_account_id: str | None = None,
    ) -> dict[str, Any]:
        validated_proxy = _validate_proxy_url(proxy_url) if proxy_url else None
        reconnect_account_id = str(reconnect_account_id or "").strip() or None
        if reconnect_account_id:
            account = self.account_store.get(reconnect_account_id)
            if account is None:
                raise WebError(HTTPStatus.NOT_FOUND, "Account not found.")
            if not self.web_auth.can_access_account(user, reconnect_account_id):
                raise WebError(
                    HTTPStatus.FORBIDDEN,
                    "Permission denied for this LINE account.",
                )
            if _account_channel(account) != "line":
                raise _line_only()
            if validated_proxy is None:
                validated_proxy = self._proxy_url_for_account(account)
        owner_id = self._login_owner_key(user)
        with self.lock:
            login = self.logins.setdefault(owner_id, {"state": "idle"})
            if login.get("state") in {"starting", "qr", "pin"}:
                raise WebError(
                    HTTPStatus.CONFLICT, "QR login is already running.", "login_running"
                )
            login_id = uuid.uuid4().hex
            self.logins[owner_id] = {
                "state": "starting",
                "id": login_id,
                "startedAt": time.time(),
                "qrUrl": None,
                "qrSvg": None,
                "pin": None,
                "error": None,
                "profile": None,
                "account": None,
                "accountName": account_name,
                "reconnectAccountId": reconnect_account_id,
                "proxyConfigured": bool(validated_proxy),
                "ownerId": owner_id,
            }
        thread = threading.Thread(
            target=self._login_worker,
            args=(
                float(wait_seconds),
                account_name,
                login_id,
                owner_id,
                validated_proxy,
                reconnect_account_id,
            ),
            daemon=True,
        )
        thread.start()
        return self.login_state(user)

    def login_state(self, user: dict[str, Any] | None = None) -> dict[str, Any]:
        owner_key = self._login_owner_key(user)
        with self.lock:
            return dict(self.logins.get(owner_key) or {"state": "idle"})

    def cancel_login(self, user: dict[str, Any] | None = None) -> dict[str, Any]:
        """Free the QR-login worker slot so a fresh login can start.

        The in-flight worker (if any) keeps its ``id``; because we install a
        new idle login state here, that stale worker's callbacks/result become
        no-ops (they only write when their ``id`` still matches).
        """
        owner_key = self._login_owner_key(user)
        with self.lock:
            self.logins[owner_key] = {"state": "idle", "id": uuid.uuid4().hex}
        return {"ok": True, "state": "idle"}

    def _login_worker(
        self,
        wait_seconds: float,
        account_name: str | None,
        login_id: str,
        owner_id: str,
        proxy_url: str | None,
        reconnect_account_id: str | None,
    ) -> None:
        client = OkLine(
            config=_line_config_for_proxy(proxy_url),
            record=False,
            redact=not self.config.show_secrets,
        )
        keep_client = False
        owner_key = str(owner_id or "")

        def _current() -> bool:
            return self.logins.get(owner_key, {}).get("id") == login_id

        def on_qr(url: str) -> None:
            with self.lock:
                if _current():
                    self.logins[owner_key].update(
                        {"state": "qr", "qrUrl": url, "qrSvg": _qr_svg(url)}
                    )

        def on_pin(pin: str) -> None:
            with self.lock:
                if _current():
                    self.logins[owner_key].update({"state": "pin", "pin": pin})

        try:
            result = client.qr_login(on_qr=on_qr, on_pin=on_pin, wait_seconds=wait_seconds)
            if not result.access_token:
                raise WebError(
                    HTTPStatus.BAD_GATEWAY, result.display_message or "Login failed"
                )
            profile = client.get_profile()
            with self.lock:
                cancelled = not _current()
            if cancelled:
                # The user cancelled while we were finishing; drop the session
                # instead of registering an account they no longer expect.
                return
            if reconnect_account_id:
                with self.api_lock_for(reconnect_account_id):
                    account = self._commit_reconnected_account(
                        client, profile, reconnect_account_id, proxy_url
                    )
                    self._bind_account_session(
                        client, reconnect_account_id, str(account["tokenFile"])
                    )
                    self.replace_api(reconnect_account_id, client)
            else:
                account = self._commit_new_account(
                    client, profile, account_name, owner_id, proxy_url
                )
                self._bind_account_session(
                    client, str(account["id"]), str(account["tokenFile"])
                )
                self.replace_api(account["id"], client)
            keep_client = True
            with self.lock:
                if _current():
                    self.logins[owner_key].update(
                        {
                            "state": "success",
                            "profile": profile,
                            "account": next(
                                (
                                    item
                                    for item in self.account_store.list_accounts(
                                        {account["id"]}
                                    )
                                    if item.get("id") == account["id"]
                                ),
                                {"id": account["id"], "label": account.get("label")},
                            ),
                            "error": None,
                        }
                    )
        except Exception as exc:
            with self.lock:
                if _current():
                    self.logins[owner_key].update(
                        {
                            "state": "error",
                            "error": _safe_log_detail(exc, 500),
                            "errorCode": str(getattr(exc, "code", "") or ""),
                        }
                    )
        finally:
            if not keep_client:
                client.close()

    def _commit_reconnected_account(
        self,
        client: OkLine,
        profile: dict[str, Any],
        account_id: str,
        proxy_url: str | None,
    ) -> dict[str, Any]:
        """Replace one revoked session while preserving all account references."""
        with self.lock, self.account_store.lock:
            previous_accounts = copy.deepcopy(self.account_store.data)
            existing = next(
                (
                    account
                    for account in self.account_store.data.get("accounts", [])
                    if isinstance(account, dict) and account.get("id") == account_id
                ),
                None,
            )
            if existing is None:
                raise WebError(HTTPStatus.NOT_FOUND, "Account not found.")
            previous_mid = str(existing.get("mid") or "")
            current_mid = str(profile.get("mid") or "")
            if previous_mid and current_mid and previous_mid != current_mid:
                raise WebError(
                    HTTPStatus.CONFLICT,
                    "The scanned LINE account does not match this account.",
                    "line_account_mismatch",
                )

            token_file = str(existing.get("tokenFile") or "")
            if not token_file:
                os.makedirs(self.config.accounts_dir, exist_ok=True)
                token_file = str(
                    Path(self.config.accounts_dir) / f"{account_id}.tokens.json"
                )
            token_path = Path(token_file)
            previous_token = token_path.read_bytes() if token_path.exists() else None
            try:
                self._save_account_tokens(client, token_file)
                existing["tokenFile"] = token_file
                existing["label"] = str(
                    existing.get("label")
                    or profile.get("displayName")
                    or "LINE Account"
                )[:MAX_NAME_LENGTH]
                existing["mid"] = profile.get("mid") or existing.get("mid")
                existing["userid"] = profile.get("userid") or existing.get("userid")
                for field in ("picturePath", "pictureStatus"):
                    if profile.get(field):
                        existing[field] = profile[field]
                    elif field in profile:
                        existing.pop(field, None)
                if proxy_url:
                    existing["proxyUrl"] = self._encrypt_secret(proxy_url)
                existing["sessionState"] = "connected"
                existing.pop("sessionError", None)
                existing.pop("sessionErrorAt", None)
                existing["updatedAt"] = _now_iso()
                self.account_store.data["activeAccountId"] = account_id
                self.account_store.save()
                return dict(existing)
            except Exception:
                self.account_store.data = previous_accounts
                if previous_token is None:
                    try:
                        token_path.unlink(missing_ok=True)
                    except OSError:
                        traceback.print_exc()
                else:
                    _write_private_bytes(token_file, previous_token)
                raise

    def _commit_new_account(
        self,
        client: OkLine,
        profile: dict[str, Any],
        account_name: str | None,
        owner_id: str,
        proxy_url: str | None = None,
    ) -> dict[str, Any]:
        account: dict[str, Any] | None = None
        with self.lock, self.web_auth.lock, self.account_store.lock:
            previous_accounts = copy.deepcopy(self.account_store.data)
            previous_auth = copy.deepcopy(self.web_auth.data)
            try:
                account = self.account_store.add_from_api(
                    client,
                    profile,
                    account_name,
                    owner_id,
                    encrypted_proxy_url=(
                        self._encrypt_secret(proxy_url) if proxy_url else None
                    ),
                    persist=False,
                    token_writer=self._save_account_tokens,
                )
                auth_data = copy.deepcopy(self.web_auth.data)
                owner = next(
                    (
                        user
                        for user in auth_data.get("users", [])
                        if str(user.get("id") or "") == owner_id
                    ),
                    None,
                )
                if owner is None:
                    raise WebError(HTTPStatus.NOT_FOUND, "Account owner not found.")
                account_ids = set(owner.get("accountIds") or [])
                account_ids.add(str(account["id"]))
                owner["accountIds"] = sorted(account_ids)
                owner["updatedAt"] = _now_iso()
                self.store.set_many(
                    {
                        "accounts": self.account_store.data,
                        "auth": auth_data,
                    }
                )
                self.web_auth.data = auth_data
                return account
            except Exception:
                self.account_store.data = previous_accounts
                self.web_auth.data = previous_auth
                token_file = str((account or {}).get("tokenFile") or "")
                if token_file and os.path.exists(token_file):
                    try:
                        os.remove(token_file)
                    except OSError:
                        traceback.print_exc()
                raise

    def logout_account(
        self, account_id: str, user: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        account_id = _required_account_id(account_id)
        if _account_channel(self.account_store.get(account_id)) != "line":
            return self.delete_account(account_id, user)
        server_error = None
        with self.api_lock_for(account_id):
            api = self.get_api(account_id, require_auth=False)
            if api.tokens.access_token:
                try:
                    api.auth.logout()
                except Exception as exc:
                    server_error = _safe_log_detail(exc, 500)
            self.close_api(account_id)
            self._commit_account_removal(account_id)
        return {
            "ok": True,
            "serverError": server_error,
            "accounts": {
                "accounts": self.account_store.list_accounts(
                    self.web_auth.allowed_account_ids(user)
                )
            },
        }

    def delete_account(
        self, account_id: str, user: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        account_id = _required_account_id(account_id)
        with self.api_lock_for(account_id):
            self.close_api(account_id)
            removed = self._commit_account_removal(account_id)
        removed.pop("tokenFile", None)
        return {
            "ok": True,
            "removed": removed,
            "accounts": {
                "accounts": self.account_store.list_accounts(
                    self.web_auth.allowed_account_ids(user)
                )
            },
        }

    def _commit_account_removal(self, account_id: str) -> dict[str, Any]:
        self.stop_ops_watcher(account_id)
        with (
            self.lock,
            self.web_auth.lock,
            self.account_store.lock,
            self.schedule_lock,
            self.incoming_api_lock,
            self.ai_auto_reply_lock,
        ):
            account_data, removed = self.account_store.data_after_remove(account_id)
            auth_data = copy.deepcopy(self.web_auth.data)
            for auth_user in auth_data.get("users", []):
                _strip_account_from_user(auth_user, {account_id})
            schedules = copy.deepcopy(self.schedules)
            for schedule in schedules:
                if schedule.get("accountId") == account_id:
                    schedule["enabled"] = False
                    schedule["running"] = False
                    schedule["status"] = "account deleted"
                    schedule.pop("runningSince", None)
                    schedule.pop("runToken", None)
            raw_incoming = self.store.get("incoming_api", {"links": []})
            incoming_data = (
                copy.deepcopy(raw_incoming)
                if isinstance(raw_incoming, dict)
                else {"links": []}
            )
            incoming_data["links"] = [
                link
                for link in incoming_data.get("links", [])
                if not isinstance(link, dict) or link.get("accountId") != account_id
            ]
            raw_auto_reply = self.store.get("ai_auto_reply", {"accounts": {}})
            auto_reply_data = (
                copy.deepcopy(raw_auto_reply)
                if isinstance(raw_auto_reply, dict)
                else {"accounts": {}}
            )
            auto_reply_accounts = auto_reply_data.get("accounts")
            if not isinstance(auto_reply_accounts, dict):
                auto_reply_accounts = {}
                auto_reply_data["accounts"] = auto_reply_accounts
            auto_reply_accounts.pop(account_id, None)
            self.store.set_many(
                {
                    "accounts": account_data,
                    "auth": auth_data,
                    "schedules": {"schedules": schedules},
                    "incoming_api": incoming_data,
                    "ai_auto_reply": auto_reply_data,
                }
            )
            self.account_store.data = account_data
            self.web_auth.data = auth_data
            self.schedules = schedules
            self.ai_auto_reply_runtime.pop(account_id, None)
            self.ai_auto_reply_inflight = {
                key for key in self.ai_auto_reply_inflight if key[0] != account_id
            }
        token_file = str(removed.get("tokenFile") or "")
        if token_file and os.path.exists(token_file):
            try:
                os.remove(token_file)
            except OSError:
                traceback.print_exc()
        self.crm_cursors.pop(account_id, None)
        try:
            self.crm.purge_account(account_id)
        except Exception:
            traceback.print_exc()
        if _account_channel(removed) != "line":
            self.telegram.stop(account_id)
            self.telegram_users.stop(account_id)
            credential_file = str(removed.get("credentialFile") or "")
            if credential_file and os.path.exists(credential_file):
                try:
                    os.remove(credential_file)
                except OSError:
                    traceback.print_exc()
            self.store.set(f"telegram_runtime:{account_id}", {"offset": 0})
        with self.room_state_lock:
            self.room_states_cache.pop(account_id, None)
        removed.pop("credentialFile", None)
        return removed

    def update_account(
        self,
        account_id: str,
        label: str,
        user: dict[str, Any] | None = None,
        *,
        proxy_enabled: bool | None = None,
        proxy_url: str | None = None,
    ) -> dict[str, Any]:
        account_id = _required_account_id(account_id)
        if proxy_enabled is not None and not isinstance(proxy_enabled, bool):
            raise WebError(
                HTTPStatus.BAD_REQUEST,
                "proxyEnabled must be true or false.",
                "invalid_proxy_setting",
            )
        validated_proxy = _validate_proxy_url(proxy_url) if proxy_url else None
        before = self.account_store.get(account_id) or {}
        if _account_channel(before) != "line" and (proxy_enabled or validated_proxy):
            raise _line_only()
        account = self.account_store.update_settings(
            account_id,
            label,
            proxy_enabled=proxy_enabled,
            encrypted_proxy_url=(
                self._encrypt_secret(validated_proxy) if validated_proxy else None
            ),
        )
        proxy_changed = str(before.get("proxyUrl") or "") != str(account.get("proxyUrl") or "")
        if proxy_changed:
            self.close_api(account_id)
        account.pop("tokenFile", None)
        account["proxyConfigured"] = bool(account.pop("proxyUrl", None))
        return {
            "ok": True,
            "account": account,
            "accounts": {
                "accounts": self.account_store.list_accounts(
                    self.web_auth.allowed_account_ids(user)
                )
            },
        }

    def users_payload(self) -> dict[str, Any]:
        return {
            "users": self.web_auth.list_users(),
            "roles": self.web_auth.roles_payload(),
            "accounts": self.account_store.list_accounts(),
        }

    def god_users_payload(self) -> dict[str, Any]:
        payload = self.users_payload()
        payload["users"] = [user for user in payload["users"] if user.get("role") != "god"]
        payload["roles"] = {
            role: meta for role, meta in payload["roles"].items() if role != "god"
        }
        payload.pop("accounts", None)
        return payload

    def user_detail(self, user_id: str, actor: dict[str, Any] | None) -> dict[str, Any]:
        if not self.web_auth._is_god(actor):
            raise WebError(HTTPStatus.FORBIDDEN, "Only God can view tenant details.")
        target = self.web_auth._find_user(user_id)
        if target is None:
            raise WebError(HTTPStatus.NOT_FOUND, "User not found.")
        public_user = self.web_auth._public_user_strict(target)
        account_ids = set(target.get("accountIds") or [])
        accounts = []
        for account in self.account_store.list_accounts(account_ids):
            accounts.append(
                {
                    "id": account.get("id"),
                    "label": account.get("label"),
                    "mid": account.get("mid"),
                    "userid": account.get("userid"),
                    "tokenFileExists": account.get("tokenFileExists"),
                    "createdAt": account.get("createdAt"),
                }
            )
        patterns = [
            {
                "id": pattern.get("id"),
                "name": pattern.get("name"),
                "text": pattern.get("text"),
                "categoryId": pattern.get("categoryId"),
                "categoryName": pattern.get("categoryName"),
            }
            for pattern in self.list_patterns(target)["patterns"]
        ]
        schedules = [
            {
                "id": schedule.get("id"),
                "name": schedule.get("name"),
                "accountId": schedule.get("accountId"),
                "contentSource": schedule.get("contentSource"),
                "enabled": bool(schedule.get("enabled")),
                "status": schedule.get("status"),
                "sentCount": int(schedule.get("sentCount") or 0),
            }
            for schedule in self.schedules
            if schedule.get("accountId") in account_ids
        ]
        ai = self.ai_settings(target)
        provider = str(ai.get("provider") or "google")
        provider_data = (ai.get("providers") or {}).get(provider) or {}
        return {
            "user": public_user,
            "accounts": accounts,
            "patterns": patterns,
            "schedules": schedules,
            "ai": {
                "provider": provider,
                "providerLabel": provider_data.get("label"),
                "model": provider_data.get("model"),
                "modelLabel": (provider_data.get("modelLabels") or {}).get(
                    provider_data.get("model")
                ),
                "aspectRatio": provider_data.get("aspectRatio"),
                "configured": bool(provider_data.get("hasApiKey")),
            },
        }

    # -- bot action log -----------------------------------------------------
    def _bot_log_entry(
        self,
        action: str,
        *,
        account_id: str | None = None,
        schedule: dict[str, Any] | None = None,
        ok: bool = True,
        detail: str = "",
        data: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        schedule = schedule if isinstance(schedule, dict) else {}
        entry = {
            "id": uuid.uuid4().hex,
            "at": _now_iso(),
            "ts": time.time(),
            "action": str(action or "event"),
            "ok": bool(ok),
            "accountId": account_id or schedule.get("accountId"),
            "scheduleId": schedule.get("id"),
            "scheduleName": schedule.get("name"),
            "target": schedule.get("to"),
            "contentSource": schedule.get("contentSource"),
            "mode": schedule.get("mode"),
        }
        if detail:
            entry["detail"] = _bot_log_detail(entry["action"], detail)
        if data:
            entry["data"] = data
        return {key: value for key, value in entry.items() if value not in (None, "")}

    def append_bot_log(
        self,
        action: str,
        *,
        account_id: str | None = None,
        schedule: dict[str, Any] | None = None,
        ok: bool = True,
        detail: str = "",
        data: dict[str, Any] | None = None,
    ) -> None:
        try:
            with self.schedule_lock:
                raw = self.store.get("bot_logs", {"logs": []})
                logs = raw.get("logs", []) if isinstance(raw, dict) else []
                if not isinstance(logs, list):
                    logs = []
                logs.append(
                    self._bot_log_entry(
                        action,
                        account_id=account_id,
                        schedule=schedule,
                        ok=ok,
                        detail=detail,
                        data=data,
                    )
                )
                logs = _trim_bot_logs(logs)
                self.store.set("bot_logs", {"logs": logs})
        except Exception:
            # Logging should never prevent the bot action itself from completing.
            traceback.print_exc()

    def list_bot_logs(
        self,
        account_id: str | None = None,
        user: dict[str, Any] | None = None,
        *,
        limit: int = 200,
    ) -> dict[str, Any]:
        account_id = (account_id or "").strip()
        if account_id and not self.web_auth.can_access_account(user, account_id):
            raise WebError(HTTPStatus.FORBIDDEN, "Permission denied for this LINE account.")
        allowed_ids = self.web_auth.allowed_account_ids(user)
        raw = self.store.get("bot_logs", {"logs": []})
        logs = raw.get("logs", []) if isinstance(raw, dict) else []
        if not isinstance(logs, list):
            logs = []
        visible = []
        for log in logs:
            if not isinstance(log, dict):
                continue
            item = dict(log)
            if item.get("detail"):
                item["detail"] = _bot_log_detail(item.get("action"), item.get("detail"))
            visible.append(item)
        if account_id:
            visible = [log for log in visible if log.get("accountId") == account_id]
        elif allowed_ids is not None:
            visible = [log for log in visible if log.get("accountId") in allowed_ids]
        visible = visible[-max(1, min(500, int(limit))) :]
        visible.reverse()
        return {"logs": visible, "count": len(visible)}

    def clear_bot_logs(
        self, account_id: str, user: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        account_id = _required_account_id(account_id)
        if not self.web_auth.can_access_account(user, account_id):
            raise WebError(HTTPStatus.FORBIDDEN, "Permission denied for this LINE account.")
        with self.schedule_lock:
            raw = self.store.get("bot_logs", {"logs": []})
            logs = raw.get("logs", []) if isinstance(raw, dict) else []
            if not isinstance(logs, list):
                logs = []
            kept = [
                log
                for log in logs
                if not isinstance(log, dict) or log.get("accountId") != account_id
            ]
            marker = self._bot_log_entry(
                "logs.clear",
                account_id=account_id,
                detail="Cleared bot logs for this account.",
            )
            kept.append(marker)
            kept = _trim_bot_logs(kept)
            self.store.set("bot_logs", {"logs": kept})
        return {"ok": True, "logs": [marker], "count": 1}

    # -- team (staff sharing the owner's LINE accounts) -----------------------
    def _require_team_owner(self, user: dict[str, Any] | None) -> dict[str, Any]:
        if not user or not self.web_auth.has_permission(user, "manage_accounts"):
            raise WebError(HTTPStatus.FORBIDDEN, "Permission denied.", "forbidden")
        if user.get("teamOwnerId"):
            raise WebError(HTTPStatus.FORBIDDEN, "Staff cannot manage a team.", "forbidden")
        return user

    def team_payload(self, user: dict[str, Any] | None) -> dict[str, Any]:
        owner = self._require_team_owner(user)
        owned = set((self.web_auth._find_user(str(owner.get("id") or "")) or owner).get(
            "accountIds"
        ) or [])
        return {
            "staff": self.web_auth.list_staff(owner),
            "accounts": [
                {"id": account.get("id"), "label": account.get("label")}
                for account in self.account_store.list_accounts(owned)
            ],
        }

    def create_staff(self, body: dict[str, Any], user: dict[str, Any] | None) -> dict[str, Any]:
        owner = self._require_team_owner(user)
        staff = self.web_auth.create_staff(
            owner,
            str(body.get("email") or body.get("username") or ""),
            str(body.get("password") or ""),
            str(body.get("displayName") or ""),
            _string_list(body.get("accountIds")),
        )
        return {"ok": True, "user": staff, **self.team_payload(owner)}

    def update_staff(self, body: dict[str, Any], user: dict[str, Any] | None) -> dict[str, Any]:
        owner = self._require_team_owner(user)
        staff = self.web_auth.update_staff(
            owner,
            str(body.get("id") or ""),
            display_name=str(body["displayName"]) if "displayName" in body else None,
            account_ids=(
                _string_list(body.get("accountIds")) if "accountIds" in body else None
            ),
            active=bool(body.get("active")) if "active" in body else None,
            password=str(body.get("password") or "") or None,
        )
        return {"ok": True, "user": staff, **self.team_payload(owner)}

    def delete_staff(self, body: dict[str, Any], user: dict[str, Any] | None) -> dict[str, Any]:
        owner = self._require_team_owner(user)
        self.web_auth.delete_staff(owner, str(body.get("id") or ""))
        return {"ok": True, **self.team_payload(owner)}

    def tenant_user(self, user: dict[str, Any] | None) -> dict[str, Any] | None:
        """The shop owner whose AI data a (possibly staff) user works on."""
        owner_id = str((user or {}).get("teamOwnerId") or "")
        if not owner_id:
            return user
        owner = self.web_auth._find_user(owner_id)
        return dict(owner) if owner else user

    # -- inbox tracking: rooms, attribution and live events -------------------
    def watch_inbox(self, account_id: str) -> None:
        self.inbox_watchers[account_id] = time.monotonic()

    def refresh_inbox_for_all_accounts(self) -> None:
        """Keep every signed-in account's inbox fresh, not only AI-enabled ones."""
        ai_accounts = self._ai_auto_reply_all()["accounts"]
        now = time.monotonic()
        eligible: set[str] = set()
        for account in list(self.account_store.data.get("accounts", [])):
            if not isinstance(account, dict):
                continue
            account_id = str(account.get("id") or "")
            token_file = str(account.get("tokenFile") or "")
            if _account_channel(account) != "line":
                continue
            if not account_id or not token_file or not os.path.exists(token_file):
                continue
            if self.account_store.requires_reauth(account_id):
                continue
            if self.web_auth.user_for_account(account_id) is None:
                continue
            eligible.add(account_id)
            self._ensure_ops_watcher(account_id)
            record = ai_accounts.get(account_id)
            watched = (
                now - self.inbox_watchers.get(account_id, -1e9) < INBOX_WATCH_TTL_SECONDS
            )
            if self.ops_stream_healthy(account_id):
                interval = OPS_FALLBACK_REFRESH_SECONDS
            elif watched or (isinstance(record, dict) and record.get("enabled")):
                interval = INBOX_ACTIVE_REFRESH_SECONDS
            else:
                interval = INBOX_IDLE_REFRESH_SECONDS
            if now - self.inbox_refreshed_at.get(account_id, -1e9) < interval:
                continue
            self.inbox_refreshed_at[account_id] = now
            try:
                self.inbox_message_boxes(account_id, self.get_api(account_id), force=True)
            except Exception:
                # A broken session is reported by the views that need it; keep
                # polling the remaining accounts.
                continue
        for account_id in set(self.ops_watchers) - eligible:
            # Signed out, deleted or needing a new QR login: stop streaming.
            self.stop_ops_watcher(account_id)
        try:
            self.process_push_queue()
        except Exception:
            traceback.print_exc()

    def _ensure_ops_watcher(self, account_id: str) -> None:
        watcher = self.ops_watchers.get(account_id)
        if watcher is not None and watcher.thread.is_alive():
            return
        try:
            api = self.get_api(account_id)
        except Exception:
            return
        if not hasattr(getattr(api, "ops", None), "stream"):
            return
        self.ops_watchers[account_id] = OpsWatcher(self, account_id)

    def stop_ops_watcher(self, account_id: str) -> None:
        watcher = self.ops_watchers.pop(account_id, None)
        if watcher is not None:
            watcher.stop()

    def ops_stream_healthy(self, account_id: str) -> bool:
        watcher = self.ops_watchers.get(account_id)
        return bool(watcher and watcher.healthy())

    def inbox_max_age(self, account_id: str) -> float:
        """How stale a cached inbox may be: longer while LINE pushes changes."""
        if self.ops_stream_healthy(account_id):
            return OPS_FALLBACK_REFRESH_SECONDS
        return INBOX_SNAPSHOT_TTL_SECONDS

    def request_inbox_refresh(self, account_id: str) -> None:
        """Called by the operation stream; coalesces bursts into one fetch."""
        with self.room_state_lock:
            if account_id in self.ops_refresh_pending:
                return
            self.ops_refresh_pending.add(account_id)
        try:
            self.ops_refresh_executor.submit(self._ops_refresh, account_id)
        except RuntimeError:
            with self.room_state_lock:
                self.ops_refresh_pending.discard(account_id)

    def _ops_refresh(self, account_id: str) -> None:
        time.sleep(OPS_REFRESH_DEBOUNCE_SECONDS)
        with self.room_state_lock:
            self.ops_refresh_pending.discard(account_id)
        try:
            self.inbox_message_boxes(account_id, self.get_api(account_id), force=True)
        except Exception:
            # The regular refresh loop retries; never kill the executor thread.
            return

    # -- Web Push for staff without an open page (B7) --------------------------
    def _vapid(self) -> VapidKeys:
        with self.push_lock:
            if self.vapid_keys is None:
                self.vapid_keys = VapidKeys.load_or_create(
                    Path(self.config.state_dir) / ".vapid_private.pem"
                )
            return self.vapid_keys

    def push_public_key(self) -> dict[str, Any]:
        return {"ok": True, "publicKey": self._vapid().public_key_b64}

    def _push_subscriptions(self) -> list[dict[str, Any]]:
        with self.push_lock:
            if self.push_subscriptions_cache is None:
                raw = self.store.get("push_subscriptions", {"subscriptions": []})
                items = raw.get("subscriptions") if isinstance(raw, dict) else None
                self.push_subscriptions_cache = (
                    [item for item in items if isinstance(item, dict)]
                    if isinstance(items, list)
                    else []
                )
            return list(self.push_subscriptions_cache)

    def _save_push_subscriptions(self, items: list[dict[str, Any]]) -> None:
        with self.push_lock:
            self.store.set("push_subscriptions", {"subscriptions": items})
            self.push_subscriptions_cache = list(items)

    def save_push_subscription(
        self, body: dict[str, Any], user: dict[str, Any] | None
    ) -> dict[str, Any]:
        user_id = str((user or {}).get("id") or "")
        if not user_id:
            raise WebError(HTTPStatus.UNAUTHORIZED, "User authentication required.")
        endpoint = str(body.get("endpoint") or "").strip()
        raw_keys = body.get("keys")
        keys: dict[str, Any] = raw_keys if isinstance(raw_keys, dict) else {}
        p256dh = str(keys.get("p256dh") or "").strip()
        auth = str(keys.get("auth") or "").strip()
        if len(endpoint) > 1024 or not push_endpoint_allowed(endpoint):
            raise WebError(
                HTTPStatus.BAD_REQUEST, "Unsupported push service.", "push_endpoint_invalid"
            )
        if not re.fullmatch(r"[A-Za-z0-9_-]{80,100}", p256dh) or not re.fullmatch(
            r"[A-Za-z0-9_-]{16,32}", auth
        ):
            raise WebError(
                HTTPStatus.BAD_REQUEST, "Push subscription keys are invalid.", "push_keys_invalid"
            )
        with self.push_lock:
            items = [item for item in self._push_subscriptions() if item.get("endpoint") != endpoint]
            mine = [item for item in items if item.get("userId") == user_id]
            if len(mine) >= MAX_PUSH_SUBSCRIPTIONS_PER_USER:
                oldest = min(mine, key=lambda item: str(item.get("createdAt") or ""))
                items.remove(oldest)
            items.append(
                {
                    "id": uuid.uuid4().hex,
                    "userId": user_id,
                    "endpoint": endpoint,
                    "p256dh": p256dh,
                    "auth": auth,
                    "createdAt": _now_iso(),
                }
            )
            self._save_push_subscriptions(items)
        return {"ok": True}

    def remove_push_subscription(
        self, endpoint: str, user: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        user_id = str((user or {}).get("id") or "")
        with self.push_lock:
            items = self._push_subscriptions()
            kept = [
                item
                for item in items
                if not (
                    item.get("endpoint") == endpoint
                    and (not user_id or item.get("userId") == user_id)
                )
            ]
            if len(kept) != len(items):
                self._save_push_subscriptions(kept)
        return {"ok": True}

    def _ai_covers_contacts(self, account_id: str) -> bool:
        record = self._ai_auto_reply_record(account_id)
        if not record.get("enabled") or not record.get("contactsEnabled"):
            return False
        owner = self.web_auth.user_for_account(account_id)
        return bool(self._assistant_settings_for(self._global_ai_all(), owner).get("configured"))

    def _alerts_wanted(self) -> bool:
        """Someone gets alerts: a browser push subscription or a linked Telegram."""
        return bool(self._push_subscriptions()) or self.staff_notifier.has_links()

    def queue_push_for_rooms(self, account_id: str, chat_mids: list[str]) -> None:
        """New customer chats waiting; the AI gets a moment to answer first."""
        if not self._alerts_wanted():
            return
        delay = PUSH_AI_GRACE_SECONDS if self._ai_covers_contacts(account_id) else 0.0
        due = time.time() + delay
        with self.push_lock:
            for chat_mid in chat_mids:
                self.push_pending.setdefault((account_id, chat_mid), due)

    def _push_recipients(self, account_id: str) -> list[tuple[str, list[dict[str, Any]]]]:
        subscriptions = self._push_subscriptions()
        if not subscriptions:
            return []
        settings = self._kpi_settings_for_owner(self._account_owner_id(account_id))
        now = time.time()
        now_ms = int(now * 1000)
        recipients = []
        for member in self._kpi_members(account_id):
            if not member.get("active"):
                continue
            user_id = member["id"]
            mine = [item for item in subscriptions if item.get("userId") == user_id]
            if not mine:
                continue
            if self._user_online(user_id, now_ms):
                # A LinePassport page is open; it shows its own notifications.
                continue
            if not self._on_duty(settings, user_id, now_ms):
                continue
            recipients.append((user_id, mine))
        return recipients

    def _user_online(self, user_id: str, now_ms: int) -> bool:
        current = self.presence_current.get(user_id)
        return bool(
            current
            and now_ms - _coerce_int(current.get("at")) <= PRESENCE_OFFLINE_SECONDS * 1000
        )

    @staticmethod
    def _on_duty(settings: dict[str, Any], user_id: str, now_ms: int) -> bool:
        if settings.get("notifyOutsideHours"):
            return True
        rules = (settings.get("shifts") or {}).get(user_id)
        hours = settings.get("businessHours") or {}
        if not rules and hours.get("enabled"):
            rules = [hours]
        return not rules or bool(_time_windows(rules, now_ms, now_ms + 1))

    def _telegram_recipients(self, account_id: str) -> list[str]:
        """Staff with a linked Telegram who should hear about this account now."""
        owner_id = self._account_owner_id(account_id)
        if not self.staff_notifier.tenant(owner_id):
            return []
        settings = self._kpi_settings_for_owner(owner_id)
        now_ms = int(time.time() * 1000)
        recipients = []
        for member in self._kpi_members(account_id):
            user_id = member["id"]
            link = self.staff_notifier.link_for(user_id)
            if not member.get("active") or not link or link.get("ownerId") != owner_id:
                continue
            if link.get("mode") != "always" and self._user_online(user_id, now_ms):
                continue
            if self._on_duty(settings, user_id, now_ms):
                recipients.append(user_id)
        return recipients

    def process_push_queue(self) -> None:
        if not self.push_pending and not self._alerts_wanted():
            return
        now = time.time()
        with self.push_lock:
            due = [key for key, at in self.push_pending.items() if at <= now]
            for key in due:
                self.push_pending.pop(key, None)
        by_account: dict[str, list[str]] = {}
        for account_id, chat_mid in due:
            room = self.room_states(account_id).get(chat_mid) or {}
            if room.get("status") == "waiting":
                by_account.setdefault(account_id, []).append(chat_mid)
        for account_id, chat_mids in by_account.items():
            self._dispatch_push(account_id, chat_mids)
        # One louder reminder for chats still waiting past the reply target.
        if not self._alerts_wanted():
            return
        for account_id in list(self.room_states_cache):
            sla = int(
                self._kpi_settings_for_owner(self._account_owner_id(account_id)).get(
                    "slaSeconds"
                )
                or DEFAULT_KPI_SLA_SECONDS
            )
            overdue = []
            with self.room_state_lock:
                rooms = self._room_states(account_id)
                for chat_mid, room in rooms.items():
                    asked = _coerce_int(room.get("firstUnansweredAt"))
                    if (
                        room.get("status") == "waiting"
                        and asked
                        and not room.get("pushEscalated")
                        and now * 1000 - asked > sla * 1000
                    ):
                        room["pushEscalated"] = True
                        overdue.append(chat_mid)
                if overdue:
                    self._save_room_states(account_id, rooms)
            if overdue:
                self._dispatch_push(account_id, overdue, escalate=True)

    def _dispatch_push(
        self, account_id: str, chat_mids: list[str], *, escalate: bool = False
    ) -> None:
        account = self.account_store.get(account_id) or {}
        label = str(account.get("label") or "LINE")
        now = time.time()
        try:
            # A chat someone took on only alerts that person.
            assignees = self.crm.assignees_for_chats(account_id, chat_mids)
        except Exception:
            traceback.print_exc()
            assignees = {}
        for user_id, subscriptions in self._push_recipients(account_id):
            with self.push_lock:
                fresh = [
                    mid
                    for mid in chat_mids
                    if assignees.get(mid, user_id) == user_id
                ]
                fresh = [
                    mid
                    for mid in fresh
                    if escalate
                    or now - self.push_last_sent.get((user_id, account_id, mid), 0)
                    >= PUSH_ROOM_COOLDOWN_SECONDS
                ]
                if not fresh:
                    continue
                recent = [
                    at
                    for at in self.push_recent.get(user_id, [])
                    if now - at < PUSH_DIGEST_WINDOW_SECONDS
                ]
                for mid in fresh:
                    self.push_last_sent[(user_id, account_id, mid)] = now
                if not escalate and len(recent) + len(fresh) > PUSH_DIGEST_THRESHOLD:
                    if now - self.push_digest_at.get(user_id, 0) < PUSH_DIGEST_WINDOW_SECONDS:
                        continue
                    self.push_digest_at[user_id] = now
                    waiting = sum(
                        1
                        for room in self.room_states(account_id).values()
                        if room.get("status") == "waiting"
                    )
                    payloads: list[dict[str, Any]] = [
                        {
                            "title": f"ลูกค้า {waiting} คนรอตอบ",
                            "body": f"{label} · เปิด LinePassport เพื่อตอบ",
                            "titleEn": f"{waiting} customers waiting",
                            "bodyEn": f"{label} · open LinePassport to reply",
                            "tag": "linepassport:digest",
                            "accountId": account_id,
                        }
                    ]
                else:
                    recent.extend(now for _ in fresh)
                    payloads = [
                        {
                            "title": "ลูกค้ารอตอบนานแล้ว" if escalate else "ลูกค้าทักมาใหม่",
                            "body": f"{label} · "
                            + ("รอเกินเวลาที่ตั้งไว้" if escalate else "เปิด LinePassport เพื่อตอบ"),
                            "titleEn": "A customer has been waiting"
                            if escalate
                            else "New customer message",
                            "bodyEn": f"{label} · "
                            + ("past the reply target" if escalate else "open LinePassport to reply"),
                            "tag": f"linepassport:{account_id}:{mid}",
                            "accountId": account_id,
                            "mid": mid,
                            "requireInteraction": escalate,
                        }
                        for mid in fresh
                    ]
                self.push_recent[user_id] = recent
            for subscription in subscriptions:
                for payload in payloads:
                    try:
                        self.push_executor.submit(self._deliver_push, subscription, payload)
                    except RuntimeError:
                        return
        self._dispatch_telegram(account_id, chat_mids, escalate=escalate, assignees=assignees)

    def _chat_alert_lines(
        self, account_id: str, chat_mid: str, label: str
    ) -> tuple[str, list[str]]:
        try:
            conv = self.crm.conversation_for_chat(account_id, chat_mid)
        except Exception:
            conv = None
        name = str((conv or {}).get("display_name") or "") or f"…{chat_mid[-6:]}"
        preview = preview_label(str((conv or {}).get("last_preview") or ""))
        head = f"{name} · {label}" if label else name
        return name, [head, f"“{preview}”" if preview else ""]

    def _dispatch_telegram(
        self,
        account_id: str,
        chat_mids: list[str],
        *,
        escalate: bool,
        assignees: dict[str, str],
    ) -> None:
        """Telegram alerts follow the same rules as browser pushes."""
        if not self.staff_notifier.has_links():
            return
        owner_id = self._account_owner_id(account_id)
        recipients = self._telegram_recipients(account_id)
        if not recipients:
            return
        account = self.account_store.get(account_id) or {}
        label = str(account.get("label") or account_id)
        now = time.time()
        for user_id in recipients:
            key = "tg:" + user_id
            with self.push_lock:
                fresh = [
                    mid
                    for mid in chat_mids
                    if assignees.get(mid, user_id) == user_id
                    and (
                        escalate
                        or now - self.push_last_sent.get((key, account_id, mid), 0)
                        >= PUSH_ROOM_COOLDOWN_SECONDS
                    )
                ]
                for mid in fresh:
                    self.push_last_sent[(key, account_id, mid)] = now
                recent = [
                    at
                    for at in self.push_recent.get(key, [])
                    if now - at < PUSH_DIGEST_WINDOW_SECONDS
                ]
                digest = not escalate and len(recent) + len(fresh) > PUSH_DIGEST_THRESHOLD
                if digest and now - self.push_digest_at.get(key, 0) < PUSH_DIGEST_WINDOW_SECONDS:
                    fresh = []
                elif digest:
                    self.push_digest_at[key] = now
                recent.extend(now for _ in fresh)
                self.push_recent[key] = recent
            if not fresh:
                continue
            if digest:
                waiting = sum(
                    1
                    for room in self.room_states(account_id).values()
                    if room.get("status") == "waiting"
                )
                self.staff_notifier.send_alert(
                    owner_id,
                    user_id,
                    title=f"🔔 ลูกค้า {waiting} คนรอตอบ",
                    lines=[f"{label} · เปิด LinePassport เพื่อตอบ"],
                )
                continue
            for mid in fresh:
                _name, lines = self._chat_alert_lines(account_id, mid, label)
                self.staff_notifier.send_alert(
                    owner_id,
                    user_id,
                    title="⏰ ลูกค้ารอตอบนานแล้ว" if escalate else "💬 ลูกค้าทักมาใหม่",
                    lines=lines,
                    account_id=account_id,
                    chat_id=mid,
                )

    def _deliver_push(self, subscription: dict[str, Any], payload: dict[str, Any]) -> None:
        subject = str(os.getenv("LINEPASSPORT_VAPID_SUBJECT") or DEFAULT_VAPID_SUBJECT)
        try:
            send_web_push(subscription, payload, self._vapid(), subject=subject)
        except WebPushError as exc:
            if exc.subscription_gone:
                self.remove_push_subscription(str(subscription.get("endpoint") or ""))
        except Exception:
            traceback.print_exc()

    def _after_inbox_fetch(
        self, account_id: str, payload: dict[str, Any], api: OkLine | None = None
    ) -> None:
        try:
            raw_boxes = payload.get("messageBoxes", [])
            boxes = [box for box in raw_boxes if isinstance(box, dict)] if isinstance(
                raw_boxes, list
            ) else []
            signature = hashlib.sha1(
                "|".join(
                    f"{_message_box_id(box)}:{_message_box_time(box)}:"
                    f"{_message_box_unread_count(box)}"
                    for box in boxes
                ).encode("utf-8")
            ).hexdigest()
            if self.inbox_signatures.get(account_id) != signature:
                self.inbox_signatures[account_id] = signature
                self._bump_inbox_version(account_id)
            own_mid = str((self.account_store.get(account_id) or {}).get("mid") or "")
            if own_mid:
                self.update_room_state(account_id, own_mid, boxes)
                self._queue_crm_ingest(account_id, own_mid, boxes)
        except Exception:
            traceback.print_exc()

    # -- customer records (CRM) ----------------------------------------------
    def _crm_cursor_map(self, account_id: str) -> dict[str, int]:
        cursors = self.crm_cursors.get(account_id)
        if cursors is None:
            cursors = {
                str(row["chat_id"]): int(row["last_message_at"] or 0)
                for row in self.crm.db.query(
                    "SELECT chat_id, last_message_at FROM crm_conversations WHERE account_id = ?",
                    (account_id,),
                )
            }
            self.crm_cursors[account_id] = cursors
        return cursors

    def _queue_crm_ingest(
        self, account_id: str, own_mid: str, boxes: list[dict[str, Any]]
    ) -> None:
        """Hand new one-to-one messages to the CRM worker (decrypting happens there)."""
        owner_id = self._account_owner_id(account_id)
        if not owner_id:
            return
        cursors = self._crm_cursor_map(account_id)
        now_ms = int(time.time() * 1000)
        work: list[tuple[str, list[dict[str, Any]], tuple[float, str] | None]] = []
        for box in boxes:
            chat_id = _message_box_id(box)
            if not _room_tracked(chat_id):
                continue
            messages = sorted(_message_box_messages(box), key=_message_time)
            latest = _message_time(messages[-1]) if messages else 0
            seen = cursors.get(chat_id, 0)
            if not latest or latest <= seen:
                continue
            fresh = [message for message in messages if _message_time(message) > seen]
            if not seen and now_ms - latest > CRM_BACKFILL_RECENT_DAYS * 86_400_000:
                # First sight of an old chat: keep the latest message as its summary.
                fresh = fresh[-1:]
            cursors[chat_id] = latest
            work.append((chat_id, fresh, self.outgoing_attribution.get((account_id, chat_id))))
        if not work:
            return
        try:
            self.crm_executor.submit(self._crm_ingest_line, account_id, owner_id, own_mid, work)
        except RuntimeError:
            return

    def _crm_ingest_line(
        self,
        account_id: str,
        owner_id: str,
        own_mid: str,
        work: list[tuple[str, list[dict[str, Any]], tuple[float, str] | None]],
    ) -> None:
        api: OkLine | None = None
        try:
            api = self.get_api(account_id)
        except Exception:
            api = None
        changed = False
        for chat_id, messages, attribution in work:
            items = []
            for message in messages:
                at = _message_time(message)
                encrypted = bool(message.get("chunks"))
                if encrypted and api is None:
                    summary: dict[str, Any] = {"text": "[encrypted]", "contentType": 0}
                elif encrypted:
                    with self.api_lock_for(account_id):
                        summary = _message_summary(cast(OkLine, api), message, {})
                else:
                    # Plain messages never touch the client.
                    summary = _message_summary(cast(OkLine, api), message, {})
                sender = str(message.get("from") or "")
                outgoing = sender == own_mid
                kind, sender_id = "customer", sender
                if outgoing:
                    by = ""
                    if attribution and at >= attribution[0] * 1000 - 60_000:
                        by = attribution[1]
                    kind, sender_id = _crm_sender(by)
                content_type = _coerce_int(summary.get("contentType"))
                items.append(
                    {
                        "externalId": str(message.get("id") or f"{chat_id}:{at}"),
                        "direction": "out" if outgoing else "in",
                        "senderKind": kind,
                        "senderId": sender_id,
                        "text": str(summary.get("text") or "") if content_type == 0 else
                        str(summary.get("fileName") or summary.get("altText") or ""),
                        "contentType": content_type,
                        "at": at,
                    }
                )
            try:
                result = self.crm.ingest(
                    owner_id=owner_id,
                    account_id=account_id,
                    channel="line",
                    chat_id=chat_id,
                    contact={"externalId": chat_id},
                    messages=items,
                )
            except Exception:
                traceback.print_exc()
                continue
            if result and (
                result.get("created")
                or result.get("status") != result.get("previousStatus")
                or result.get("reopened")
            ):
                changed = True
        if changed:
            self._bump_crm_version(account_id)

    # CrmContext: what the CRM service needs from the web app.
    def crm_tenant_id(self, user: dict[str, Any] | None) -> str:
        if not user or self.web_auth._is_god(user):
            return ""
        return str((self.tenant_user(user) or {}).get("id") or "")

    def crm_scope(self, user: dict[str, Any] | None) -> list[str] | None:
        if not user:
            return []
        if user.get("teamOwnerId"):
            return sorted({str(item) for item in user.get("staffAccountIds") or [] if item})
        return None

    def crm_accounts(self, owner_id: str) -> list[dict[str, Any]]:
        owner = self.web_auth._find_user(owner_id) or {}
        ids = {str(item) for item in owner.get("accountIds") or []}
        return [
            {
                "id": str(account.get("id") or ""),
                "label": str(account.get("label") or account.get("id") or ""),
                "channel": str(account.get("channel") or "line"),
            }
            for account in self.account_store.list_accounts(ids)
        ]

    def crm_members(self, owner_id: str) -> list[dict[str, Any]]:
        owner = self.web_auth._find_user(owner_id)
        if not owner:
            return []
        members = [
            {
                "id": owner_id,
                "name": str(owner.get("displayName") or owner.get("username") or ""),
                "role": "owner",
                "active": bool(owner.get("active", True)),
                "accountIds": sorted(str(item) for item in owner.get("accountIds") or []),
            }
        ]
        for item in self.web_auth.data.get("users", []):
            if isinstance(item, dict) and str(item.get("teamOwnerId") or "") == owner_id:
                members.append(
                    {
                        "id": str(item.get("id") or ""),
                        "name": str(item.get("displayName") or item.get("username") or ""),
                        "role": "staff",
                        "active": bool(item.get("active", True)),
                        "accountIds": sorted(
                            str(acct) for acct in item.get("staffAccountIds") or []
                        ),
                    }
                )
        return members

    def crm_has_permission(self, user: dict[str, Any] | None, permission: str) -> bool:
        return self.web_auth.has_permission(user, permission)

    def crm_notify(self, user_id: str, payload: dict[str, Any]) -> None:
        self.notify_user(user_id, payload)

    def crm_changed(self, account_ids: list[str]) -> None:
        for account_id in account_ids:
            self._bump_crm_version(account_id)

    def crm_resolve_names(
        self, account_id: str, external_ids: list[str]
    ) -> dict[str, dict[str, str]]:
        account = self.account_store.get(account_id) or {}
        if (account.get("channel") or "line") != "line" or self.account_store.requires_reauth(
            account_id
        ):
            return {}
        api = self.get_api(account_id)
        with self.api_lock_for(account_id):
            result = api.get_contacts(external_ids[:100])
        contacts = result.get("contacts", {}) if isinstance(result, dict) else {}
        profiles: dict[str, dict[str, str]] = {}
        for mid, wrapper in contacts.items():
            contact = wrapper.get("contact", wrapper) if isinstance(wrapper, dict) else {}
            if not isinstance(contact, dict):
                continue
            name = contact.get("displayNameOverridden") or contact.get("displayName") or ""
            if name:
                profiles[str(mid)] = {
                    "name": str(name),
                    "picture": str(contact.get("picturePath") or ""),
                }
        return profiles

    def crm_engine_tick(self) -> None:
        # Telegram rooms never pass through a LINE inbox fetch; close quiet ones here.
        for account in self.account_store.list_accounts():
            if account.get("channel") != "line":
                self.sweep_rooms(str(account.get("id") or ""))

    def notify_user(self, user_id: str, payload: dict[str, Any]) -> None:
        """Send one person a notification on every device they turned it on for."""
        for subscription in self._push_subscriptions():
            if subscription.get("userId") != user_id:
                continue
            try:
                self.push_executor.submit(self._deliver_push, subscription, payload)
            except RuntimeError:
                break
        user = self.web_auth._find_user(user_id) or {}
        owner_id = str(user.get("teamOwnerId") or user_id)
        account_id = str(payload.get("accountId") or "")
        chat_mid = str(payload.get("mid") or "")
        lines = [str(payload.get("body") or "")]
        if account_id and chat_mid:
            label = str((self.account_store.get(account_id) or {}).get("label") or account_id)
            _name, lines = self._chat_alert_lines(account_id, chat_mid, label)
        icon = {"assigned": "👤", "task_due": "📌", "task_assigned": "📝"}.get(
            str(payload.get("kind") or ""), "🔔"
        )
        self.staff_notifier.send_alert(
            owner_id,
            user_id,
            title=f"{icon} {payload.get('title') or ''}".strip(),
            lines=lines,
            account_id=account_id,
            chat_id=chat_mid,
        )

    # NotifyHost: what the Telegram staff notifier needs from the web app.
    def notify_encrypt(self, value: str) -> str:
        return self._encrypt_secret(value)

    def notify_decrypt(self, value: str) -> str:
        return self._decrypt_secret(value)

    def notify_proxy(self) -> str | None:
        value = str(os.getenv("LINEPASSPORT_TELEGRAM_PROXY") or "").strip()
        return _validate_proxy_url(value) if value else None

    def notify_user_record(self, user_id: str) -> dict[str, Any] | None:
        user = self.web_auth._find_user(user_id)
        if not user or not user.get("active", True) or self.web_auth._is_god(user):
            return None
        return dict(user)

    def notify_reply(
        self, user: dict[str, Any], account_id: str, chat_id: str, text: str
    ) -> str:
        if not self.web_auth.has_permission(user, "send") or not self.web_auth.can_access_account(
            user, account_id
        ):
            raise WebError(HTTPStatus.FORBIDDEN, "คุณไม่มีสิทธิ์ตอบแชทของบัญชีนี้", "forbidden")
        self.channel_send_text(account_id, chat_id, text[:5000], by=str(user["id"]))
        self.record_operator_send(account_id, user, chat_id, "text")
        name, _lines = self._chat_alert_lines(account_id, chat_id, "")
        return f"✓ ส่งถึง {name} แล้ว"

    def notify_claim(self, user: dict[str, Any], account_id: str, chat_id: str) -> str:
        self.crm.assign(user, {"accountId": account_id, "chatId": chat_id, "assignee": "me"})
        return "รับเรื่องแล้ว แชทนี้เป็นของคุณ"

    def notify_close(self, user: dict[str, Any], account_id: str, chat_id: str) -> str:
        self.crm.set_status(
            user, {"accountId": account_id, "chatId": chat_id, "status": "closed"}
        )
        return "ปิดแชทแล้ว"

    def telegram_can_manage(self, user: dict[str, Any] | None) -> bool:
        return bool(
            user
            and self.web_auth.has_permission(user, "manage_accounts")
            and not user.get("teamOwnerId")
        )

    def channel_send_text(self, account_id: str, chat_id: str, text: str, *, by: str) -> str:
        """Send a text to a chat from any connected account; returns the message id."""
        channel = _account_channel(self.account_store.get(account_id))
        if channel == "telegram_bot":
            target = self._telegram_target(account_id, chat_id)
            client = self.telegram.client(account_id)
            with self.api_lock_for(account_id):
                try:
                    sent = client.send_message(target, text)
                except TelegramApiError as exc:
                    raise self._telegram_send_error(account_id, exc) from None
                self.note_outgoing(account_id, chat_id, by)
            self._telegram_record_outgoing(
                account_id, chat_id, sent, by=by, text=text, content_type=0, meta={}
            )
            return str(sent.get("message_id") or "")
        if channel == "telegram_user":
            target = self._telegram_target(account_id, chat_id)
            with self.api_lock_for(account_id):
                sent = self._telegram_user_call(
                    account_id, lambda adapter: adapter.send_text(target, text)
                )
                self.note_outgoing(account_id, chat_id, by)
            self._telegram_record_outgoing(
                account_id, chat_id, sent, by=by, text=text, content_type=0,
                meta={"mtproto": True},
            )
            return str(sent.get("message_id") or "")
        if channel != "line":
            raise _line_only()
        api = self.get_api(account_id)
        with self.api_lock_for(account_id):
            result = api.send_text(chat_id, text)
            self.note_outgoing(account_id, chat_id, by)
        self.invalidate_inbox_snapshot(account_id)
        self.request_inbox_refresh(account_id)
        return str(result.get("id") or "") if isinstance(result, dict) else ""

    # -- Telegram bot accounts ------------------------------------------------
    def _telegram_target(self, account_id: str, chat_id: str) -> int:
        try:
            target = telegram_user_id(chat_id)
        except ValueError:
            raise WebError(
                HTTPStatus.BAD_REQUEST, "Pick a Telegram chat first.", "telegram_chat_invalid"
            ) from None
        if not self.crm.conversation_for_chat(account_id, chat_id):
            # A bot can only write to people who started it.
            raise WebError(
                HTTPStatus.BAD_REQUEST,
                "This person has not started a chat with the bot yet.",
                "telegram_not_started",
            )
        return target

    def _telegram_user_call(self, account_id: str, fn: Callable[[Any], Any]) -> Any:
        try:
            return fn(self.telegram_users.adapter(account_id))
        except TelegramError as exc:
            if exc.code == "telegram_reauth":
                self.tg_auth_failed(account_id)
            raise

    def _telegram_send_error(self, account_id: str, exc: TelegramApiError) -> WebError:
        if exc.blocked:
            return WebError(
                HTTPStatus.CONFLICT,
                "This customer blocked the bot or never pressed Start.",
                "telegram_blocked",
            )
        if exc.unauthorized:
            self.tg_auth_failed(account_id)
            return WebError(
                HTTPStatus.UNAUTHORIZED,
                "Telegram rejected the bot token. Paste a new token for this account.",
                "telegram_reauth",
            )
        if exc.network:
            return WebError(HTTPStatus.BAD_GATEWAY, exc.message, "upstream_error")
        return WebError(HTTPStatus.BAD_REQUEST, exc.message, "telegram_send_failed")

    def _telegram_record_outgoing(
        self,
        account_id: str,
        chat_id: str,
        sent: dict[str, Any],
        *,
        by: str,
        text: str,
        content_type: int,
        meta: dict[str, Any],
    ) -> None:
        kind, sender_id = _crm_sender(by)
        result: dict[str, Any] = {}
        try:
            result = self.crm.ingest(
                owner_id=self._account_owner_id(account_id),
                account_id=account_id,
                channel=_account_channel(self.account_store.get(account_id)),
                chat_id=chat_id,
                contact={"externalId": chat_id[3:]},
                messages=[
                    {
                        "externalId": str(sent.get("message_id") or uuid.uuid4().hex),
                        "direction": "out",
                        "senderKind": kind,
                        "senderId": sender_id,
                        "text": text,
                        "contentType": content_type,
                        "meta": meta,
                        # Our own clock, in ms: Telegram dates are whole seconds.
                        "at": int(time.time() * 1000),
                    }
                ],
                track_unread=True,
            )
        except Exception:
            traceback.print_exc()
        self._bump_inbox_version(account_id)
        if result and result.get("status") != result.get("previousStatus"):
            self._bump_crm_version(account_id)

    def _telegram_secret(self, account_id: str) -> dict[str, Any]:
        account = self.account_store.get(account_id) or {}
        path = str(account.get("credentialFile") or "")
        if not path or not os.path.exists(path):
            return {}
        try:
            with open(path, encoding="utf-8") as handle:
                stored = json.load(handle)
            secret = json.loads(self._decrypt_secret(str(stored.get("secret") or "")) or "{}")
        except (OSError, ValueError):
            traceback.print_exc()
            return {}
        return secret if isinstance(secret, dict) else {}

    def tg_token(self, account_id: str) -> str:
        return str(self._telegram_secret(account_id).get("token") or "")

    def tgu_credentials(self, account_id: str) -> dict[str, Any]:
        return self._telegram_secret(account_id)

    def _write_telegram_secret(self, path: str, secret: dict[str, Any]) -> None:
        _write_json_file(path, {"secret": self._encrypt_secret(json.dumps(secret))})

    def _write_telegram_credentials(self, path: str, token: str) -> None:
        self._write_telegram_secret(path, {"token": token})

    def tg_backfill(self, account_id: str, messages: list[dict[str, Any]]) -> None:
        """Recent chats when a personal account connects: history only, no alerts."""
        account = self.account_store.get(account_id)
        if not account:
            return
        owner_id = self._account_owner_id(account_id)
        for message in messages:
            outgoing = bool(message.get("outgoing"))
            try:
                self.crm.ingest(
                    owner_id=owner_id,
                    account_id=account_id,
                    channel=_account_channel(account),
                    chat_id=str(message.get("chatId") or ""),
                    contact={
                        "externalId": str(message.get("userId") or ""),
                        "name": message.get("name"),
                        "username": message.get("username"),
                    },
                    messages=[
                        {
                            "externalId": message.get("externalId"),
                            "direction": "out" if outgoing else "in",
                            "senderKind": "app" if outgoing else "customer",
                            "senderId": "" if outgoing else str(message.get("userId") or ""),
                            "text": message.get("text"),
                            "contentType": message.get("contentType"),
                            "meta": message.get("meta") or {},
                            "at": message.get("at"),
                        }
                    ],
                )
            except Exception:
                traceback.print_exc()
        self._bump_inbox_version(account_id)
        self._bump_crm_version(account_id)

    def tg_receive(self, account_id: str, message: dict[str, Any]) -> None:
        account = self.account_store.get(account_id)
        if not account:
            return
        owner_id = self._account_owner_id(account_id)
        chat_id = str(message.get("chatId") or "")
        outgoing = bool(message.get("outgoing"))
        if outgoing:
            kind, sender_id = _crm_sender(
                self._outgoing_attribution_for(account_id, chat_id) or "telegram_app"
            )
        else:
            kind, sender_id = "customer", str(message.get("userId") or "")
        result = self.crm.ingest(
            owner_id=owner_id,
            account_id=account_id,
            channel=_account_channel(account),
            chat_id=chat_id,
            contact={
                "externalId": str(message.get("userId") or ""),
                "name": message.get("name"),
                "username": message.get("username"),
            },
            messages=[
                {
                    "externalId": message.get("externalId"),
                    "direction": "out" if outgoing else "in",
                    "senderKind": kind,
                    "senderId": sender_id,
                    "text": message.get("text"),
                    "contentType": message.get("contentType"),
                    "meta": message.get("meta") or {},
                    "at": message.get("at"),
                }
            ],
            track_unread=True,
        )
        if not outgoing:
            self.note_incoming(account_id, chat_id, _coerce_int(message.get("at")))
        self._bump_inbox_version(account_id)
        if result and (
            result.get("created") or result.get("status") != result.get("previousStatus")
        ):
            self._bump_crm_version(account_id)
        if not outgoing:
            self._telegram_auto_reply(account_id, owner_id, chat_id, message)

    def tg_auth_failed(self, account_id: str) -> None:
        if _account_channel(self.account_store.get(account_id)) == "telegram_user":
            self.account_store.mark_session_reauth_required(
                account_id, "This Telegram account was signed out. Sign in again."
            )
            threading.Thread(
                target=self.telegram_users.stop, args=(account_id,), daemon=True
            ).start()
            return
        self.account_store.mark_session_reauth_required(
            account_id, "Telegram rejected the bot token. Paste a new token."
        )
        self.telegram.stop(account_id)

    def tg_offset(self, account_id: str) -> int:
        raw = self.store.get(f"telegram_runtime:{account_id}", {})
        return _coerce_int(raw.get("offset")) if isinstance(raw, dict) else 0

    def tg_save_offset(self, account_id: str, offset: int) -> None:
        self.store.set(f"telegram_runtime:{account_id}", {"offset": int(offset)})

    def _telegram_auto_reply(
        self, account_id: str, owner_id: str, chat_id: str, message: dict[str, Any]
    ) -> None:
        question = str(message.get("text") or "").strip()
        if _coerce_int(message.get("contentType")) != 0 or not question:
            return
        record = self._ai_auto_reply_record(account_id)
        enabled_at_ms = _coerce_int(record.get("enabledAtMs"))
        if not record.get("enabled") or _coerce_int(message.get("at")) < enabled_at_ms:
            return
        if not self._ai_auto_reply_chat_enabled(record, "contact", chat_id):
            return
        inflight_key = (account_id, chat_id)
        with self.ai_auto_reply_lock:
            if inflight_key in self.ai_auto_reply_inflight:
                return
        if not self._consume_ai_auto_reply_rate(account_id, chat_id):
            self.append_bot_log(
                "ai.auto_reply.rate_limit",
                account_id=account_id,
                ok=False,
                detail=f"contact:{chat_id}",
                data={"chatMid": chat_id, "chatType": "contact"},
            )
            return
        with self.ai_auto_reply_lock:
            self.ai_auto_reply_inflight.add(inflight_key)
        name = str(message.get("name") or "")
        try:
            self.ai_auto_reply_executor.submit(
                self._process_ai_auto_reply,
                {
                    "accountId": account_id,
                    "chatMid": chat_id,
                    "chatType": "contact",
                    "question": question[:MAX_ASSISTANT_QUESTION_LENGTH],
                    "senderMid": chat_id,
                    "senderName": name,
                    "chatName": name,
                    "messageId": message.get("externalId"),
                    "cursor": None,
                    "enabledAtMs": enabled_at_ms,
                    "ownerId": owner_id,
                },
            )
        except RuntimeError:
            with self.ai_auto_reply_lock:
                self.ai_auto_reply_inflight.discard(inflight_key)

    def add_telegram_bot(self, body: dict[str, Any], user: dict[str, Any] | None) -> dict[str, Any]:
        owner_id = self._require_account_adder(user)
        token = str(body.get("token") or "").strip()
        me = self._check_telegram_token(token)
        bot_id = str(me.get("id"))
        for account in self.account_store.list_accounts():
            if account.get("channel") == "telegram_bot" and str(account.get("botId")) == bot_id:
                raise WebError(
                    HTTPStatus.CONFLICT, "This bot is already connected.", "telegram_bot_exists"
                )
        notify_tenants = self.staff_notifier._data()["tenants"].values()
        if any(str(t.get("botId")) == bot_id for t in notify_tenants if isinstance(t, dict)):
            raise WebError(
                HTTPStatus.CONFLICT,
                "This bot already sends staff alerts. Create a separate bot for customers.",
                "telegram_bot_in_use",
            )
        username = str(me.get("username") or "")
        label = str(body.get("label") or "").strip()[:MAX_NAME_LENGTH] or str(
            me.get("first_name") or username
        )
        record = {
            "id": f"tg-{_safe_slug(username or label, 'bot')}",
            "label": label,
            "channel": "telegram_bot",
            "mid": f"tgu{bot_id}",
            "userid": f"@{username}" if username else "",
            "botId": bot_id,
            "botUsername": username,
            "sessionState": "connected",
            "createdAt": _now_iso(),
            "updatedAt": _now_iso(),
        }
        account = self._create_telegram_account(record, {"token": token}, owner_id)
        self.telegram.start(account["id"])
        return self._accounts_payload(owner_id, account["id"])

    def _create_telegram_account(
        self, record: dict[str, Any], secret: dict[str, Any], owner_id: str
    ) -> dict[str, Any]:
        """Save a Telegram account, its encrypted secret and its owner in one go."""
        with self.lock, self.web_auth.lock, self.account_store.lock:
            previous_accounts = copy.deepcopy(self.account_store.data)
            previous_auth = copy.deepcopy(self.web_auth.data)
            credential_file = ""
            try:
                account = self.account_store.add_channel_account(record, owner_id)
                os.makedirs(self.config.accounts_dir, exist_ok=True)
                credential_file = str(
                    Path(self.config.accounts_dir) / f"{account['id']}.telegram.json"
                )
                self._write_telegram_secret(credential_file, secret)
                for stored in self.account_store.data["accounts"]:
                    if isinstance(stored, dict) and stored.get("id") == account["id"]:
                        stored["credentialFile"] = credential_file
                auth_data = copy.deepcopy(self.web_auth.data)
                owner = next(
                    (u for u in auth_data.get("users", []) if str(u.get("id") or "") == owner_id),
                    None,
                )
                if owner is None:
                    raise WebError(HTTPStatus.NOT_FOUND, "Account owner not found.")
                owner["accountIds"] = sorted(set(owner.get("accountIds") or []) | {account["id"]})
                owner["updatedAt"] = _now_iso()
                self.store.set_many({"accounts": self.account_store.data, "auth": auth_data})
                self.web_auth.data = auth_data
            except Exception:
                self.account_store.data = previous_accounts
                self.web_auth.data = previous_auth
                if credential_file and os.path.exists(credential_file):
                    os.remove(credential_file)
                raise
        self.store.set(f"telegram_runtime:{account['id']}", {"offset": 0})
        return account

    def _accounts_payload(self, owner_id: str, account_id: str) -> dict[str, Any]:
        # The request's user copy predates the new account; list from the saved owner.
        fresh_owner = self.web_auth._find_user(owner_id)
        return {
            "ok": True,
            "account": next(
                a for a in self.account_store.list_accounts() if a["id"] == account_id
            ),
            "accounts": {
                "accounts": self.account_store.list_accounts(
                    self.web_auth.allowed_account_ids(fresh_owner)
                )
            },
        }

    def _require_account_adder(self, user: dict[str, Any] | None) -> str:
        if not user or not self.web_auth.has_permission(user, "manage_accounts"):
            raise WebError(HTTPStatus.FORBIDDEN, "Permission denied.", "forbidden")
        if user.get("teamOwnerId"):
            raise WebError(HTTPStatus.FORBIDDEN, "Only the shop owner can add accounts.", "forbidden")
        return str(user.get("id") or "")

    def tg_user_available(self) -> dict[str, Any]:
        return {"ok": True, "available": telethon_available(), "install": INSTALL_HINT}

    def tg_user_login_start(
        self, body: dict[str, Any], user: dict[str, Any] | None
    ) -> dict[str, Any]:
        owner_id = self._require_account_adder(user)
        reconnect_id = str(body.get("reconnectAccountId") or "").strip()
        if reconnect_id:
            account = self.account_store.get(reconnect_id)
            if (
                not account
                or _account_channel(account) != "telegram_user"
                or self._account_owner_id(reconnect_id) != owner_id
            ):
                raise WebError(HTTPStatus.NOT_FOUND, "Telegram account not found.")
        return self.telegram_users.begin_login(
            owner_id,
            body.get("apiId"),
            str(body.get("apiHash") or ""),
            str(body.get("phone") or ""),
            {
                "label": str(body.get("label") or "").strip()[:MAX_NAME_LENGTH],
                "reconnectAccountId": reconnect_id,
            },
        )

    def tg_user_login_code(self, body: dict[str, Any], user: dict[str, Any] | None) -> dict[str, Any]:
        owner_id = self._require_account_adder(user)
        finished = self.telegram_users.submit_code(owner_id, str(body.get("code") or ""))
        if finished is None:
            return {"ok": True, "state": "password"}
        return self._finish_telegram_user(owner_id, finished)

    def tg_user_login_password(
        self, body: dict[str, Any], user: dict[str, Any] | None
    ) -> dict[str, Any]:
        owner_id = self._require_account_adder(user)
        finished = self.telegram_users.submit_password(owner_id, str(body.get("password") or ""))
        return self._finish_telegram_user(owner_id, finished)

    def tg_user_login_cancel(self, user: dict[str, Any] | None) -> dict[str, Any]:
        self.telegram_users.cancel_login(str((user or {}).get("id") or ""))
        return {"ok": True, "state": "idle"}

    def _finish_telegram_user(self, owner_id: str, finished: dict[str, Any]) -> dict[str, Any]:
        me = finished["me"]
        telegram_id = str(me.get("id"))
        secret = {
            "apiId": finished["apiId"],
            "apiHash": finished["apiHash"],
            "session": finished["session"],
        }
        reconnect_id = str(finished.get("reconnectAccountId") or "")
        if reconnect_id:
            account = self.account_store.get(reconnect_id) or {}
            if str(account.get("telegramUserId")) != telegram_id:
                raise WebError(
                    HTTPStatus.BAD_REQUEST,
                    "You signed in to a different Telegram account.",
                    "telegram_account_mismatch",
                )
            self._write_telegram_secret(str(account.get("credentialFile") or ""), secret)
            self.account_store.mark_session_connected(reconnect_id)
            self.telegram_users.start(reconnect_id)
            return {**self._accounts_payload(owner_id, reconnect_id), "state": "done"}
        for account in self.account_store.list_accounts():
            if account.get("channel") == "telegram_user" and str(
                account.get("telegramUserId")
            ) == telegram_id:
                raise WebError(
                    HTTPStatus.CONFLICT,
                    "This Telegram account is already connected.",
                    "telegram_account_exists",
                )
        username = str(me.get("username") or "")
        phone = str(me.get("phone") or "")
        name = " ".join(p for p in (me.get("first_name"), me.get("last_name")) if p)
        label = str(finished.get("label") or "") or name or username or "Telegram"
        record = {
            "id": f"tgu-{_safe_slug(username or phone[-4:] or label, 'telegram')}",
            "label": label,
            "channel": "telegram_user",
            "mid": f"tgu{telegram_id}",
            "userid": f"@{username}" if username else (f"+…{phone[-4:]}" if phone else ""),
            "username": username,
            "telegramUserId": telegram_id,
            "sessionState": "connected",
            "createdAt": _now_iso(),
            "updatedAt": _now_iso(),
        }
        account = self._create_telegram_account(record, secret, owner_id)
        self.telegram_users.start(account["id"])
        return {**self._accounts_payload(owner_id, account["id"]), "state": "done"}

    def update_telegram_token(
        self, body: dict[str, Any], user: dict[str, Any] | None
    ) -> dict[str, Any]:
        account_id = _required_account_id(str(body.get("accountId") or ""))
        account = self.account_store.get(account_id)
        if not account or _account_channel(account) != "telegram_bot":
            raise WebError(HTTPStatus.NOT_FOUND, "Telegram account not found.")
        if not self.web_auth.owns_account(user, account_id) or not self.web_auth.has_permission(
            user, "manage_accounts"
        ):
            raise WebError(HTTPStatus.FORBIDDEN, "Permission denied.", "forbidden")
        token = str(body.get("token") or "").strip()
        me = self._check_telegram_token(token)
        if str(me.get("id")) != str(account.get("botId")):
            raise WebError(
                HTTPStatus.BAD_REQUEST,
                "This token belongs to a different bot.",
                "telegram_bot_mismatch",
            )
        self._write_telegram_credentials(str(account.get("credentialFile") or ""), token)
        self.account_store.mark_session_connected(account_id)
        self.telegram.stop(account_id)
        self.telegram.start(account_id)
        return {"ok": True, "status": self.status(account_id, user)}

    def _check_telegram_token(self, token: str) -> dict[str, Any]:
        if not valid_token(token):
            raise WebError(
                HTTPStatus.BAD_REQUEST,
                "That does not look like a bot token from @BotFather.",
                "telegram_token_invalid",
            )
        client = self.telegram.client_factory(token, proxy=self.notify_proxy())
        try:
            me = client.get_me()
            try:
                client.delete_webhook()
            except TelegramApiError:
                pass
        except TelegramApiError as exc:
            if exc.unauthorized:
                raise WebError(
                    HTTPStatus.BAD_REQUEST, exc.message, "telegram_token_rejected"
                ) from None
            raise WebError(HTTPStatus.BAD_GATEWAY, exc.message, "telegram_unreachable") from None
        finally:
            client.close()
        if not me.get("is_bot"):
            raise WebError(HTTPStatus.BAD_REQUEST, "That token is not a bot.", "telegram_token_invalid")
        return me

    def _telegram_status(
        self, account: dict[str, Any], allowed_ids: set[str] | None
    ) -> dict[str, Any]:
        account_id = str(account.get("id") or "")
        session_state = self.account_store.session_state(account_id)
        authenticated = session_state == "connected"
        personal = _account_channel(account) == "telegram_user"
        runtime = self.telegram_users if personal else self.telegram
        if authenticated and not runtime.running(account_id) and not personal:
            runtime.start(account_id)
        username = str(account.get("botUsername") or account.get("username") or "")
        return {
            "version": __version__,
            "authenticated": authenticated,
            "activeAccountId": account_id,
            "accounts": self.account_store.list_accounts(allowed_ids),
            "storage": self.store.label(),
            "nodeAvailable": LtsmBridge.is_available(),
            "e2eeReady": False,
            "profile": {
                "mid": str(account.get("mid") or ""),
                "displayName": str(account.get("label") or username),
                "userid": str(account.get("userid") or ""),
                "statusMessage": (
                    str(account.get("userid") or "")
                    if personal
                    else (f"t.me/{username}" if username else "")
                ),
                "picturePath": "",
            },
            "profileError": None,
            "sessionState": session_state,
            "sessionError": str(account.get("sessionError") or ""),
            "loginRequired": session_state == "reauth_required",
            "channel": _account_channel(account),
            "capabilities": list(ACCOUNT_CAPABILITIES.get(_account_channel(account), [])),
        }

    def _telegram_message(
        self, row: dict[str, Any], own_mid: str, chat_id: str, names: dict[str, str]
    ) -> dict[str, Any]:
        meta = row.get("meta")
        meta = json.loads(meta) if isinstance(meta, str) and meta else (meta or {})
        outgoing = row.get("direction") != "in"
        sender = own_mid if outgoing else chat_id
        content_type = _coerce_int(row.get("content_type"))
        duration = meta.get("duration")
        return {
            "id": str(row.get("external_id") or ""),
            "from": sender,
            "fromName": names.get(sender) or sender,
            "to": chat_id if outgoing else own_mid,
            "text": row.get("text") or "",
            "contentType": content_type,
            "stickerId": None,
            "fileName": meta.get("fileName") or None,
            "fileSize": str(meta.get("fileSize") or "") or None,
            "durationMs": int(duration) * 1000 if isinstance(duration, (int, float)) else None,
            "location": _message_location({"location": meta.get("location")})
            if meta.get("location")
            else None,
            "contactMid": None,
            "contactName": meta.get("contactName") or None,
            "altText": None,
            "linkUrl": None,
            "eventKey": None,
            "eventNames": [],
            "createdTime": _coerce_int(row.get("at")),
            "encrypted": False,
            "mediaReady": True,
            "hasPreview": False,
        }

    def _telegram_chat_rows(self, account_id: str) -> list[dict[str, Any]]:
        account = self.account_store.get(account_id) or {}
        own_mid = str(account.get("mid") or "")
        rows = []
        for rank, row in enumerate(self.crm.account_chats(account_id)):
            username = str(row.get("identity_username") or "")
            name = str(row.get("display_name") or row.get("identity_name") or "") or (
                f"@{username}" if username else row["chat_id"]
            )
            preview = str(row.get("last_preview") or "")
            content_type = TELEGRAM_PREVIEW_TYPES.get(preview, 0)
            outgoing = _coerce_int(row.get("last_outbound_at")) >= _coerce_int(
                row.get("last_inbound_at")
            ) and _coerce_int(row.get("last_outbound_at")) > 0
            last_at = _coerce_int(row.get("last_message_at"))
            rows.append(
                {
                    "mid": row["chat_id"],
                    "name": name,
                    "statusMessage": f"@{username}" if username else "",
                    "picturePath": None,
                    "rank": rank,
                    "unreadCount": _coerce_int(row.get("unread")),
                    "lastMessageAt": last_at,
                    "lastMessage": {
                        "id": None,
                        "from": own_mid if outgoing else row["chat_id"],
                        "text": "" if content_type else preview,
                        "contentType": content_type,
                        "createdTime": last_at,
                    }
                    if last_at
                    else None,
                }
            )
        return rows

    def tg_conversations(self, account_id: str) -> dict[str, Any]:
        self.watch_inbox(account_id)
        items = [
            {key: row[key] for key in ("mid", "rank", "unreadCount", "lastMessageAt", "lastMessage")}
            for row in self._telegram_chat_rows(account_id)
        ]
        return {"conversations": items, "count": len(items)}

    def tg_contacts(self, account_id: str, query: dict[str, list[str]]) -> dict[str, Any]:
        search = _query_one(query, "search", "").lower()
        limit = _query_int(query, "limit", 250, minimum=1, maximum=1000)
        rows = [
            row
            for row in self._telegram_chat_rows(account_id)
            if not search or search in str(row["name"]).lower()
        ][:limit]
        return {"contacts": rows, "count": len(rows)}

    def tg_messages(self, account_id: str, query: dict[str, list[str]]) -> dict[str, Any]:
        chat_mid = _query_one(query, "chat_mid")
        if not chat_mid:
            raise WebError(HTTPStatus.BAD_REQUEST, "chat_mid is required.")
        count = _query_int(query, "count", 30, minimum=1, maximum=200)
        account = self.account_store.get(account_id) or {}
        own_mid = str(account.get("mid") or "")
        conv = self.crm.conversation_for_chat(account_id, chat_mid) or {}
        names = {own_mid: str(account.get("label") or ""), chat_mid: str(conv.get("display_name") or "")}
        rows = self.crm.chat_messages(account_id, chat_mid, limit=count)
        messages = []
        for row in rows:
            message = self._telegram_message(row, own_mid, chat_mid, names)
            messages.append(message)
            if message["contentType"] in (1, 2, 3, 14) and message["text"]:
                # The chat view shows media without text; keep the caption visible.
                messages.append(
                    {**message, "id": f"{message['id']}:caption", "contentType": 0,
                     "fileName": None, "fileSize": None, "durationMs": None}
                )
                message["text"] = ""
        return {"messages": messages, "count": len(messages)}

    def tg_mark_read(self, account_id: str, body: dict[str, Any]) -> dict[str, Any]:
        chat_mid = str(body.get("chatMid") or "").strip()
        if not chat_mid:
            raise WebError(HTTPStatus.BAD_REQUEST, "chatMid is required.")
        self.crm.mark_read(account_id, chat_mid)
        return {"ok": True, "chatMid": chat_mid, "lastMessageId": body.get("lastMessageId")}

    def tg_send(
        self, account_id: str, body: dict[str, Any], user: dict[str, Any] | None
    ) -> dict[str, Any]:
        to = str(body.get("to") or "").strip()
        text = str(body.get("text") or "")
        if not text:
            raise WebError(HTTPStatus.BAD_REQUEST, "text is required.")
        if body.get("encrypt"):
            raise _line_only()
        message_id = self.channel_send_text(
            account_id, to, text, by=str((user or {}).get("id") or "")
        )
        self.record_operator_send(account_id, user, to, "text")
        return {"ok": True, "messageId": message_id}

    def tg_send_media(
        self,
        account_id: str,
        to: str,
        raw: bytes,
        name: str,
        is_image: bool,
        user: dict[str, Any] | None,
    ) -> dict[str, Any]:
        target = self._telegram_target(account_id, to)
        if _account_channel(self.account_store.get(account_id)) == "telegram_user":
            with self.api_lock_for(account_id):
                sent = self._telegram_user_call(
                    account_id, lambda adapter: adapter.send_file(target, raw, name, is_image)
                )
                self.note_outgoing(account_id, to, str((user or {}).get("id") or ""))
            self._telegram_record_outgoing(
                account_id,
                to,
                sent,
                by=str((user or {}).get("id") or ""),
                text="",
                content_type=1 if is_image else 14,
                meta={"mtproto": True, "fileName": name, "fileSize": len(raw)},
            )
            self.record_operator_send(account_id, user, to, "media")
            return {"ok": True, "messageId": str(sent.get("message_id") or "")}
        client = self.telegram.client(account_id)
        with self.api_lock_for(account_id):
            try:
                sent = (
                    client.send_photo(target, raw, filename=name)
                    if is_image
                    else client.send_document(target, raw, filename=name)
                )
            except TelegramApiError as exc:
                raise self._telegram_send_error(account_id, exc) from None
            self.note_outgoing(account_id, to, str((user or {}).get("id") or ""))
        photos = sent.get("photo") or []
        document = sent.get("document") or {}
        file_id = (
            max(photos, key=lambda p: int(p.get("width") or 0)).get("file_id")
            if photos
            else document.get("file_id")
        )
        self._telegram_record_outgoing(
            account_id,
            to,
            sent,
            by=str((user or {}).get("id") or ""),
            text="",
            content_type=1 if is_image else 14,
            meta={"fileId": file_id, "fileName": name, "fileSize": len(raw)},
        )
        self.record_operator_send(account_id, user, to, "media")
        return {"ok": True, "messageId": str(sent.get("message_id") or "")}

    def tg_media(
        self, account_id: str, chat_mid: str, message_id: str
    ) -> tuple[bytes, str, int]:
        row = self.crm.find_message(account_id, chat_mid, message_id)
        if not row:
            raise WebError(HTTPStatus.NOT_FOUND, "Media not available.")
        meta = json.loads(row.get("meta") or "{}")
        if meta.get("mtproto"):
            target = telegram_user_id(chat_mid)
            data, filename = self._telegram_user_call(
                account_id, lambda adapter: adapter.download(target, int(message_id))
            )
            return data, str(meta.get("fileName") or filename), _coerce_int(row.get("content_type"))
        file_id = str(meta.get("fileId") or meta.get("thumbId") or "")
        if not file_id:
            raise WebError(HTTPStatus.NOT_FOUND, "Media not available.")
        client = self.telegram.client(account_id)
        try:
            info = client.get_file(file_id)
            data = client.download(str(info.get("file_path") or ""))
        except TelegramApiError as exc:
            raise WebError(HTTPStatus.NOT_FOUND, "Media not available.") from exc
        filename = str(meta.get("fileName") or "") or os.path.basename(
            str(info.get("file_path") or "file")
        )
        return data, filename, _coerce_int(row.get("content_type"))

    def tg_avatar(self, account_id: str) -> bytes:
        account = self.account_store.get(account_id) or {}
        if _account_channel(account) != "telegram_bot":
            raise WebError(
                HTTPStatus.NOT_FOUND, "No profile picture.", "profile_picture_not_found"
            )
        client = self.telegram.client(account_id)
        try:
            file_id = client.user_photo_file_id(str(account.get("botId") or ""))
            if not file_id:
                raise TelegramApiError("no photo", error_code=404)
            info = client.get_file(file_id)
            return client.download(str(info.get("file_path") or ""))
        except TelegramApiError as exc:
            raise WebError(
                HTTPStatus.NOT_FOUND,
                "The bot has no profile picture.",
                "profile_picture_not_found",
            ) from exc

    def _bump_inbox_version(self, account_id: str) -> None:
        with self.inbox_events:
            self.inbox_versions[account_id] = self.inbox_versions.get(account_id, 0) + 1
            self.inbox_events.notify_all()

    def inbox_version(self, account_id: str) -> int:
        with self.inbox_events:
            return self.inbox_versions.get(account_id, 0)

    def _bump_crm_version(self, account_id: str) -> None:
        """Customer records of this account changed (status, assignee, tags...)."""
        with self.inbox_events:
            self.crm_versions[account_id] = self.crm_versions.get(account_id, 0) + 1
            self.inbox_events.notify_all()

    def crm_version(self, account_id: str) -> int:
        with self.inbox_events:
            return self.crm_versions.get(account_id, 0)

    def wait_live_event(
        self, account_id: str, inbox: int, crm: int, timeout: float
    ) -> tuple[int, int] | None:
        """Block until the inbox or the customer records of ``account_id`` change."""
        deadline = time.monotonic() + timeout
        with self.inbox_events:
            while True:
                current = (
                    self.inbox_versions.get(account_id, 0),
                    self.crm_versions.get(account_id, 0),
                )
                if current != (inbox, crm):
                    return current
                remaining = deadline - time.monotonic()
                if remaining <= 0 or self.ai_auto_reply_engine.stop_event.is_set():
                    return None
                self.inbox_events.wait(remaining)

    def wait_inbox_event(
        self, account_id: str, version: int, timeout: float
    ) -> int | None:
        """Block until the account's inbox version moves past ``version``."""
        deadline = time.monotonic() + timeout
        with self.inbox_events:
            while True:
                current = self.inbox_versions.get(account_id, 0)
                if current != version:
                    return current
                remaining = deadline - time.monotonic()
                if remaining <= 0 or self.ai_auto_reply_engine.stop_event.is_set():
                    return None
                self.inbox_events.wait(remaining)

    def _room_states(self, account_id: str) -> dict[str, dict[str, Any]]:
        cached = self.room_states_cache.get(account_id)
        if cached is not None:
            return cached
        raw = self.store.get(f"room_state:{account_id}", {})
        rooms = raw.get("rooms") if isinstance(raw, dict) else None
        rooms = (
            {mid: room for mid, room in rooms.items() if isinstance(room, dict)}
            if isinstance(rooms, dict)
            else {}
        )
        self.room_states_cache[account_id] = rooms
        return rooms

    def _save_room_states(self, account_id: str, rooms: dict[str, Any]) -> None:
        if len(rooms) > MAX_TRACKED_ROOMS:
            ordered = sorted(
                rooms.items(),
                key=lambda item: max(
                    _coerce_int(item[1].get("lastIncomingAt")),
                    _coerce_int(item[1].get("lastOutgoingAt")),
                ),
                reverse=True,
            )
            rooms.clear()
            rooms.update(ordered[:MAX_TRACKED_ROOMS])
        self.room_states_cache[account_id] = rooms
        self.store.set(f"room_state:{account_id}", {"rooms": rooms})

    def _kpi_responses(self, account_id: str) -> list[dict[str, Any]]:
        raw = self.store.get(f"kpi_responses:{account_id}", {})
        items = raw.get("responses") if isinstance(raw, dict) else None
        return [item for item in items if isinstance(item, dict)] if isinstance(
            items, list
        ) else []

    def _record_kpi_response(self, account_id: str, record: dict[str, Any]) -> None:
        items = self._kpi_responses(account_id)
        items.append(record)
        cutoff = int(time.time() * 1000) - KPI_RETENTION_DAYS * 86_400_000
        items = [item for item in items if _coerce_int(item.get("askedAt")) >= cutoff]
        self.store.set(
            f"kpi_responses:{account_id}", {"responses": items[-MAX_KPI_RESPONSES:]}
        )

    def _outgoing_attribution_for(self, account_id: str, chat_mid: str) -> str:
        entry = self.outgoing_attribution.get((account_id, chat_mid))
        if entry and time.time() - entry[0] <= OUTGOING_ATTRIBUTION_TTL_SECONDS:
            return entry[1]
        return ""

    def _answer_room(
        self,
        account_id: str,
        chat_mid: str,
        room: dict[str, Any],
        answered_ms: int,
        by: str,
        *,
        record: bool = True,
    ) -> None:
        asked_ms = _coerce_int(room.get("firstUnansweredAt")) or answered_ms
        room["status"] = "answered"
        room["answeredBy"] = by
        room["answeredAt"] = answered_ms
        room["firstUnansweredAt"] = None
        room["lastOutgoingAt"] = max(_coerce_int(room.get("lastOutgoingAt")), answered_ms)
        if record:
            self._record_kpi_response(
                account_id,
                {
                    "chatMid": chat_mid,
                    "askedAt": asked_ms,
                    "answeredAt": answered_ms,
                    "answeredBy": by,
                    "responseSeconds": max(0, round((answered_ms - asked_ms) / 1000)),
                },
            )

    def note_outgoing(self, account_id: str, chat_mid: str, by: str) -> None:
        """Remember who sent to a chat so the inbox tracker can attribute it."""
        account_id = str(account_id or "")
        chat_mid = str(chat_mid or "")
        if not account_id or not chat_mid:
            return
        now = time.time()
        with self.room_state_lock:
            self.outgoing_attribution[(account_id, chat_mid)] = (now, by)
            if len(self.outgoing_attribution) > 5000:
                self.outgoing_attribution = {
                    key: value
                    for key, value in self.outgoing_attribution.items()
                    if now - value[0] <= OUTGOING_ATTRIBUTION_TTL_SECONDS
                }
            if by in NON_REPLY_SENDERS or not _room_tracked(chat_mid):
                return
            try:
                rooms = self._room_states(account_id)
                room = rooms.get(chat_mid)
                if not isinstance(room, dict) or room.get("status") != "waiting":
                    return
                self._answer_room(account_id, chat_mid, room, int(now * 1000), by)
                self._save_room_states(account_id, rooms)
            except Exception:
                traceback.print_exc()

    def update_room_state(
        self, account_id: str, own_mid: str, boxes: list[dict[str, Any]]
    ) -> None:
        now_ms = int(time.time() * 1000)
        newly_waiting: list[str] = []
        with self.room_state_lock:
            rooms = self._room_states(account_id)
            changed = False
            for box in boxes:
                chat_mid = _message_box_id(box)
                if not _room_tracked(chat_mid):
                    continue
                messages = sorted(_message_box_messages(box), key=_message_time)
                if not messages:
                    continue
                room = rooms.get(chat_mid)
                is_new = not isinstance(room, dict)
                if is_new:
                    room = {
                        "status": "closed",
                        "cursorAt": 0,
                        "lastIncomingAt": 0,
                        "lastOutgoingAt": 0,
                        "firstUnansweredAt": None,
                        "answeredBy": None,
                        "answeredAt": None,
                    }
                assert room is not None
                was_waiting = room.get("status") == "waiting"
                cursor = _coerce_int(room.get("cursorAt"))
                start_cursor = cursor
                for message in messages:
                    sent_ms = _message_time(message)
                    if sent_ms <= cursor:
                        continue
                    cursor = sent_ms
                    if str(message.get("from") or "") not in {"", own_mid}:
                        room["lastIncomingAt"] = max(
                            _coerce_int(room.get("lastIncomingAt")), sent_ms
                        )
                        if room.get("status") != "waiting":
                            room["status"] = "waiting"
                            room["firstUnansweredAt"] = sent_ms
                            room["answeredBy"] = None
                            room["answeredAt"] = None
                        continue
                    room["lastOutgoingAt"] = max(
                        _coerce_int(room.get("lastOutgoingAt")), sent_ms
                    )
                    if room.get("status") != "waiting" or sent_ms < _coerce_int(
                        room.get("firstUnansweredAt")
                    ):
                        continue
                    by = self._outgoing_attribution_for(account_id, chat_mid)
                    if by in NON_REPLY_SENDERS:
                        continue
                    # History seen on first contact is context, not a KPI event.
                    self._answer_room(
                        account_id,
                        chat_mid,
                        room,
                        sent_ms,
                        by or "line_app",
                        record=not is_new,
                    )
                if is_new or cursor != start_cursor:
                    room["cursorAt"] = cursor
                    rooms[chat_mid] = room
                    changed = True
                if not is_new and not was_waiting and room.get("status") == "waiting":
                    room["pushEscalated"] = False
                    newly_waiting.append(chat_mid)
            if self._close_stale_rooms(account_id, rooms, now_ms):
                changed = True
            if changed:
                self._save_room_states(account_id, rooms)
        if newly_waiting:
            self.queue_push_for_rooms(account_id, newly_waiting)

    def _close_stale_rooms(
        self, account_id: str, rooms: dict[str, dict[str, Any]], now_ms: int
    ) -> bool:
        """Close rooms quiet for a day; a still-waiting one counts as missed."""
        changed = False
        for chat_mid, room in rooms.items():
            last = max(
                _coerce_int(room.get("lastIncomingAt")),
                _coerce_int(room.get("lastOutgoingAt")),
            )
            if (
                room.get("status") != "closed"
                and last
                and now_ms - last > ROOM_CLOSE_AFTER_SECONDS * 1000
            ):
                if room.get("status") == "waiting":
                    asked_ms = _coerce_int(room.get("firstUnansweredAt"))
                    self._record_kpi_response(
                        account_id,
                        {
                            "chatMid": chat_mid,
                            "askedAt": asked_ms,
                            "answeredAt": None,
                            "answeredBy": None,
                            "missed": True,
                        },
                    )
                room["status"] = "closed"
                room["firstUnansweredAt"] = None
                changed = True
        return changed

    def note_incoming(self, account_id: str, chat_mid: str, at_ms: int) -> None:
        """A customer message seen outside a LINE inbox fetch (Telegram)."""
        if not _room_tracked(chat_mid):
            return
        newly_waiting = False
        with self.room_state_lock:
            rooms = self._room_states(account_id)
            room = rooms.get(chat_mid)
            if not isinstance(room, dict):
                room = {
                    "status": "closed",
                    "cursorAt": 0,
                    "lastIncomingAt": 0,
                    "lastOutgoingAt": 0,
                    "firstUnansweredAt": None,
                    "answeredBy": None,
                    "answeredAt": None,
                }
            room["lastIncomingAt"] = max(_coerce_int(room.get("lastIncomingAt")), at_ms)
            room["cursorAt"] = max(_coerce_int(room.get("cursorAt")), at_ms)
            if room.get("status") != "waiting":
                # Unlike the LINE inbox, a first message here is a real new chat.
                room.update(
                    status="waiting",
                    firstUnansweredAt=at_ms,
                    answeredBy=None,
                    answeredAt=None,
                    pushEscalated=False,
                )
                newly_waiting = True
            rooms[chat_mid] = room
            self._save_room_states(account_id, rooms)
        if newly_waiting:
            self.queue_push_for_rooms(account_id, [chat_mid])

    def sweep_rooms(self, account_id: str) -> None:
        with self.room_state_lock:
            rooms = self._room_states(account_id)
            if self._close_stale_rooms(account_id, rooms, int(time.time() * 1000)):
                self._save_room_states(account_id, rooms)

    def room_states(self, account_id: str) -> dict[str, dict[str, Any]]:
        with self.room_state_lock:
            return copy.deepcopy(self._room_states(account_id))

    # -- staff presence (KPI screen time) -------------------------------------
    def _presence_segments(self) -> list[dict[str, Any]]:
        if self.presence_cache is None:
            raw = self.store.get("presence", {})
            items = raw.get("segments") if isinstance(raw, dict) else None
            self.presence_cache = (
                [item for item in items if isinstance(item, dict)]
                if isinstance(items, list)
                else []
            )
        return self.presence_cache

    def _save_presence(self, now: float) -> None:
        segments = self._presence_segments()
        cutoff = int(now * 1000) - KPI_RETENTION_DAYS * 86_400_000
        kept = [item for item in segments if _coerce_int(item.get("to")) >= cutoff]
        self.presence_cache = kept[-MAX_PRESENCE_SEGMENTS:]
        self.store.set("presence", {"segments": self.presence_cache})
        self.presence_saved_at["*"] = now

    def record_presence(
        self, user: dict[str, Any] | None, body: dict[str, Any]
    ) -> dict[str, Any]:
        user_id = str((user or {}).get("id") or "")
        if not user_id:
            raise WebError(HTTPStatus.UNAUTHORIZED, "User authentication required.")
        state = str(body.get("state") or "").strip().lower()
        if state not in PRESENCE_STATES:
            raise WebError(HTTPStatus.BAD_REQUEST, "Unknown presence state.", "invalid_presence")
        notification = str(body.get("notification") or "").strip().lower()
        if notification not in {"granted", "denied", "default", "unsupported"}:
            notification = ""
        now = time.time()
        now_ms = int(now * 1000)
        with self.presence_lock:
            segments = self._presence_segments()
            current = next(
                (item for item in reversed(segments) if item.get("userId") == user_id), None
            )
            contiguous = bool(
                current and now_ms - _coerce_int(current.get("to")) <= PRESENCE_OFFLINE_SECONDS * 1000
            )
            if current and contiguous and current.get("state") == state:
                current["to"] = now_ms
                if notification:
                    current["notification"] = notification
                segment = current
                persist = now - self.presence_saved_at.get("*", 0) >= PRESENCE_SAVE_SECONDS
            else:
                if current and contiguous:
                    current["to"] = now_ms
                segment = {
                    "userId": user_id,
                    "state": state,
                    "from": now_ms,
                    "to": now_ms,
                }
                if notification:
                    segment["notification"] = notification
                segments.append(segment)
                persist = True
            self.presence_current[user_id] = {
                "state": state,
                "notification": notification,
                "at": now_ms,
            }
            if persist:
                self._save_presence(now)
            return {"ok": True, "state": state, "since": segment["from"]}

    def flush_presence(self) -> None:
        with self.presence_lock:
            if self.presence_cache is not None:
                self._save_presence(time.time())

    # -- KPI settings and aggregation ---------------------------------------
    def _account_owner_id(self, account_id: str) -> str:
        account = self.account_store.get(account_id) or {}
        owner = self.web_auth.user_for_account(account_id)
        return str(account.get("ownerId") or (owner or {}).get("id") or "")

    def _kpi_settings_for_owner(self, owner_id: str) -> dict[str, Any]:
        raw = self.store.get("kpi_settings", {"tenants": {}})
        tenants = raw.get("tenants") if isinstance(raw, dict) else None
        stored = tenants.get(owner_id) if isinstance(tenants, dict) else None
        settings = _default_kpi_settings()
        if isinstance(stored, dict):
            settings.update(
                {key: stored[key] for key in settings if key in stored}
            )
        return settings

    def kpi_settings(self, account_id: str, user: dict[str, Any] | None) -> dict[str, Any]:
        account_id = _required_account_id(account_id)
        if not self.web_auth.can_access_account(user, account_id):
            raise WebError(HTTPStatus.FORBIDDEN, "Permission denied for this LINE account.")
        settings = self._kpi_settings_for_owner(self._account_owner_id(account_id))
        user_id = str((user or {}).get("id") or "")
        return {
            "ok": True,
            "accountId": account_id,
            "settings": settings,
            "myShifts": list((settings.get("shifts") or {}).get(user_id) or []),
            "members": self._kpi_members(account_id),
            "canEdit": self.web_auth.owns_account(user, account_id)
            and self.web_auth.has_permission(user, "manage_accounts"),
        }

    def save_kpi_settings(
        self, body: dict[str, Any], user: dict[str, Any] | None
    ) -> dict[str, Any]:
        account_id = _required_account_id(str(body.get("accountId") or ""))
        if not self.web_auth.owns_account(user, account_id) or not self.web_auth.has_permission(
            user, "manage_accounts"
        ):
            raise WebError(HTTPStatus.FORBIDDEN, "Only the account owner can change KPI settings.")
        owner_id = self._account_owner_id(account_id)
        member_ids = {member["id"] for member in self._kpi_members(account_id)}
        settings = _validate_kpi_settings(body.get("settings"), member_ids)
        with self.lock:
            raw = self.store.get("kpi_settings", {"tenants": {}})
            root = raw if isinstance(raw, dict) else {"tenants": {}}
            if not isinstance(root.get("tenants"), dict):
                root["tenants"] = {}
            root["tenants"][owner_id] = {**settings, "updatedAt": _now_iso()}
            self.store.set("kpi_settings", root)
        return self.kpi_settings(account_id, user)

    def _kpi_members(self, account_id: str) -> list[dict[str, Any]]:
        members = []
        for item in self.web_auth.data.get("users", []):
            if not isinstance(item, dict) or item.get("role") == "god":
                continue
            if account_id in set(item.get("accountIds") or []) or account_id in set(
                item.get("staffAccountIds") or []
            ):
                members.append(
                    {
                        "id": str(item.get("id") or ""),
                        "name": str(item.get("displayName") or item.get("username") or ""),
                        "role": "owner" if account_id in set(item.get("accountIds") or []) else "staff",
                        "active": bool(item.get("active", True)),
                    }
                )
        return members

    def kpi_report(
        self,
        account_id: str,
        user: dict[str, Any] | None,
        *,
        from_ms: int,
        to_ms: int,
    ) -> dict[str, Any]:
        account_id = _required_account_id(account_id)
        if not self.web_auth.owns_account(user, account_id) or not self.web_auth.has_permission(
            user, "manage_accounts"
        ):
            raise WebError(HTTPStatus.FORBIDDEN, "Only the account owner can view KPI.")
        now_ms = int(time.time() * 1000)
        to_ms = min(to_ms, now_ms)
        if from_ms >= to_ms:
            raise WebError(HTTPStatus.BAD_REQUEST, "The KPI range is empty.", "invalid_range")
        settings = self._kpi_settings_for_owner(self._account_owner_id(account_id))
        members = self._kpi_members(account_id)
        responses = [
            item
            for item in self._kpi_responses(account_id)
            if from_ms <= _coerce_int(item.get("askedAt")) < to_ms
        ]
        with self.presence_lock:
            segments = [dict(item) for item in self._presence_segments()]
        rooms = self.room_states(account_id)
        return _build_kpi_report(
            responses=responses,
            segments=segments,
            rooms=rooms,
            members=members,
            settings=settings,
            from_ms=from_ms,
            to_ms=to_ms,
            now_ms=now_ms,
        )

    def record_operator_send(
        self, account_id: str, user: dict[str, Any] | None, to: str, kind: str
    ) -> None:
        user_id = str((user or {}).get("id") or "")
        self.append_bot_log(
            "operator_send",
            account_id=account_id,
            data={
                "webUserId": user_id,
                "webUserName": str(
                    (user or {}).get("displayName") or (user or {}).get("username") or ""
                ),
                "to": to,
                "kind": kind,
            },
        )
        if user_id:
            self.note_outgoing(account_id, to, user_id)

    def create_user(
        self, body: dict[str, Any], actor: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        user = self.web_auth.create_user(
            str(body.get("email") or body.get("username") or ""),
            str(body.get("password") or ""),
            str(body.get("role") or "viewer"),
            _string_list(body.get("accountIds")),
            str(body.get("displayName") or ""),
            actor=actor,
        )
        return {"ok": True, "user": user, **self.users_payload()}

    def update_user(
        self, body: dict[str, Any], actor: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        user_id = str(body.get("id") or "")
        user = self.web_auth.update_user(
            user_id,
            username=str(body["username"]) if "username" in body else None,
            email=str(body["email"]) if "email" in body else None,
            display_name=str(body["displayName"]) if "displayName" in body else None,
            role=str(body["role"]) if "role" in body else None,
            account_ids=_string_list(body.get("accountIds")) if "accountIds" in body else None,
            active=bool(body.get("active")) if "active" in body else None,
            password=str(body.get("password") or "") or None,
            actor=actor,
        )
        return {"ok": True, "user": user, **self.users_payload()}

    def delete_user(
        self, body: dict[str, Any], current_user: dict[str, Any]
    ) -> dict[str, Any]:
        user_id = str(body.get("id") or "")
        current_user_id = str(current_user.get("id") or "")
        target = self.web_auth._find_user(user_id)
        if target is None:
            raise WebError(HTTPStatus.NOT_FOUND, "User not found.")
        account_ids = set(target.get("accountIds") or [])
        account_ids.update(
            str(account.get("id") or "")
            for account in self.account_store.data.get("accounts", [])
            if isinstance(account, dict) and str(account.get("ownerId") or "") == user_id
        )
        account_ids.discard("")
        api_locks = [self.api_lock_for(account_id) for account_id in sorted(account_ids)]
        for api_lock in api_locks:
            api_lock.acquire()
        token_files: list[str] = []
        try:
            with (
                self.lock,
                self.web_auth.lock,
                self.account_store.lock,
                self.schedule_lock,
                self.incoming_api_lock,
            ):
                auth_data = self.web_auth.data_after_user_delete(
                    user_id,
                    current_user_id=current_user_id,
                    actor=current_user,
                )
                # Staff the deleted owner created lose their only reason to exist.
                auth_data["users"] = [
                    auth_user
                    for auth_user in auth_data.get("users", [])
                    if str(auth_user.get("teamOwnerId") or "") != user_id
                ]
                for auth_user in auth_data.get("users", []):
                    _strip_account_from_user(auth_user, account_ids)
                account_data = copy.deepcopy(self.account_store.data)
                kept_accounts = []
                for account in account_data.get("accounts", []):
                    if isinstance(account, dict) and account.get("id") in account_ids:
                        token_file = str(account.get("tokenFile") or "")
                        if token_file:
                            token_files.append(token_file)
                    else:
                        kept_accounts.append(account)
                account_data["accounts"] = kept_accounts
                if account_data.get("activeAccountId") in account_ids:
                    account_data["activeAccountId"] = (
                        kept_accounts[0].get("id") if kept_accounts else None
                    )
                schedules = [
                    copy.deepcopy(schedule)
                    for schedule in self.schedules
                    if schedule.get("accountId") not in account_ids
                    and str(schedule.get("ownerId") or "") != user_id
                ]

                raw_patterns = self.store.get("patterns", {"patterns": [], "categories": []})
                pattern_data = (
                    copy.deepcopy(raw_patterns) if isinstance(raw_patterns, dict) else {}
                )
                pattern_data["patterns"] = [
                    pattern
                    for pattern in pattern_data.get("patterns", [])
                    if not isinstance(pattern, dict)
                    or str(pattern.get("ownerId") or "") != user_id
                ]
                pattern_data["categories"] = [
                    category
                    for category in pattern_data.get("categories", [])
                    if not isinstance(category, dict)
                    or str(category.get("ownerId") or "") != user_id
                ]

                raw_ai = self.store.get("ai_settings", {"tenants": {}})
                ai_root = (
                    copy.deepcopy(raw_ai) if isinstance(raw_ai, dict) else {"tenants": {}}
                )
                tenants = ai_root.get("tenants")
                if isinstance(tenants, dict):
                    tenants.pop(user_id, None)

                raw_global_ai = self.store.get("global_ai", {})
                global_ai = (
                    copy.deepcopy(raw_global_ai) if isinstance(raw_global_ai, dict) else {}
                )
                knowledge_tenants = global_ai.get("tenants")
                if isinstance(knowledge_tenants, dict):
                    knowledge_tenants.pop(user_id, None)
                global_ai["questions"] = [
                    question
                    for question in global_ai.get("questions", [])
                    if not isinstance(question, dict)
                    or str(question.get("userId") or "") != user_id
                ]

                raw_logs = self.store.get("bot_logs", {"logs": []})
                log_data = copy.deepcopy(raw_logs) if isinstance(raw_logs, dict) else {}
                log_data["logs"] = [
                    log
                    for log in log_data.get("logs", [])
                    if not isinstance(log, dict) or log.get("accountId") not in account_ids
                ]

                raw_incoming = self.store.get("incoming_api", {"links": []})
                incoming_data = (
                    copy.deepcopy(raw_incoming)
                    if isinstance(raw_incoming, dict)
                    else {"links": []}
                )
                incoming_data["links"] = [
                    link
                    for link in incoming_data.get("links", [])
                    if not isinstance(link, dict)
                    or (
                        str(link.get("ownerId") or "") != user_id
                        and link.get("accountId") not in account_ids
                    )
                ]

                self.store.set_many(
                    {
                        "auth": auth_data,
                        "accounts": account_data,
                        "schedules": {"schedules": schedules},
                        "patterns": pattern_data,
                        "ai_settings": ai_root,
                        "global_ai": global_ai,
                        "bot_logs": log_data,
                        "incoming_api": incoming_data,
                    }
                )
                self.web_auth.data = auth_data
                self.account_store.data = account_data
                self.schedules = schedules
                for account_id in account_ids:
                    self.close_api(account_id)
        finally:
            for api_lock in reversed(api_locks):
                api_lock.release()
        for token_file in token_files:
            try:
                if os.path.exists(token_file):
                    os.remove(token_file)
            except OSError:
                traceback.print_exc()
        return {"ok": True, **self.users_payload()}

    # -- incoming API links ----------------------------------------------
    def _incoming_api_root(self) -> dict[str, Any]:
        raw = self.store.get("incoming_api", {"links": []})
        if not isinstance(raw, dict):
            return {"links": []}
        links = raw.get("links")
        return {"links": links if isinstance(links, list) else []}

    def _incoming_api_public_link(self, link: dict[str, Any]) -> dict[str, Any]:
        token = self._decrypt_secret(str(link.get("tokenSecret") or ""))
        endpoint_path = f"/api/incoming/{link.get('id')}/{token}" if token else ""
        return {
            "id": link.get("id"),
            "name": link.get("name"),
            "accountId": link.get("accountId"),
            "targets": [
                {
                    "mid": target.get("mid"),
                    "name": target.get("name"),
                    "type": target.get("type"),
                }
                for target in link.get("targets", [])
                if isinstance(target, dict)
            ],
            "encrypt": bool(link.get("encrypt")),
            "active": bool(link.get("active", True)),
            "endpointPath": endpoint_path,
            "requestCount": max(0, int(link.get("requestCount") or 0)),
            "successCount": max(0, int(link.get("successCount") or 0)),
            "failureCount": max(0, int(link.get("failureCount") or 0)),
            "lastUsedAt": link.get("lastUsedAt"),
            "lastStatus": link.get("lastStatus"),
            "lastError": link.get("lastError"),
            "createdAt": link.get("createdAt"),
            "updatedAt": link.get("updatedAt"),
        }

    def _find_owned_incoming_api_link(
        self,
        links: list[Any],
        link_id: str,
        user: dict[str, Any] | None,
    ) -> dict[str, Any]:
        owner_id = str((user or {}).get("id") or "")
        for link in links:
            if (
                isinstance(link, dict)
                and str(link.get("id") or "") == link_id
                and str(link.get("ownerId") or "") == owner_id
            ):
                account_id = str(link.get("accountId") or "")
                if not self.web_auth.can_access_account(user, account_id):
                    break
                return link
        raise WebError(HTTPStatus.NOT_FOUND, "API link not found.", "api_link_not_found")

    @staticmethod
    def _validated_incoming_api_name(value: Any) -> str:
        name = str(value or "").strip()
        if not name:
            raise WebError(HTTPStatus.BAD_REQUEST, "API link name is required.")
        if len(name) > MAX_INCOMING_API_NAME_LENGTH:
            raise WebError(HTTPStatus.BAD_REQUEST, "API link name is too long.")
        return name

    @staticmethod
    def _incoming_api_target_catalog(api: OkLine) -> dict[tuple[str, str], str]:
        catalog: dict[tuple[str, str], str] = {
            ("contact", mid): str(data.get("name") or mid) for mid, data in _contact_rows(api)
        }
        raw_mids = api.get_all_chat_mids() or {}
        group_mids = list(raw_mids.get("memberChatMids", []) or [])
        invited = list(raw_mids.get("invitedChatMids", []) or [])
        group_mids.extend(mid for mid in invited if mid not in group_mids)
        if group_mids:
            result = api.get_chats(group_mids) or {}
            for raw in result.get("chats", []) if isinstance(result, dict) else []:
                group = Group.from_dict(raw)
                if group.chat_mid:
                    catalog[("group", group.chat_mid)] = group.name or group.chat_mid
        return catalog

    def _validated_incoming_api_targets(
        self, api: OkLine, raw_targets: Any
    ) -> list[dict[str, str]]:
        if not isinstance(raw_targets, list) or not raw_targets:
            raise WebError(HTTPStatus.BAD_REQUEST, "Select at least one API target.")
        if len(raw_targets) > MAX_INCOMING_API_TARGETS:
            raise WebError(
                HTTPStatus.BAD_REQUEST,
                f"Select no more than {MAX_INCOMING_API_TARGETS} API targets.",
            )
        catalog = self._incoming_api_target_catalog(api)
        targets: list[dict[str, str]] = []
        seen: set[tuple[str, str]] = set()
        for raw in raw_targets:
            if not isinstance(raw, dict):
                raise WebError(HTTPStatus.BAD_REQUEST, "API target is invalid.")
            kind = str(raw.get("type") or "contact").strip().lower()
            mid = str(raw.get("mid") or "").strip()
            key = (kind, mid)
            if kind not in {"contact", "group"} or not mid or key not in catalog:
                raise WebError(
                    HTTPStatus.BAD_REQUEST,
                    "One or more API targets are unavailable for this LINE account.",
                    "invalid_api_target",
                )
            if key in seen:
                continue
            seen.add(key)
            targets.append({"type": kind, "mid": mid, "name": catalog[key]})
        if not targets:
            raise WebError(HTTPStatus.BAD_REQUEST, "Select at least one API target.")
        return targets

    def list_incoming_api_links(
        self, account_id: str, user: dict[str, Any] | None
    ) -> dict[str, Any]:
        account_id = _required_account_id(account_id)
        if not self.web_auth.can_access_account(user, account_id):
            raise WebError(HTTPStatus.FORBIDDEN, "Permission denied for this LINE account.")
        owner_id = str((user or {}).get("id") or "")
        with self.incoming_api_lock:
            links = [
                self._incoming_api_public_link(link)
                for link in self._incoming_api_root()["links"]
                if isinstance(link, dict)
                and str(link.get("ownerId") or "") == owner_id
                and str(link.get("accountId") or "") == account_id
            ]
        links.sort(key=lambda item: str(item.get("createdAt") or ""), reverse=True)
        return {"links": links, "count": len(links)}

    def create_incoming_api_link(
        self,
        body: dict[str, Any],
        user: dict[str, Any] | None,
        api: OkLine,
    ) -> dict[str, Any]:
        account_id = _required_account_id(str(body.get("accountId") or ""))
        if not self.web_auth.can_access_account(user, account_id):
            raise WebError(HTTPStatus.FORBIDDEN, "Permission denied for this LINE account.")
        owner_id = str((user or {}).get("id") or "")
        name = self._validated_incoming_api_name(body.get("name"))
        targets = self._validated_incoming_api_targets(api, body.get("targets"))
        token = secrets.token_urlsafe(32)
        now = _now_iso()
        with self.incoming_api_lock:
            root = self._incoming_api_root()
            owner_links = [
                link
                for link in root["links"]
                if isinstance(link, dict) and str(link.get("ownerId") or "") == owner_id
            ]
            if len(owner_links) >= MAX_INCOMING_API_LINKS_PER_USER:
                raise WebError(
                    HTTPStatus.CONFLICT,
                    "Incoming API link limit reached.",
                    "api_link_limit",
                )
            link = {
                "id": uuid.uuid4().hex,
                "ownerId": owner_id,
                "accountId": account_id,
                "name": name,
                "targets": targets,
                "encrypt": bool(body.get("encrypt")),
                "active": bool(body.get("active", True)),
                "tokenHash": hashlib.sha256(token.encode("utf-8")).hexdigest(),
                "tokenSecret": self._encrypt_secret(token),
                "requestCount": 0,
                "successCount": 0,
                "failureCount": 0,
                "createdAt": now,
                "updatedAt": now,
            }
            root["links"].append(link)
            self.store.set("incoming_api", root)
        self.append_bot_log(
            "incoming_api.create",
            account_id=account_id,
            detail=name,
            data={"linkId": link["id"], "targets": len(targets)},
        )
        return {"ok": True, "link": self._incoming_api_public_link(link)}

    def update_incoming_api_link(
        self, body: dict[str, Any], user: dict[str, Any] | None
    ) -> dict[str, Any]:
        link_id = str(body.get("id") or "").strip()
        with self.incoming_api_lock:
            root = self._incoming_api_root()
            link = self._find_owned_incoming_api_link(root["links"], link_id, user)
            if "name" in body:
                link["name"] = self._validated_incoming_api_name(body.get("name"))
            if "active" in body:
                link["active"] = bool(body.get("active"))
            link["updatedAt"] = _now_iso()
            self.store.set("incoming_api", root)
            public = self._incoming_api_public_link(link)
        self.append_bot_log(
            "incoming_api.update",
            account_id=str(link.get("accountId") or ""),
            detail=str(link.get("name") or ""),
            data={"linkId": link_id, "active": bool(link.get("active"))},
        )
        return {"ok": True, "link": public}

    def rotate_incoming_api_link(
        self, link_id: str, user: dict[str, Any] | None
    ) -> dict[str, Any]:
        token = secrets.token_urlsafe(32)
        with self.incoming_api_lock:
            root = self._incoming_api_root()
            link = self._find_owned_incoming_api_link(root["links"], link_id, user)
            link["tokenHash"] = hashlib.sha256(token.encode("utf-8")).hexdigest()
            link["tokenSecret"] = self._encrypt_secret(token)
            link["updatedAt"] = _now_iso()
            self.store.set("incoming_api", root)
            public = self._incoming_api_public_link(link)
        self.append_bot_log(
            "incoming_api.rotate",
            account_id=str(link.get("accountId") or ""),
            detail=str(link.get("name") or ""),
            data={"linkId": link_id},
        )
        return {"ok": True, "link": public}

    def delete_incoming_api_link(
        self, link_id: str, user: dict[str, Any] | None
    ) -> dict[str, Any]:
        with self.incoming_api_lock:
            root = self._incoming_api_root()
            link = self._find_owned_incoming_api_link(root["links"], link_id, user)
            root["links"] = [item for item in root["links"] if item is not link]
            self.store.set("incoming_api", root)
            self.incoming_api_rate.pop(link_id, None)
        self.append_bot_log(
            "incoming_api.delete",
            account_id=str(link.get("accountId") or ""),
            detail=str(link.get("name") or ""),
            data={"linkId": link_id},
        )
        return {"ok": True, "id": link_id}

    def execute_incoming_api(
        self,
        link_id: str,
        token: str,
        body: dict[str, Any],
        *,
        method: str = "POST",
    ) -> dict[str, Any]:
        request_method = str(method or "POST").strip().upper()
        if request_method not in {"GET", "POST"}:
            raise WebError(HTTPStatus.METHOD_NOT_ALLOWED, "Use GET or POST.")
        supplied_hash = hashlib.sha256(token.encode("utf-8")).hexdigest()
        now_epoch = time.time()
        with self.incoming_api_lock:
            root = self._incoming_api_root()
            stored = next(
                (
                    item
                    for item in root["links"]
                    if isinstance(item, dict) and str(item.get("id") or "") == link_id
                ),
                None,
            )
            if stored is None or not hmac.compare_digest(
                str(stored.get("tokenHash") or ""), supplied_hash
            ):
                raise WebError(
                    HTTPStatus.NOT_FOUND, "Incoming API link not found.", "api_link_not_found"
                )
            if not bool(stored.get("active", True)):
                raise WebError(
                    HTTPStatus.NOT_FOUND, "Incoming API link not found.", "api_link_not_found"
                )
            cutoff = now_epoch - 60.0
            recent = [
                stamp for stamp in self.incoming_api_rate.get(link_id, []) if stamp > cutoff
            ]
            if len(recent) >= MAX_INCOMING_API_REQUESTS_PER_MINUTE:
                retry_after = max(1, math.ceil(recent[0] + 60.0 - now_epoch))
                raise WebError(
                    HTTPStatus.TOO_MANY_REQUESTS,
                    "Incoming API rate limit exceeded.",
                    "api_rate_limited",
                    headers=[("Retry-After", str(retry_after))],
                )
            recent.append(now_epoch)
            self.incoming_api_rate[link_id] = recent
            link = copy.deepcopy(stored)

        owner = self.web_auth._find_user(str(link.get("ownerId") or ""))
        account_id = str(link.get("accountId") or "")
        if (
            owner is None
            or not self.web_auth._is_active_user(owner)
            or not self.web_auth.has_permission(owner, "send")
            or not self.web_auth.can_access_account(owner, account_id)
            or not self.account_store.get(account_id)
        ):
            raise WebError(
                HTTPStatus.NOT_FOUND, "Incoming API link not found.", "api_link_not_found"
            )
        targets = [item for item in link.get("targets", []) if isinstance(item, dict)]
        if not targets:
            raise WebError(HTTPStatus.CONFLICT, "Incoming API link has no targets.")

        text, image = _incoming_api_payload(body, allow_image=request_method == "POST")
        content_kinds = [
            kind
            for kind, present in (("text", bool(text)), ("image", image is not None))
            if present
        ]
        request_detail = (
            _short_text(text, 120) if text else str((image or {}).get("name") or "image")
        )

        self.append_bot_log(
            "incoming_api.request",
            account_id=account_id,
            detail=request_detail,
            data={
                "linkId": link_id,
                "method": request_method,
                "targets": len(targets),
                "contents": content_kinds,
            },
        )
        results: list[dict[str, Any]] = []
        with self.api_lock_for(account_id):
            api = self.get_api(account_id)
            for target in targets:
                mid = str(target.get("mid") or "")
                name = str(target.get("name") or mid)
                kind = str(target.get("type") or "contact")
                try:
                    message_ids: list[Any] = []
                    self.note_outgoing(account_id, mid, "api")
                    if text:
                        result = (
                            api.send_encrypted_text(mid, text)
                            if bool(link.get("encrypt"))
                            else api.send_text(mid, text)
                        )
                        message_ids.append(
                            result.get("id") if isinstance(result, dict) else result
                        )
                    if image is not None:
                        result = api.send_image(mid, image["data"], name=image["name"])
                        message_ids.append(
                            result.get("id") if isinstance(result, dict) else result
                        )
                    results.append(
                        {
                            "ok": True,
                            "name": name,
                            "type": kind,
                            "messageId": message_ids[-1] if message_ids else None,
                            "messageIds": message_ids,
                            "contents": content_kinds,
                        }
                    )
                    self.append_bot_log(
                        "incoming_api.send.success",
                        account_id=account_id,
                        detail=name,
                        data={
                            "linkId": link_id,
                            "target": mid,
                            "type": kind,
                            "contents": content_kinds,
                        },
                    )
                except Exception as exc:
                    error = _safe_log_detail(exc, 500)
                    results.append({"ok": False, "name": name, "type": kind, "error": error})
                    self.append_bot_log(
                        "incoming_api.send.error",
                        account_id=account_id,
                        ok=False,
                        detail=error,
                        data={"linkId": link_id, "target": mid, "type": kind},
                    )

        success_count = sum(1 for item in results if item.get("ok"))
        failure_count = len(results) - success_count
        with self.incoming_api_lock:
            latest_root = self._incoming_api_root()
            latest = next(
                (
                    item
                    for item in latest_root["links"]
                    if isinstance(item, dict) and str(item.get("id") or "") == link_id
                ),
                None,
            )
            if latest is not None:
                latest["requestCount"] = int(latest.get("requestCount") or 0) + 1
                latest["successCount"] = int(latest.get("successCount") or 0) + success_count
                latest["failureCount"] = int(latest.get("failureCount") or 0) + failure_count
                latest["lastUsedAt"] = _now_iso()
                latest["lastStatus"] = (
                    "success" if not failure_count else "partial" if success_count else "error"
                )
                if failure_count:
                    latest["lastError"] = str(
                        next(item.get("error") for item in results if not item.get("ok"))
                    )
                else:
                    latest.pop("lastError", None)
                self.store.set("incoming_api", latest_root)
        return {
            "ok": failure_count == 0,
            "linkId": link_id,
            "method": request_method,
            "contents": content_kinds,
            "sent": success_count,
            "failed": failure_count,
            "results": results,
        }

    # -- schedules ---------------------------------------------------------
    def _load_schedules(self) -> list[dict[str, Any]]:
        data = self.store.get("schedules", {"schedules": []})
        schedules = data.get("schedules", []) if isinstance(data, dict) else []
        if not isinstance(schedules, list):
            return []
        items = [s for s in schedules if isinstance(s, dict)]
        recovered = False
        for job in items:
            if job.get("running"):
                job["running"] = False
                job["status"] = "error"
                job["lastError"] = "Recovered after the previous process stopped unexpectedly."
                job.pop("runningSince", None)
                job.pop("runToken", None)
                recovered = True
        if recovered:
            self.store.set("schedules", {"schedules": items})
        return items

    def save_schedules(self) -> None:
        with self.schedule_lock:
            self.store.set("schedules", {"schedules": self.schedules})

    def list_schedules(
        self, account_id: str | None = None, user: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        account_id = (account_id or "").strip()
        allowed_ids = self.web_auth.allowed_account_ids(user)
        with self.schedule_lock:
            schedules = [dict(job) for job in self.schedules]
            if account_id:
                if not self.web_auth.can_access_account(user, account_id):
                    raise WebError(
                        HTTPStatus.FORBIDDEN, "Permission denied for this LINE account."
                    )
                schedules = [job for job in schedules if job.get("accountId") == account_id]
            elif allowed_ids is not None:
                schedules = [job for job in schedules if job.get("accountId") in allowed_ids]
            return {
                "schedules": schedules,
                "accounts": self.account_store.list_accounts(allowed_ids),
            }

    def create_schedule(self, body: dict[str, Any]) -> dict[str, Any]:
        account_id = _required_account_id(str(body.get("accountId") or ""))
        if not self.account_store.get(account_id):
            raise WebError(HTTPStatus.BAD_REQUEST, "A valid account is required.")
        if _account_channel(self.account_store.get(account_id)) != "line":
            raise _line_only()
        job = _schedule_from_body(body, account_id=account_id)
        with self.schedule_lock:
            count = sum(1 for item in self.schedules if item.get("accountId") == account_id)
            if count >= MAX_SCHEDULES_PER_ACCOUNT:
                raise WebError(
                    HTTPStatus.CONFLICT,
                    f"Each LINE account can have at most {MAX_SCHEDULES_PER_ACCOUNT} schedules.",
                    "schedule_quota",
                )
            _ensure_schedule_image_quota(self.schedules, job)
            self.schedules.append(job)
            self.save_schedules()
            self.append_bot_log(
                "schedule.create",
                account_id=account_id,
                schedule=job,
                detail=f"{job.get('contentSource')} -> {job.get('to')}",
            )
        return {"ok": True, "schedule": job}

    def update_schedule(self, schedule_id: str, body: dict[str, Any]) -> dict[str, Any]:
        with self.schedule_lock:
            job = self._find_schedule(schedule_id)
            account_id = _required_account_id(str(body.get("accountId") or ""))
            _ensure_schedule_account(job, account_id)
            if not self.account_store.get(account_id):
                raise WebError(HTTPStatus.BAD_REQUEST, "A valid account is required.")
            if _account_channel(self.account_store.get(account_id)) != "line":
                raise _line_only()
            updated = _schedule_from_body(body, account_id=account_id, existing=job)
            _ensure_schedule_image_quota(self.schedules, updated, replacing_id=schedule_id)
            job.clear()
            job.update(updated)
            self.save_schedules()
            self.append_bot_log(
                "schedule.update",
                account_id=account_id,
                schedule=job,
                detail=f"{job.get('contentSource')} -> {job.get('to')}",
            )
            return {"ok": True, "schedule": dict(job)}

    def toggle_schedule(
        self, schedule_id: str, enabled: bool, account_id: str | None = None
    ) -> dict[str, Any]:
        with self.schedule_lock:
            job = self._find_schedule(schedule_id)
            _ensure_schedule_account(job, account_id)
            job["enabled"] = bool(enabled)
            job["status"] = "waiting" if enabled else "paused"
            if enabled:
                job["nextRunAt"] = _compute_next_epoch(job)
            self.save_schedules()
            self.append_bot_log(
                "schedule.resume" if enabled else "schedule.pause",
                account_id=str(job.get("accountId") or ""),
                schedule=job,
            )
            return {"ok": True, "schedule": dict(job)}

    def delete_schedule(
        self, schedule_id: str, account_id: str | None = None
    ) -> dict[str, Any]:
        with self.schedule_lock:
            job = self._find_schedule(schedule_id)
            _ensure_schedule_account(job, account_id)
            snapshot = dict(job)
            before = len(self.schedules)
            self.schedules = [job for job in self.schedules if job.get("id") != schedule_id]
            if len(self.schedules) == before:
                raise WebError(HTTPStatus.NOT_FOUND, "Schedule not found.")
            self.save_schedules()
            self.append_bot_log(
                "schedule.delete",
                account_id=str(snapshot.get("accountId") or ""),
                schedule=snapshot,
            )
        return {"ok": True}

    def clear_stuck_schedules(
        self, account_id: str, user: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        account_id = _required_account_id(account_id)
        if not self.web_auth.can_access_account(user, account_id):
            raise WebError(HTTPStatus.FORBIDDEN, "Permission denied for this LINE account.")
        cleared = 0
        with self.schedule_lock:
            for job in self.schedules:
                if job.get("accountId") != account_id:
                    continue
                status = str(job.get("status") or "").lower()
                stuck = bool(
                    job.get("running")
                    or status in {"running", "error"}
                    or job.get("lastError")
                )
                if not stuck:
                    continue
                old_status = str(job.get("status") or "")
                was_running = bool(job.get("running"))
                job["running"] = False
                job["lastError"] = None
                if job.get("enabled"):
                    if not job.get("nextRunAt"):
                        job["nextRunAt"] = _compute_next_epoch(job)
                    job["status"] = "waiting" if job.get("nextRunAt") else "paused"
                else:
                    job["status"] = "paused"
                job["updatedAt"] = _now_iso()
                _append_history(
                    job,
                    {
                        "at": _now_iso(),
                        "ok": True,
                        "action": "clear_stuck",
                        "oldStatus": old_status,
                        "wasRunning": was_running,
                    },
                )
                self.append_bot_log(
                    "schedule.clear_stuck",
                    account_id=account_id,
                    schedule=job,
                    detail=f"reset from {old_status or 'unknown'}",
                    data={"oldStatus": old_status, "wasRunning": was_running},
                )
                cleared += 1
            if cleared:
                self.save_schedules()
            schedules = [
                dict(job) for job in self.schedules if job.get("accountId") == account_id
            ]
        return {"ok": True, "cleared": cleared, "schedules": schedules}

    # -- message patterns (tenant-owned) ---------------------------------
    def list_patterns(self, user: dict[str, Any] | None = None) -> dict[str, Any]:
        data = self.store.get("patterns", {"patterns": []})
        items = data.get("patterns", []) if isinstance(data, dict) else []
        raw_categories = data.get("categories", []) if isinstance(data, dict) else []
        owner_id = str((user or {}).get("id") or "")
        categories = [
            {
                "id": DEFAULT_PATTERN_CATEGORY_ID,
                "name": "General",
                "system": True,
            }
        ]
        categories.extend(
            dict(category)
            for category in raw_categories
            if isinstance(category, dict) and str(category.get("ownerId") or "") == owner_id
        )
        category_names = {
            str(category.get("id") or ""): str(category.get("name") or "")
            for category in categories
        }
        patterns = []
        for pattern in items:
            if not isinstance(pattern, dict) or str(pattern.get("ownerId") or "") != owner_id:
                continue
            item = dict(pattern)
            category_id = str(item.get("categoryId") or DEFAULT_PATTERN_CATEGORY_ID)
            if category_id not in category_names:
                category_id = DEFAULT_PATTERN_CATEGORY_ID
            item["categoryId"] = category_id
            item["categoryName"] = category_names[category_id]
            patterns.append(item)
        patterns.sort(
            key=lambda item: (
                str(item.get("categoryName") or "").casefold(),
                str(item.get("name") or "").casefold(),
            )
        )
        return {
            "patterns": patterns,
            "categories": categories,
        }

    def create_pattern_category(
        self, body: dict[str, Any], user: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        name = str(body.get("name") or "").strip()
        if not name:
            raise WebError(HTTPStatus.BAD_REQUEST, "Category name is required.")
        if len(name) > 80:
            raise WebError(HTTPStatus.BAD_REQUEST, "Category name is too long.")
        owner_id = str((user or {}).get("id") or "")
        with self.schedule_lock:
            data = self.store.get("patterns", {"patterns": [], "categories": []})
            items = data.get("patterns", []) if isinstance(data, dict) else []
            categories = data.get("categories", []) if isinstance(data, dict) else []
            if not isinstance(items, list):
                items = []
            if not isinstance(categories, list):
                categories = []
            owner_categories = sum(
                1
                for category in categories
                if isinstance(category, dict)
                and str(category.get("ownerId") or "") == owner_id
            )
            if owner_categories >= MAX_PATTERN_CATEGORIES_PER_USER:
                raise WebError(
                    HTTPStatus.CONFLICT,
                    f"Each user can have at most {MAX_PATTERN_CATEGORIES_PER_USER} categories.",
                    "pattern_category_quota",
                )
            duplicate = any(
                isinstance(category, dict)
                and str(category.get("ownerId") or "") == owner_id
                and str(category.get("name") or "").casefold() == name.casefold()
                for category in categories
            )
            if duplicate or name.casefold() in {"general", "ทั่วไป"}:
                raise WebError(HTTPStatus.CONFLICT, "Category name already exists.")
            category = {
                "id": uuid.uuid4().hex,
                "ownerId": owner_id,
                "name": name,
                "createdAt": _now_iso(),
            }
            categories.append(category)
            self.store.set("patterns", {"patterns": items, "categories": categories})
            self.append_bot_log(
                "pattern.category.create",
                account_id=str(body.get("accountId") or ""),
                detail=name,
            )
        return {"ok": True, "category": category}

    def update_pattern_category(
        self, body: dict[str, Any], user: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        category_id = str(body.get("id") or "").strip()
        name = str(body.get("name") or "").strip()
        if not category_id or category_id == DEFAULT_PATTERN_CATEGORY_ID:
            raise WebError(HTTPStatus.BAD_REQUEST, "The General category cannot be edited.")
        if not name:
            raise WebError(HTTPStatus.BAD_REQUEST, "Category name is required.")
        if len(name) > 80:
            raise WebError(HTTPStatus.BAD_REQUEST, "Category name is too long.")
        if name.casefold() in {"general", "ทั่วไป"}:
            raise WebError(HTTPStatus.CONFLICT, "Category name already exists.")
        owner_id = str((user or {}).get("id") or "")
        with self.schedule_lock:
            data = self.store.get("patterns", {"patterns": [], "categories": []})
            items = data.get("patterns", []) if isinstance(data, dict) else []
            categories = data.get("categories", []) if isinstance(data, dict) else []
            if not isinstance(items, list):
                items = []
            if not isinstance(categories, list):
                categories = []
            category = next(
                (
                    item
                    for item in categories
                    if isinstance(item, dict)
                    and str(item.get("id") or "") == category_id
                    and str(item.get("ownerId") or "") == owner_id
                ),
                None,
            )
            if category is None:
                raise WebError(HTTPStatus.NOT_FOUND, "Category not found.")
            duplicate = any(
                isinstance(item, dict)
                and item is not category
                and str(item.get("ownerId") or "") == owner_id
                and str(item.get("name") or "").casefold() == name.casefold()
                for item in categories
            )
            if duplicate:
                raise WebError(HTTPStatus.CONFLICT, "Category name already exists.")
            old_name = str(category.get("name") or "")
            category["name"] = name
            category["updatedAt"] = _now_iso()
            self.store.set("patterns", {"patterns": items, "categories": categories})
            self.append_bot_log(
                "pattern.category.update",
                account_id=str(body.get("accountId") or ""),
                detail=f"{old_name} -> {name}",
            )
        return {"ok": True, "category": dict(category)}

    def delete_pattern_category(
        self,
        category_id: str,
        account_id: str | None = None,
        user: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        category_id = str(category_id or "").strip()
        if not category_id or category_id == DEFAULT_PATTERN_CATEGORY_ID:
            raise WebError(HTTPStatus.BAD_REQUEST, "The General category cannot be deleted.")
        owner_id = str((user or {}).get("id") or "")
        with self.schedule_lock:
            data = self.store.get("patterns", {"patterns": [], "categories": []})
            items = data.get("patterns", []) if isinstance(data, dict) else []
            categories = data.get("categories", []) if isinstance(data, dict) else []
            if not isinstance(items, list):
                items = []
            if not isinstance(categories, list):
                categories = []
            removed = next(
                (
                    category
                    for category in categories
                    if isinstance(category, dict)
                    and str(category.get("id") or "") == category_id
                    and str(category.get("ownerId") or "") == owner_id
                ),
                None,
            )
            if removed is None:
                raise WebError(HTTPStatus.NOT_FOUND, "Category not found.")
            kept_categories = [category for category in categories if category is not removed]
            moved = 0
            for pattern in items:
                if (
                    isinstance(pattern, dict)
                    and str(pattern.get("ownerId") or "") == owner_id
                    and str(pattern.get("categoryId") or "") == category_id
                ):
                    pattern["categoryId"] = DEFAULT_PATTERN_CATEGORY_ID
                    moved += 1
            self.store.set("patterns", {"patterns": items, "categories": kept_categories})
            self.append_bot_log(
                "pattern.category.delete",
                account_id=account_id,
                detail=str(removed.get("name") or category_id),
                data={"patternsMoved": moved},
            )
        return {"ok": True, "patternsMoved": moved}

    def create_pattern(
        self, body: dict[str, Any], user: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        name = str(body.get("name") or "").strip()
        text = str(body.get("text") or "")
        category_id = str(body.get("categoryId") or DEFAULT_PATTERN_CATEGORY_ID).strip()
        if not name:
            raise WebError(HTTPStatus.BAD_REQUEST, "Pattern name is required.")
        if not text.strip():
            raise WebError(HTTPStatus.BAD_REQUEST, "Pattern text is required.")
        if len(name) > MAX_NAME_LENGTH:
            raise WebError(HTTPStatus.BAD_REQUEST, "Pattern name is too long.")
        if len(text) > MAX_TEXT_LENGTH:
            raise WebError(HTTPStatus.BAD_REQUEST, "Pattern text is too long.")
        with self.schedule_lock:
            data = self.store.get("patterns", {"patterns": []})
            items = data.get("patterns", []) if isinstance(data, dict) else []
            if not isinstance(items, list):
                items = []
            categories = data.get("categories", []) if isinstance(data, dict) else []
            if not isinstance(categories, list):
                categories = []
            owner_id = str((user or {}).get("id") or "")
            owner_patterns = sum(
                1
                for pattern in items
                if isinstance(pattern, dict) and str(pattern.get("ownerId") or "") == owner_id
            )
            if owner_patterns >= MAX_PATTERNS_PER_USER:
                raise WebError(
                    HTTPStatus.CONFLICT,
                    f"Each user can have at most {MAX_PATTERNS_PER_USER} patterns.",
                    "pattern_quota",
                )
            category_exists = category_id == DEFAULT_PATTERN_CATEGORY_ID or any(
                isinstance(category, dict)
                and str(category.get("id") or "") == category_id
                and str(category.get("ownerId") or "") == owner_id
                for category in categories
            )
            if not category_exists:
                raise WebError(HTTPStatus.BAD_REQUEST, "Pattern category is invalid.")
            item = {
                "id": uuid.uuid4().hex,
                "ownerId": owner_id,
                "name": name,
                "text": text,
                "categoryId": category_id,
            }
            items.append(item)
            self.store.set("patterns", {"patterns": items, "categories": categories})
            self.append_bot_log(
                "pattern.create",
                account_id=str(body.get("accountId") or ""),
                detail=name,
            )
        return {"ok": True, "pattern": item}

    def update_pattern(
        self, body: dict[str, Any], user: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        pattern_id = str(body.get("id") or "").strip()
        name = str(body.get("name") or "").strip()
        text = str(body.get("text") or "")
        category_id = str(body.get("categoryId") or DEFAULT_PATTERN_CATEGORY_ID).strip()
        if not pattern_id:
            raise WebError(HTTPStatus.BAD_REQUEST, "Pattern id is required.")
        if not name:
            raise WebError(HTTPStatus.BAD_REQUEST, "Pattern name is required.")
        if not text.strip():
            raise WebError(HTTPStatus.BAD_REQUEST, "Pattern text is required.")
        if len(name) > MAX_NAME_LENGTH:
            raise WebError(HTTPStatus.BAD_REQUEST, "Pattern name is too long.")
        if len(text) > MAX_TEXT_LENGTH:
            raise WebError(HTTPStatus.BAD_REQUEST, "Pattern text is too long.")
        owner_id = str((user or {}).get("id") or "")
        with self.schedule_lock:
            data = self.store.get("patterns", {"patterns": [], "categories": []})
            items = data.get("patterns", []) if isinstance(data, dict) else []
            categories = data.get("categories", []) if isinstance(data, dict) else []
            if not isinstance(items, list):
                items = []
            if not isinstance(categories, list):
                categories = []
            pattern = next(
                (
                    item
                    for item in items
                    if isinstance(item, dict)
                    and str(item.get("id") or "") == pattern_id
                    and str(item.get("ownerId") or "") == owner_id
                ),
                None,
            )
            if pattern is None:
                raise WebError(HTTPStatus.NOT_FOUND, "Pattern not found.")
            category_exists = category_id == DEFAULT_PATTERN_CATEGORY_ID or any(
                isinstance(category, dict)
                and str(category.get("id") or "") == category_id
                and str(category.get("ownerId") or "") == owner_id
                for category in categories
            )
            if not category_exists:
                raise WebError(HTTPStatus.BAD_REQUEST, "Pattern category is invalid.")
            old_name = str(pattern.get("name") or "")
            pattern.update(
                {
                    "name": name,
                    "text": text,
                    "categoryId": category_id,
                    "updatedAt": _now_iso(),
                }
            )
            self.store.set("patterns", {"patterns": items, "categories": categories})
            self.append_bot_log(
                "pattern.update",
                account_id=str(body.get("accountId") or ""),
                detail=f"{old_name} -> {name}",
            )
        return {"ok": True, "pattern": dict(pattern)}

    def delete_pattern(
        self,
        pattern_id: str,
        account_id: str | None = None,
        user: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        with self.schedule_lock:
            data = self.store.get("patterns", {"patterns": []})
            items = data.get("patterns", []) if isinstance(data, dict) else []
            if not isinstance(items, list):
                items = []
            owner_id = str((user or {}).get("id") or "")
            removed = next(
                (
                    p
                    for p in items
                    if isinstance(p, dict)
                    and p.get("id") == pattern_id
                    and str(p.get("ownerId") or "") == owner_id
                ),
                None,
            )
            kept = [p for p in items if p is not removed]
            if len(kept) == len(items):
                raise WebError(HTTPStatus.NOT_FOUND, "Pattern not found.")
            categories = data.get("categories", []) if isinstance(data, dict) else []
            self.store.set("patterns", {"patterns": kept, "categories": categories})
            self.append_bot_log(
                "pattern.delete",
                account_id=account_id,
                detail=str((removed or {}).get("name") or pattern_id),
            )
        return {"ok": True}

    # -- AI image settings (multi-provider) ------------------------------
    def _ai_all(self, user: dict[str, Any] | None = None) -> dict[str, Any]:
        root = self.store.get("ai_settings", {"tenants": {}})
        if not isinstance(root, dict):
            root = {"tenants": {}}
        owner_id = str((user or {}).get("id") or "")
        if "tenants" not in root:
            legacy = dict(root)
            root = {"tenants": {owner_id: legacy} if legacy else {}}
            self.store.set("ai_settings", root)
        raw_tenants = root.get("tenants")
        tenants: dict[str, Any] = raw_tenants if isinstance(raw_tenants, dict) else {}
        raw_data = tenants.get(owner_id)
        data: dict[str, Any] = raw_data if isinstance(raw_data, dict) else {}
        # Migrate the old flat Google-only shape {apiKey, model, baseUrl}.
        if "provider" not in data and any(k in data for k in ("apiKey", "model", "baseUrl")):
            data = {
                "provider": "google",
                "google": {
                    "apiKey": data.get("apiKey", ""),
                    "model": data.get("model", ""),
                    "baseUrl": data.get("baseUrl", ""),
                },
            }
        return data

    def _ai_provider_view(self, data: dict[str, Any], provider: str) -> dict[str, Any]:
        meta = _ai_provider_meta(provider)
        raw = data.get(provider)
        cfg = raw if isinstance(raw, dict) else {}
        model = str(cfg.get("model") or meta["model"]).strip() or meta["model"]
        view = {
            "apiKey": self._decrypt_secret(str(cfg.get("apiKey") or "")),
            "model": model,
            # Provider origins are fixed so a tenant cannot turn an API key field
            # into an authenticated SSRF primitive.
            "baseUrl": meta["baseUrl"],
        }
        if provider == "nanobananaapi":
            aspect = str(cfg.get("aspectRatio") or "").strip()
            # Previous builds stored the aspect ratio in "model" for this
            # provider. Preserve that setting while moving model selection to
            # the actual endpoint chooser.
            if model in NBAPI_ASPECT_RATIOS:
                aspect = aspect or model
                model = NBAPI_DEFAULT_MODEL
            if model not in NBAPI_MODELS:
                model = NBAPI_DEFAULT_MODEL
            if aspect not in NBAPI_ASPECT_RATIOS:
                aspect = meta["aspectRatio"]
            view["model"] = model
            view["aspectRatio"] = aspect
        elif provider == "fal":
            if model not in FAL_MODELS:
                model = FAL_DEFAULT_MODEL
            image_size = str(cfg.get("aspectRatio") or meta["aspectRatio"]).strip()
            if image_size not in FAL_IMAGE_SIZES:
                image_size = FAL_DEFAULT_IMAGE_SIZE
            view["model"] = model
            view["aspectRatio"] = image_size
        return view

    def _active_provider(self, data: dict[str, Any]) -> str:
        provider = str(data.get("provider") or "google")
        return provider if provider in AI_PROVIDERS else "google"

    def ai_settings(
        self, user: dict[str, Any] | None = None, *, reveal: bool = False
    ) -> dict[str, Any]:
        data = self._ai_all(user)
        provider = self._active_provider(data)
        if reveal:
            # Config for the ACTIVE provider, used to actually generate.
            return {"provider": provider, **self._ai_provider_view(data, provider)}
        providers: dict[str, Any] = {}
        for name in AI_PROVIDERS:
            meta = _ai_provider_meta(name)
            view = self._ai_provider_view(data, name)
            providers[name] = {
                "hasApiKey": bool(view["apiKey"]),
                "apiKeyPreview": _mask_secret(view["apiKey"]),
                "model": view["model"],
                "baseUrl": view["baseUrl"],
                "models": list(meta["models"]),
                "defaultModel": meta["model"],
                "modelLabels": dict(meta.get("modelLabels") or {}),
                "modelPrices": dict(meta.get("modelPrices") or {}),
                "aspectRatio": view.get("aspectRatio"),
                "aspectRatios": list(meta.get("aspectRatios") or []),
                "aspectRatioLabels": dict(meta.get("aspectRatioLabels") or {}),
                "defaultAspectRatio": meta.get("aspectRatio"),
                "label": meta["label"],
                "modelLabel": meta["modelLabel"],
            }
        return {
            "provider": provider,
            "providers": providers,
            "configured": providers[provider]["hasApiKey"],
        }

    def save_ai_settings(
        self, body: dict[str, Any], user: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        # Read-modify-write under one lock so a concurrent clear+save can't
        # resurrect a key the admin just removed (self.lock is reentrant).
        with self.lock:
            data = self._ai_all(user)
            root = self.store.get("ai_settings", {"tenants": {}})
            if not isinstance(root, dict):
                root = {"tenants": {}}
            tenants = root.get("tenants")
            if not isinstance(tenants, dict):
                tenants = {}
                root["tenants"] = tenants
            owner_id = str((user or {}).get("id") or "")
            requested = str(body.get("provider") or "")
            provider = requested if requested in AI_PROVIDERS else self._active_provider(data)
            meta = _ai_provider_meta(provider)
            current = self._ai_provider_view(data, provider)
            raw_key = body.get("apiKey")
            if body.get("clearApiKey"):
                api_key = ""
            elif raw_key is None or not str(raw_key).strip():
                # Blank key on save keeps the stored one (edit model without re-typing).
                api_key = current["apiKey"]
            else:
                api_key = str(raw_key).strip()
            model = str(body.get("model") or current["model"]).strip() or meta["model"]
            record = {
                "apiKey": self._encrypt_secret(api_key),
                "model": model,
                "baseUrl": meta["baseUrl"],
            }
            if provider == "nanobananaapi":
                legacy_aspect = model if model in NBAPI_ASPECT_RATIOS else ""
                if model not in NBAPI_MODELS:
                    model = NBAPI_DEFAULT_MODEL
                aspect_ratio = str(
                    body.get("aspectRatio")
                    or legacy_aspect
                    or current.get("aspectRatio")
                    or meta["aspectRatio"]
                ).strip()
                if aspect_ratio not in NBAPI_ASPECT_RATIOS:
                    aspect_ratio = meta["aspectRatio"]
                record["model"] = model
                record["aspectRatio"] = aspect_ratio
            elif provider == "fal":
                if model not in FAL_MODELS:
                    model = FAL_DEFAULT_MODEL
                image_size = str(
                    body.get("aspectRatio")
                    or current.get("aspectRatio")
                    or meta["aspectRatio"]
                ).strip()
                if image_size not in FAL_IMAGE_SIZES:
                    image_size = FAL_DEFAULT_IMAGE_SIZE
                record["model"] = model
                record["aspectRatio"] = image_size
            data[provider] = record
            # A save selects the active provider; a bare "clear" must not switch it.
            if not body.get("clearApiKey"):
                data["provider"] = provider
            tenants[owner_id] = data
            self.store.set("ai_settings", root)
            return {"ok": True, **self.ai_settings(user)}

    def generate_ai_image(
        self, prompt: str, user: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        cfg = self.ai_settings(user, reveal=True)
        result = _generate_ai_image(
            _prepare_ai_image_prompt(prompt),
            provider=cfg["provider"],
            api_key=cfg["apiKey"],
            model=cfg["model"],
            aspect_ratio=str(cfg.get("aspectRatio") or ""),
            base_url=cfg["baseUrl"],
        )
        return {
            "ok": True,
            "image": base64.b64encode(result["data"]).decode("ascii"),
            "mime": result["mime"],
            "name": result["name"],
        }

    # -- Global Ollama assistant and RAG ---------------------------------
    def _global_ai_all(self) -> dict[str, Any]:
        data = self.store.get("global_ai", {})
        if not isinstance(data, dict):
            data = {}
        if not isinstance(data.get("settings"), dict):
            data["settings"] = {}
        if not isinstance(data.get("apiSources"), list):
            data["apiSources"] = []
        if not isinstance(data.get("manualAnswers"), list):
            data["manualAnswers"] = []
        if not isinstance(data.get("chunks"), list):
            data["chunks"] = []
        if not isinstance(data.get("questions"), list):
            data["questions"] = []
        if not isinstance(data.get("tenants"), dict):
            data["tenants"] = {}
        return data

    @staticmethod
    def _assistant_owner_id(user: dict[str, Any] | None) -> str:
        owner_id = str((user or {}).get("id") or "").strip()
        if not owner_id:
            raise WebError(HTTPStatus.UNAUTHORIZED, "User authentication required.")
        return owner_id

    def _tenant_ai_knowledge(
        self, data: dict[str, Any], user: dict[str, Any] | None
    ) -> tuple[str, dict[str, Any]]:
        owner_id = self._assistant_owner_id(user)
        tenants = data["tenants"]
        tenant = tenants.get(owner_id)
        if not isinstance(tenant, dict):
            tenant = {}
            tenants[owner_id] = tenant
        for key in ("apiSources", "manualAnswers", "chunks"):
            if not isinstance(tenant.get(key), list):
                tenant[key] = []
        return owner_id, tenant

    def _global_ai_private_settings(self, data: dict[str, Any]) -> dict[str, Any]:
        raw = data.get("settings")
        settings = raw if isinstance(raw, dict) else {}
        try:
            top_k = max(1, min(int(settings.get("topK") or 5), 12))
        except (TypeError, ValueError):
            top_k = 5
        try:
            temperature = max(0.0, min(float(settings.get("temperature") or 0.2), 2.0))
        except (TypeError, ValueError):
            temperature = 0.2
        try:
            timeout = max(5.0, min(float(settings.get("timeout") or 120), 600.0))
        except (TypeError, ValueError):
            timeout = 120.0
        return {
            "enabled": bool(settings.get("enabled")),
            "baseUrl": str(settings.get("baseUrl") or DEFAULT_OLLAMA_BASE_URL),
            "apiKey": self._decrypt_secret(str(settings.get("apiKey") or "")),
            "chatModel": str(settings.get("chatModel") or "").strip(),
            "embeddingModel": str(settings.get("embeddingModel") or "").strip(),
            "systemPrompt": str(
                settings.get("systemPrompt") or DEFAULT_ASSISTANT_SYSTEM_PROMPT
            ).strip(),
            "strictKnowledge": bool(settings.get("strictKnowledge", False)),
            "topK": top_k,
            "temperature": temperature,
            "timeout": timeout,
        }

    def global_ai_settings(self, *, reveal: bool = False) -> dict[str, Any]:
        data = self._global_ai_all()
        settings = self._global_ai_private_settings(data)
        if reveal:
            return settings
        questions = [item for item in data["questions"] if isinstance(item, dict)]
        return {
            "enabled": settings["enabled"],
            "baseUrl": settings["baseUrl"],
            "hasApiKey": bool(settings["apiKey"]),
            "apiKeyPreview": _mask_secret(settings["apiKey"]),
            "chatModel": settings["chatModel"],
            "embeddingModel": settings["embeddingModel"],
            "systemPrompt": settings["systemPrompt"],
            "strictKnowledge": settings["strictKnowledge"],
            "topK": settings["topK"],
            "temperature": settings["temperature"],
            "timeout": settings["timeout"],
            "configured": bool(settings["enabled"] and settings["chatModel"]),
            "chunkCount": len(data["chunks"]),
            "unansweredCount": sum(
                1 for item in questions if item.get("status") == "unanswered"
            ),
            "indexMode": str(data.get("indexMode") or "none"),
            "indexError": str(data.get("indexError") or ""),
            "indexedAt": str(data.get("indexedAt") or ""),
        }

    def save_global_ai_settings(self, body: dict[str, Any]) -> dict[str, Any]:
        with self.lock:
            data = self._global_ai_all()
            current = self._global_ai_private_settings(data)
            try:
                base_url = normalize_ollama_base_url(
                    str(body.get("baseUrl") or current["baseUrl"])
                )
            except ValueError as exc:
                raise WebError(HTTPStatus.BAD_REQUEST, str(exc), "ollama_url_invalid") from exc
            raw_key = body.get("apiKey")
            if body.get("clearApiKey"):
                api_key = ""
            elif raw_key is None or not str(raw_key).strip():
                api_key = current["apiKey"]
            else:
                api_key = str(raw_key).strip()
            chat_model = str(body.get("chatModel") or current["chatModel"]).strip()[:200]
            embedding_model = str(
                body.get("embeddingModel") or current["embeddingModel"]
            ).strip()[:200]
            system_prompt = str(body.get("systemPrompt") or current["systemPrompt"]).strip()[
                :20_000
            ]
            try:
                top_k = max(1, min(int(body.get("topK", current["topK"])), 12))
                temperature = max(
                    0.0,
                    min(float(body.get("temperature", current["temperature"])), 2.0),
                )
                timeout = max(5.0, min(float(body.get("timeout", current["timeout"])), 600.0))
            except (TypeError, ValueError) as exc:
                raise WebError(
                    HTTPStatus.BAD_REQUEST,
                    "AI numeric settings are invalid.",
                    "ai_settings_invalid",
                ) from exc
            previous_embedding_model = current["embeddingModel"]
            data["settings"] = {
                "enabled": bool(body.get("enabled", current["enabled"])),
                "baseUrl": base_url,
                "apiKey": self._encrypt_secret(api_key),
                "chatModel": chat_model,
                "embeddingModel": embedding_model,
                "systemPrompt": system_prompt or DEFAULT_ASSISTANT_SYSTEM_PROMPT,
                "strictKnowledge": bool(
                    body.get("strictKnowledge", current["strictKnowledge"])
                ),
                "topK": top_k,
                "temperature": temperature,
                "timeout": timeout,
                "updatedAt": _now_iso(),
            }
            if embedding_model != previous_embedding_model:
                for chunk in data["chunks"]:
                    if isinstance(chunk, dict):
                        chunk.pop("embedding", None)
                for tenant in data["tenants"].values():
                    if not isinstance(tenant, dict):
                        continue
                    for chunk in tenant.get("chunks", []):
                        if isinstance(chunk, dict):
                            chunk.pop("embedding", None)
                    tenant["indexMode"] = "needs-reindex"
                    tenant["indexError"] = ""
                data["indexMode"] = "needs-reindex"
                data["indexError"] = ""
            self.store.set("global_ai", data)
        return {"ok": True, **self.global_ai_settings()}

    # -- per-shop assistant brain (Gemini key or Ollama) ----------------------
    def _assistant_settings_for(
        self, data: dict[str, Any], user: dict[str, Any] | None
    ) -> dict[str, Any]:
        """Effective assistant settings: the shop's own brain, else God's global one."""
        tenant_user = self.tenant_user(user) or {}
        owner_id = str(tenant_user.get("id") or "")
        tenant = data["tenants"].get(owner_id) if owner_id else None
        raw = tenant.get("settings") if isinstance(tenant, dict) else None
        if isinstance(raw, dict) and raw.get("provider") in {"gemini", "ollama"}:
            provider = str(raw["provider"])
            settings = self._global_ai_private_settings({"settings": raw})
            settings["provider"] = provider
            settings["source"] = "tenant"
            if provider == "gemini":
                key = settings["apiKey"] or self._ai_provider_view(
                    self._ai_all(tenant_user), "google"
                )["apiKey"]
                settings["apiKey"] = key
                settings["chatModel"] = settings["chatModel"] or DEFAULT_GEMINI_CHAT_MODEL
                settings["embeddingModel"] = (
                    settings["embeddingModel"] or DEFAULT_GEMINI_EMBEDDING_MODEL
                )
                settings["configured"] = bool(settings["enabled"] and key)
            else:
                settings["configured"] = bool(settings["enabled"] and settings["chatModel"])
            return settings
        settings = self._global_ai_private_settings(data)
        settings["provider"] = "ollama"
        settings["source"] = "global"
        settings["configured"] = bool(settings["enabled"] and settings["chatModel"])
        return settings

    def _assistant_client(self, settings: dict[str, Any]) -> OllamaClient | GeminiClient:
        if settings.get("provider") == "gemini":
            return GeminiClient(
                str(settings.get("apiKey") or ""), timeout=float(settings.get("timeout") or 120)
            )
        return self._ollama_client(settings)

    def assistant_settings(self, user: dict[str, Any] | None) -> dict[str, Any]:
        data = self._global_ai_all()
        settings = self._assistant_settings_for(data, user)
        global_settings = self._global_ai_private_settings(data)
        tenant_user = self.tenant_user(user) or {}
        return {
            "ok": True,
            "provider": settings["provider"],
            "source": settings["source"],
            "configured": settings["configured"],
            "enabled": settings["enabled"],
            "hasApiKey": bool(settings["apiKey"]),
            "apiKeyPreview": _mask_secret(settings["apiKey"]),
            "baseUrl": settings["baseUrl"],
            "chatModel": settings["chatModel"],
            "embeddingModel": settings["embeddingModel"],
            "strictKnowledge": settings["strictKnowledge"],
            "temperature": settings["temperature"],
            "topK": settings["topK"],
            "systemPrompt": settings["systemPrompt"],
            "imageKeyAvailable": bool(
                self._ai_provider_view(self._ai_all(tenant_user), "google")["apiKey"]
            ),
            "globalAvailable": bool(
                global_settings["enabled"] and global_settings["chatModel"]
            ),
            "canEdit": self.web_auth.has_permission(user, "manage_accounts")
            and not (user or {}).get("teamOwnerId"),
            "defaults": {
                "geminiChatModel": DEFAULT_GEMINI_CHAT_MODEL,
                "geminiEmbeddingModel": DEFAULT_GEMINI_EMBEDDING_MODEL,
                "ollamaBaseUrl": DEFAULT_OLLAMA_BASE_URL,
            },
        }

    def save_assistant_settings(
        self, body: dict[str, Any], user: dict[str, Any] | None
    ) -> dict[str, Any]:
        if not self.web_auth.has_permission(user, "manage_accounts") or (user or {}).get(
            "teamOwnerId"
        ):
            raise WebError(HTTPStatus.FORBIDDEN, "Only the shop owner can change the AI.")
        owner_id = self._assistant_owner_id(user)
        provider = str(body.get("provider") or "").strip().lower()
        if provider not in {"gemini", "ollama", "global"}:
            raise WebError(HTTPStatus.BAD_REQUEST, "Choose Gemini or Ollama.", "ai_settings_invalid")
        with self.lock:
            data = self._global_ai_all()
            _, tenant = self._tenant_ai_knowledge(data, user)
            previous = tenant.get("settings") if isinstance(tenant.get("settings"), dict) else {}
            previous_embedding = str((previous or {}).get("embeddingModel") or "")
            previous_provider = str((previous or {}).get("provider") or "")
            if provider == "global":
                tenant.pop("settings", None)
            else:
                current = self._global_ai_private_settings({"settings": previous or {}})
                raw_key = str(body.get("apiKey") or "").strip()
                if body.get("clearApiKey"):
                    api_key = ""
                elif raw_key:
                    api_key = raw_key
                else:
                    api_key = current["apiKey"] if previous_provider == provider else ""
                base_url = DEFAULT_OLLAMA_BASE_URL
                if provider == "ollama":
                    try:
                        base_url = normalize_ollama_base_url(
                            str(body.get("baseUrl") or current["baseUrl"])
                        )
                    except ValueError as exc:
                        raise WebError(
                            HTTPStatus.BAD_REQUEST, str(exc), "ollama_url_invalid"
                        ) from exc
                    if not str(body.get("chatModel") or "").strip():
                        raise WebError(
                            HTTPStatus.BAD_REQUEST,
                            "Pick the Ollama chat model.",
                            "ai_settings_invalid",
                        )
                try:
                    temperature = max(
                        0.0, min(float(body.get("temperature", current["temperature"])), 2.0)
                    )
                    top_k = max(1, min(int(body.get("topK", current["topK"])), 12))
                except (TypeError, ValueError) as exc:
                    raise WebError(
                        HTTPStatus.BAD_REQUEST,
                        "AI numeric settings are invalid.",
                        "ai_settings_invalid",
                    ) from exc
                tenant["settings"] = {
                    "provider": provider,
                    "enabled": True,
                    "baseUrl": base_url,
                    "apiKey": self._encrypt_secret(api_key),
                    "chatModel": str(body.get("chatModel") or "").strip()[:200],
                    "embeddingModel": str(body.get("embeddingModel") or "").strip()[:200],
                    "systemPrompt": str(
                        body.get("systemPrompt") or current["systemPrompt"]
                    ).strip()[:20_000]
                    or DEFAULT_ASSISTANT_SYSTEM_PROMPT,
                    "strictKnowledge": bool(
                        body.get("strictKnowledge", current["strictKnowledge"])
                    ),
                    "topK": top_k,
                    "temperature": temperature,
                    "timeout": current["timeout"],
                    "updatedAt": _now_iso(),
                }
                if provider == "gemini" and raw_key:
                    # One Gemini key per shop: share it with the AI image tool
                    # when that slot is still empty.
                    self._share_gemini_key_with_image_ai(user, raw_key)
            new_settings = tenant.get("settings") or {}
            if (
                str(new_settings.get("embeddingModel") or "") != previous_embedding
                or str(new_settings.get("provider") or "") != previous_provider
            ):
                for chunk in tenant.get("chunks", []):
                    if isinstance(chunk, dict):
                        chunk.pop("embedding", None)
                tenant["indexMode"] = "needs-reindex"
            self.store.set("global_ai", data)
        test: dict[str, Any] = {"ok": True, "error": ""}
        if body.get("test", True):
            test = self.test_assistant_settings(user)
        try:
            self.reindex_assistant_knowledge({"id": owner_id})
        except Exception:
            traceback.print_exc()
        return {**self.assistant_settings(user), "test": test}

    def _share_gemini_key_with_image_ai(self, user: dict[str, Any] | None, key: str) -> None:
        data = self._ai_all(user)
        raw_google = data.get("google")
        google: dict[str, Any] = raw_google if isinstance(raw_google, dict) else {}
        if self._decrypt_secret(str(google.get("apiKey") or "")):
            return
        self.save_ai_settings({"provider": "google", "apiKey": key}, user)

    def test_assistant_settings(self, user: dict[str, Any] | None) -> dict[str, Any]:
        settings = self._assistant_settings_for(self._global_ai_all(), user)
        if not settings["configured"]:
            return {"ok": False, "error": "not_configured"}
        try:
            client = self._assistant_client(settings)
            if settings["provider"] == "gemini":
                result = client.chat(
                    model=settings["chatModel"],
                    question="ping",
                    context="",
                    system_prompt="Reply with answer 'pong'.",
                    strict_knowledge=False,
                    temperature=0.0,
                )
                return {"ok": True, "error": "", "model": result.get("model")}
            models = client.list_models()
            names = {str(item.get("name") or "") for item in models}
            if settings["chatModel"] not in names and f"{settings['chatModel']}:latest" not in names:
                return {
                    "ok": False,
                    "error": f"Model {settings['chatModel']} is not installed in Ollama.",
                    "models": sorted(names),
                }
            return {"ok": True, "error": "", "models": sorted(names)}
        except OllamaError as exc:
            return {"ok": False, "error": _safe_log_detail(exc, 500)}

    def _ollama_client(self, settings: dict[str, Any] | None = None) -> OllamaClient:
        cfg = settings or self.global_ai_settings(reveal=True)
        return OllamaClient(
            str(cfg.get("baseUrl") or DEFAULT_OLLAMA_BASE_URL),
            api_key=str(cfg.get("apiKey") or ""),
            timeout=float(cfg.get("timeout") or 120),
        )

    def test_global_ai(self, body: dict[str, Any]) -> dict[str, Any]:
        settings = self.global_ai_settings(reveal=True)
        if body.get("baseUrl"):
            try:
                settings["baseUrl"] = normalize_ollama_base_url(str(body["baseUrl"]))
            except ValueError as exc:
                raise WebError(HTTPStatus.BAD_REQUEST, str(exc), "ollama_url_invalid") from exc
        if str(body.get("apiKey") or "").strip():
            settings["apiKey"] = str(body["apiKey"]).strip()
        try:
            models = self._ollama_client(settings).list_models()
        except OllamaError as exc:
            raise WebError(HTTPStatus.BAD_GATEWAY, str(exc), "ollama_unavailable") from exc
        return {"ok": True, "baseUrl": settings["baseUrl"], "models": models}

    @staticmethod
    def _knowledge_source_view(source: dict[str, Any]) -> dict[str, Any]:
        return {
            "id": str(source.get("id") or ""),
            "name": str(source.get("name") or ""),
            "url": str(source.get("url") or ""),
            "jsonPath": str(source.get("jsonPath") or ""),
            "enabled": bool(source.get("enabled", True)),
            "hasApiKey": bool(source.get("apiKey")),
            "lastSyncAt": str(source.get("lastSyncAt") or ""),
            "lastError": str(source.get("lastError") or ""),
            "contentLength": len(str(source.get("content") or "")),
        }

    def global_ai_knowledge(self) -> dict[str, Any]:
        data = self._global_ai_all()
        return {
            "knowledgeMarkdown": str(data.get("knowledgeMarkdown") or ""),
            "apiSources": [
                self._knowledge_source_view(source)
                for source in data["apiSources"]
                if isinstance(source, dict)
            ],
            "manualAnswerCount": len(data["manualAnswers"]),
            "chunkCount": len(data["chunks"]),
            "indexMode": str(data.get("indexMode") or "none"),
            "indexError": str(data.get("indexError") or ""),
            "indexedAt": str(data.get("indexedAt") or ""),
        }

    def assistant_knowledge(self, user: dict[str, Any] | None) -> dict[str, Any]:
        data = self._global_ai_all()
        _, tenant = self._tenant_ai_knowledge(data, user)
        stored_sections = tenant.get("knowledgeSections")
        return {
            "knowledgeMarkdown": str(tenant.get("knowledgeMarkdown") or ""),
            "sections": (
                [dict(item) for item in stored_sections if isinstance(item, dict)]
                if isinstance(stored_sections, list) and stored_sections
                else _knowledge_sections_from_markdown(
                    str(tenant.get("knowledgeMarkdown") or "")
                )
            ),
            "updatedAt": str(tenant.get("knowledgeUpdatedAt") or ""),
            "apiSources": [
                self._knowledge_source_view(source)
                for source in tenant["apiSources"]
                if isinstance(source, dict)
            ],
            "manualAnswerCount": len(tenant["manualAnswers"]),
            "chunkCount": len(tenant["chunks"]),
            "indexMode": str(tenant.get("indexMode") or "none"),
            "indexError": str(tenant.get("indexError") or ""),
            "indexedAt": str(tenant.get("indexedAt") or ""),
            "globalChunkCount": len(data["chunks"]),
        }

    def save_assistant_knowledge(
        self, body: dict[str, Any], user: dict[str, Any] | None
    ) -> dict[str, Any]:
        sections = (
            _validate_knowledge_sections(body["sections"]) if "sections" in body else None
        )
        markdown = (
            _knowledge_sections_markdown(sections)
            if sections is not None
            else str(body.get("knowledgeMarkdown") or "")
        )
        if len(markdown) > MAX_GLOBAL_KNOWLEDGE_LENGTH:
            raise WebError(
                HTTPStatus.REQUEST_ENTITY_TOO_LARGE,
                "knowledge.md is too large.",
                "knowledge_too_large",
            )
        with self.lock:
            data = self._global_ai_all()
            _, tenant = self._tenant_ai_knowledge(data, user)
            tenant["knowledgeMarkdown"] = markdown
            if sections is not None:
                tenant["knowledgeSections"] = sections
            else:
                tenant.pop("knowledgeSections", None)
            tenant["knowledgeUpdatedAt"] = _now_iso()
            self.store.set("global_ai", data)
        return {"ok": True, **self.reindex_assistant_knowledge(user)}

    def add_knowledge_faq(
        self, body: dict[str, Any], user: dict[str, Any] | None
    ) -> dict[str, Any]:
        """Append a question/answer pair to the shop's FAQ topic and reindex."""
        question = str(body.get("question") or "").strip()
        answer = str(body.get("answer") or "").strip()
        if not question or not answer:
            raise WebError(HTTPStatus.BAD_REQUEST, "Question and answer are required.")
        if len(question) > MAX_ASSISTANT_QUESTION_LENGTH or len(answer) > MAX_ASSISTANT_ANSWER_LENGTH:
            raise WebError(HTTPStatus.BAD_REQUEST, "Question or answer is too long.")
        tenant_user = self.tenant_user(user)
        owner_id = self._assistant_owner_id(tenant_user)
        question_id = str(body.get("questionId") or "").strip()
        with self.lock:
            data = self._global_ai_all()
            _, tenant = self._tenant_ai_knowledge(data, tenant_user)
            sections = tenant.get("knowledgeSections")
            if not isinstance(sections, list) or not sections:
                sections = _knowledge_sections_from_markdown(
                    str(tenant.get("knowledgeMarkdown") or "")
                )
            faq = next(
                (
                    item
                    for item in sections
                    if isinstance(item, dict) and item.get("id") == KNOWLEDGE_FAQ_SECTION_ID
                ),
                None,
            )
            if faq is None:
                faq = {"id": KNOWLEDGE_FAQ_SECTION_ID, "title": "คำถามที่พบบ่อย", "body": ""}
                sections.append(faq)
            entry = f"ถาม: {question}\nตอบ: {answer}"
            faq["body"] = f"{str(faq.get('body') or '').strip()}\n\n{entry}".strip()
            sections = _validate_knowledge_sections(sections)
            markdown = _knowledge_sections_markdown(sections)
            if len(markdown) > MAX_GLOBAL_KNOWLEDGE_LENGTH:
                raise WebError(
                    HTTPStatus.REQUEST_ENTITY_TOO_LARGE,
                    "knowledge.md is too large.",
                    "knowledge_too_large",
                )
            tenant["knowledgeSections"] = sections
            tenant["knowledgeMarkdown"] = markdown
            tenant["knowledgeUpdatedAt"] = _now_iso()
            if question_id:
                member_ids = self._tenant_member_ids(owner_id)
                for item in data["questions"]:
                    if (
                        isinstance(item, dict)
                        and str(item.get("id") or "") == question_id
                        and str(item.get("userId") or "") in member_ids
                    ):
                        item["answer"] = answer
                        item["status"] = "resolved"
                        item["resolvedBy"] = str(
                            (user or {}).get("displayName") or (user or {}).get("username") or ""
                        )
                        item["updatedAt"] = _now_iso()
            self.store.set("global_ai", data)
        return {"ok": True, **self.reindex_assistant_knowledge(tenant_user)}

    def _tenant_member_ids(self, owner_id: str) -> set[str]:
        ids = {owner_id}
        for item in self.web_auth.data.get("users", []):
            if isinstance(item, dict) and str(item.get("teamOwnerId") or "") == owner_id:
                ids.add(str(item.get("id") or ""))
        return ids

    def tenant_unanswered(
        self, user: dict[str, Any] | None, *, limit: int = 200
    ) -> dict[str, Any]:
        """Questions the shop's AI could not answer, newest first."""
        owner_id = self._assistant_owner_id(self.tenant_user(user))
        member_ids = self._tenant_member_ids(owner_id)
        data = self._global_ai_all()
        items = [
            self._public_assistant_question(item)
            for item in data["questions"]
            if isinstance(item, dict)
            and item.get("status") == "unanswered"
            and str(item.get("userId") or "") in member_ids
        ]
        items.sort(key=lambda item: item["createdAt"], reverse=True)
        return {"questions": items[: max(1, min(int(limit), 500))]}

    def dismiss_tenant_question(
        self, body: dict[str, Any], user: dict[str, Any] | None
    ) -> dict[str, Any]:
        question_id = str(body.get("id") or "").strip()
        owner_id = self._assistant_owner_id(self.tenant_user(user))
        member_ids = self._tenant_member_ids(owner_id)
        with self.lock:
            data = self._global_ai_all()
            target = next(
                (
                    item
                    for item in data["questions"]
                    if isinstance(item, dict)
                    and str(item.get("id") or "") == question_id
                    and str(item.get("userId") or "") in member_ids
                ),
                None,
            )
            if target is None:
                raise WebError(HTTPStatus.NOT_FOUND, "Question not found.")
            target["status"] = "dismissed"
            target["updatedAt"] = _now_iso()
            self.store.set("global_ai", data)
        return {"ok": True, **self.tenant_unanswered(user)}

    def save_assistant_api_source(
        self, body: dict[str, Any], user: dict[str, Any] | None
    ) -> dict[str, Any]:
        source_id = str(body.get("id") or "").strip()
        name = str(body.get("name") or "").strip()[:MAX_NAME_LENGTH]
        if not name:
            raise WebError(HTTPStatus.BAD_REQUEST, "API source name is required.")
        url = self._validate_knowledge_api_url(str(body.get("url") or ""))
        json_path = str(body.get("jsonPath") or "").strip()[:500]
        with self.lock:
            data = self._global_ai_all()
            _, tenant = self._tenant_ai_knowledge(data, user)
            sources = [item for item in tenant["apiSources"] if isinstance(item, dict)]
            existing = next((item for item in sources if item.get("id") == source_id), None)
            if existing is None and len(sources) >= MAX_KNOWLEDGE_API_SOURCES:
                raise WebError(HTTPStatus.CONFLICT, "Too many knowledge API sources.")
            current_key = (
                self._decrypt_secret(str(existing.get("apiKey") or "")) if existing else ""
            )
            if body.get("clearApiKey"):
                api_key = ""
            elif str(body.get("apiKey") or "").strip():
                api_key = str(body["apiKey"]).strip()
            else:
                api_key = current_key
            record = existing or {"id": uuid.uuid4().hex, "createdAt": _now_iso()}
            record.update(
                {
                    "name": name,
                    "url": url,
                    "jsonPath": json_path,
                    "apiKey": self._encrypt_secret(api_key),
                    "enabled": bool(body.get("enabled", True)),
                    "updatedAt": _now_iso(),
                }
            )
            if existing is None:
                sources.append(record)
            tenant["apiSources"] = sources
            self.store.set("global_ai", data)
        return {"ok": True, **self.assistant_knowledge(user)}

    def delete_assistant_api_source(
        self, source_id: str, user: dict[str, Any] | None
    ) -> dict[str, Any]:
        with self.lock:
            data = self._global_ai_all()
            _, tenant = self._tenant_ai_knowledge(data, user)
            sources = [item for item in tenant["apiSources"] if isinstance(item, dict)]
            kept = [item for item in sources if str(item.get("id") or "") != source_id]
            if len(kept) == len(sources):
                raise WebError(HTTPStatus.NOT_FOUND, "Knowledge API source not found.")
            tenant["apiSources"] = kept
            self.store.set("global_ai", data)
        return {"ok": True, **self.reindex_assistant_knowledge(user)}

    def save_global_ai_knowledge(self, body: dict[str, Any]) -> dict[str, Any]:
        markdown = str(body.get("knowledgeMarkdown") or "")
        if len(markdown) > MAX_GLOBAL_KNOWLEDGE_LENGTH:
            raise WebError(
                HTTPStatus.REQUEST_ENTITY_TOO_LARGE,
                "knowledge.md is too large.",
                "knowledge_too_large",
            )
        with self.lock:
            data = self._global_ai_all()
            data["knowledgeMarkdown"] = markdown
            data["knowledgeUpdatedAt"] = _now_iso()
            self.store.set("global_ai", data)
        return {"ok": True, **self.reindex_global_ai()}

    @staticmethod
    def _validate_knowledge_api_url(value: str) -> str:
        url = value.strip()
        parsed = urlparse(url)
        if (
            len(url) > MAX_URL_LENGTH
            or parsed.scheme not in {"http", "https"}
            or not parsed.hostname
            or parsed.username
            or parsed.password
        ):
            raise WebError(
                HTTPStatus.BAD_REQUEST,
                "Knowledge API URL is invalid.",
                "knowledge_api_url_invalid",
            )
        return url

