def _account_channel(account: dict[str, Any] | None) -> str:
    return str((account or {}).get("channel") or "line")


def _line_only() -> WebError:
    return WebError(
        HTTPStatus.BAD_REQUEST, "This works with LINE accounts only.", "line_only"
    )


def _crm_sender(by: str) -> tuple[str, str]:
    """CRM sender kind and id for an outgoing message attributed by ``note_outgoing``."""
    if not by or by in {"line_app", "telegram_app"}:
        return "app", ""
    if by in {"ai", "schedule", "api", "broadcast"}:
        return by, ""
    return "staff", by


def _room_tracked(chat_mid: str) -> bool:
    """KPI rooms are 1:1 customer chats; groups are not tracked."""
    chat_mid = str(chat_mid or "")
    return chat_mid[:1].lower() == "u" or chat_mid.startswith("tgu")


_HHMM_RE = re.compile(r"^([01]\d|2[0-3]):([0-5]\d)$")


def _default_kpi_settings() -> dict[str, Any]:
    return {
        "slaSeconds": DEFAULT_KPI_SLA_SECONDS,
        "businessHours": {
            "enabled": False,
            "days": [0, 1, 2, 3, 4, 5],
            "start": "09:00",
            "end": "18:00",
        },
        "shifts": {},
        "notifyOutsideHours": False,
    }


def _validate_time_rule(raw: Any) -> dict[str, Any]:
    if not isinstance(raw, dict):
        raise WebError(HTTPStatus.BAD_REQUEST, "Shift rules must be objects.", "invalid_kpi")
    days = raw.get("days")
    if not isinstance(days, list) or not days:
        raise WebError(HTTPStatus.BAD_REQUEST, "Pick at least one day.", "invalid_kpi")
    clean_days = sorted({int(day) for day in days if str(day).isdigit() and 0 <= int(day) <= 6})
    start = str(raw.get("start") or "")
    end = str(raw.get("end") or "")
    if not clean_days or not _HHMM_RE.match(start) or not _HHMM_RE.match(end):
        raise WebError(HTTPStatus.BAD_REQUEST, "Times must be HH:MM.", "invalid_kpi")
    return {"days": clean_days, "start": start, "end": end}


def _validate_kpi_settings(raw: Any, member_ids: set[str]) -> dict[str, Any]:
    if not isinstance(raw, dict):
        raise WebError(HTTPStatus.BAD_REQUEST, "settings must be an object.", "invalid_kpi")
    settings = _default_kpi_settings()
    try:
        sla = int(raw.get("slaSeconds", settings["slaSeconds"]))
    except (TypeError, ValueError) as exc:
        raise WebError(HTTPStatus.BAD_REQUEST, "SLA must be a number.", "invalid_kpi") from exc
    settings["slaSeconds"] = max(30, min(sla, 86_400))
    hours = raw.get("businessHours")
    if isinstance(hours, dict):
        rule = _validate_time_rule(hours)
        settings["businessHours"] = {"enabled": bool(hours.get("enabled")), **rule}
    shifts = raw.get("shifts")
    if shifts is not None:
        if not isinstance(shifts, dict):
            raise WebError(HTTPStatus.BAD_REQUEST, "shifts must be an object.", "invalid_kpi")
        clean: dict[str, list[dict[str, Any]]] = {}
        for user_id, rules in shifts.items():
            if str(user_id) not in member_ids or not isinstance(rules, list):
                continue
            if rules:
                clean[str(user_id)] = [_validate_time_rule(rule) for rule in rules[:14]]
        settings["shifts"] = clean
    settings["notifyOutsideHours"] = bool(raw.get("notifyOutsideHours", False))
    return settings


def _time_windows(
    rules: list[dict[str, Any]], from_ms: int, to_ms: int
) -> list[tuple[int, int]]:
    """Expand weekly HH:MM rules into local-time windows clipped to the range."""
    windows: list[tuple[int, int]] = []
    day = _dt.datetime.fromtimestamp(from_ms / 1000).date() - _dt.timedelta(days=1)
    last_day = _dt.datetime.fromtimestamp(to_ms / 1000).date()
    while day <= last_day:
        for rule in rules:
            if day.weekday() not in rule.get("days", []):
                continue
            sh, sm = (int(part) for part in str(rule["start"]).split(":"))
            eh, em = (int(part) for part in str(rule["end"]).split(":"))
            start = _dt.datetime.combine(day, _dt.time(sh, sm))
            end = _dt.datetime.combine(day, _dt.time(eh, em))
            if end <= start:
                end += _dt.timedelta(days=1)
            lo = max(from_ms, int(start.timestamp() * 1000))
            hi = min(to_ms, int(end.timestamp() * 1000))
            if hi > lo:
                windows.append((lo, hi))
        day += _dt.timedelta(days=1)
    windows.sort()
    merged: list[tuple[int, int]] = []
    for lo, hi in windows:
        if merged and lo <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], hi))
        else:
            merged.append((lo, hi))
    return merged


def _kpi_summary(items: list[dict[str, Any]], sla_seconds: int) -> dict[str, Any]:
    answered = [item for item in items if not item.get("missed")]
    times = sorted(_coerce_int(item.get("responseSeconds")) for item in answered)
    within = sum(1 for value in times if value <= sla_seconds)
    total = len(items)
    median = None
    if times:
        middle = len(times) // 2
        median = (
            times[middle]
            if len(times) % 2
            else round((times[middle - 1] + times[middle]) / 2)
        )
    return {
        "chats": total,
        "answered": len(answered),
        "missed": total - len(answered),
        "avgResponseSeconds": round(sum(times) / len(times)) if times else None,
        "medianResponseSeconds": median,
        "withinSla": within,
        "slaPercent": round(100 * within / total, 1) if total else None,
    }


def _presence_totals(
    segments: list[dict[str, Any]], windows: list[tuple[int, int]]
) -> dict[str, int | None]:
    totals = dict.fromkeys(sorted(PRESENCE_STATES), 0)
    scheduled = sum(hi - lo for lo, hi in windows)
    covered = 0
    for segment in segments:
        seg_lo = _coerce_int(segment.get("from"))
        seg_hi = _coerce_int(segment.get("to"))
        state = str(segment.get("state") or "")
        if state not in totals or seg_hi <= seg_lo:
            continue
        for lo, hi in windows:
            overlap = min(hi, seg_hi) - max(lo, seg_lo)
            if overlap > 0:
                totals[state] += overlap
                covered += overlap
    result: dict[str, int | None] = {
        state: round(value / 1000) for state, value in totals.items()
    }
    result["offline"] = max(0, round((scheduled - covered) / 1000))
    result["scheduled"] = round(scheduled / 1000)
    return result


def _build_kpi_report(
    *,
    responses: list[dict[str, Any]],
    segments: list[dict[str, Any]],
    rooms: dict[str, dict[str, Any]],
    members: list[dict[str, Any]],
    settings: dict[str, Any],
    from_ms: int,
    to_ms: int,
    now_ms: int,
) -> dict[str, Any]:
    sla = int(settings.get("slaSeconds") or DEFAULT_KPI_SLA_SECONDS)
    tiles = _kpi_summary(responses, sla)
    pending: list[dict[str, Any]] = sorted(
        (
            {
                "chatMid": mid,
                "waitingSince": _coerce_int(room.get("firstUnansweredAt")),
                "waitingSeconds": max(
                    0, round((now_ms - _coerce_int(room.get("firstUnansweredAt"))) / 1000)
                ),
            }
            for mid, room in rooms.items()
            if room.get("status") == "waiting" and _coerce_int(room.get("firstUnansweredAt"))
        ),
        key=lambda item: item["waitingSince"],
    )
    tiles["pendingNow"] = len(pending)
    tiles["overdueNow"] = sum(
        1 for item in pending if item["waitingSeconds"] > KPI_OVERDUE_SECONDS
    )
    business = settings.get("businessHours") or {}
    default_windows = (
        _time_windows([business], from_ms, to_ms)
        if business.get("enabled")
        else [(from_ms, to_ms)]
    )
    shifts = settings.get("shifts") or {}
    member_ids = {member["id"] for member in members}
    per_user = []
    timeline = []
    for member in members:
        member_segments = [item for item in segments if item.get("userId") == member["id"]]
        rules = shifts.get(member["id"])
        windows = _time_windows(rules, from_ms, to_ms) if rules else default_windows
        presence = _presence_totals(member_segments, windows)
        if not rules and not business.get("enabled"):
            # Without a shift or business hours "offline" has no meaning.
            presence["offline"] = None
            presence["scheduled"] = None
        per_user.append(
            {
                **member,
                **_kpi_summary(
                    [item for item in responses if item.get("answeredBy") == member["id"]],
                    sla,
                ),
                "presence": presence,
                "hasShift": bool(rules),
            }
        )
        clipped = [
            {
                "state": item.get("state"),
                "from": max(from_ms, _coerce_int(item.get("from"))),
                "to": min(to_ms, _coerce_int(item.get("to"))),
            }
            for item in member_segments
            if _coerce_int(item.get("to")) > from_ms and _coerce_int(item.get("from")) < to_ms
        ]
        timeline.append({"userId": member["id"], "name": member["name"], "segments": clipped[-500:]})
    ai_items = [item for item in responses if item.get("answeredBy") == "ai"]
    app_items = [item for item in responses if item.get("answeredBy") == "line_app"]
    human_items = [item for item in responses if item.get("answeredBy") in member_ids]
    daily_map: dict[str, list[dict[str, Any]]] = {}
    for item in responses:
        key = _dt.datetime.fromtimestamp(_coerce_int(item.get("askedAt")) / 1000).date().isoformat()
        daily_map.setdefault(key, []).append(item)
    daily = [
        {"date": key, **_kpi_summary(items, sla)} for key, items in sorted(daily_map.items())
    ]

    def states_at(moment: int) -> set[str]:
        return {
            str(item.get("state"))
            for item in segments
            if item.get("userId") in member_ids
            and _coerce_int(item.get("from")) <= moment <= _coerce_int(item.get("to"))
        }

    away_alerts = 0
    for item in responses:
        states = states_at(_coerce_int(item.get("askedAt")))
        if "away" in states and not states & {"active", "standby", "busy"}:
            away_alerts += 1
    return {
        "ok": True,
        "from": from_ms,
        "to": to_ms,
        "slaSeconds": sla,
        "tiles": tiles,
        "perUser": per_user,
        "ai": _kpi_summary(ai_items, sla),
        "lineApp": _kpi_summary(app_items, sla),
        "split": {
            "ai": len(ai_items),
            "human": len(human_items),
            "lineApp": len(app_items),
            "missed": sum(1 for item in responses if item.get("missed")),
        },
        "daily": daily,
        "pendingNow": pending[:200],
        "presence": timeline,
        "awayAlerts": away_alerts,
    }


def _message_box_id(box: dict[str, Any]) -> str:
    for key in ("id", "chatId", "chatMid", "messageBoxId", "mid"):
        value = box.get(key)
        if value:
            return str(value)
    nested = box.get("messageBox")
    if isinstance(nested, dict):
        return _message_box_id(nested)
    return ""


def _message_time(message: Any) -> int:
    if not isinstance(message, dict):
        return 0
    for key in ("createdTime", "deliveredTime", "updatedTime", "sentTime"):
        timestamp = _coerce_int(message.get(key))
        if timestamp:
            return timestamp
    return 0


def _message_box_time(box: dict[str, Any]) -> int:
    for key in ("updatedTime", "lastMessageTime", "lastMessageCreatedTime", "createdTime"):
        timestamp = _coerce_int(box.get(key))
        if timestamp:
            return timestamp
    messages = box.get("lastMessages")
    if isinstance(messages, list):
        return max((_message_time(message) for message in messages), default=0)
    nested = box.get("messageBox")
    if isinstance(nested, dict):
        return _message_box_time(nested)
    return 0


def _message_box_messages(box: dict[str, Any]) -> list[dict[str, Any]]:
    for candidate in (box, box.get("messageBox")):
        if not isinstance(candidate, dict):
            continue
        messages = candidate.get("lastMessages")
        if isinstance(messages, list):
            return [message for message in messages if isinstance(message, dict)]
    return []


def _message_box_unread_count(box: dict[str, Any]) -> int:
    for candidate in (box, box.get("messageBox")):
        if not isinstance(candidate, dict):
            continue
        if "unreadCount" in candidate:
            return max(0, _coerce_int(candidate.get("unreadCount")))
    return 0


def _chat_summary_map(
    api: OkLine,
    limit: int = 1000,
    *,
    message_boxes: dict[str, Any] | None = None,
) -> dict[str, dict[str, Any]]:
    boxes = message_boxes
    if boxes is None:
        try:
            boxes = api.get_message_boxes(limit=limit, last_messages_per_box=1)
        except TypeError:
            try:
                boxes = api.get_message_boxes(limit=limit)
            except Exception:
                return {}
        except Exception:
            return {}
    raw_boxes = boxes.get("messageBoxes", []) if isinstance(boxes, dict) else []
    summaries: dict[str, dict[str, Any]] = {}
    for rank, box in enumerate(raw_boxes[:limit]):
        if not isinstance(box, dict):
            continue
        mid = _message_box_id(box)
        if not mid or mid in summaries:
            continue
        messages = _message_box_messages(box)
        latest = max(
            enumerate(messages),
            key=lambda item: (_message_time(item[1]), item[0]),
            default=(0, None),
        )[1]
        summaries[mid] = {
            "rank": rank,
            "lastAt": _message_box_time(box),
            "unreadCount": _message_box_unread_count(box),
            "lastMessage": _message_summary(api, latest, {}) if latest else None,
        }
    return summaries


def _chat_recency_from_summaries(
    summaries: dict[str, dict[str, Any]],
) -> dict[str, tuple[int, int]]:
    return {
        mid: (_coerce_int(summary.get("rank")), _coerce_int(summary.get("lastAt")))
        for mid, summary in summaries.items()
    }


def _chat_recency_map(api: OkLine, limit: int = 1000) -> dict[str, tuple[int, int]]:
    return _chat_recency_from_summaries(_chat_summary_map(api, limit))


def _chat_list_fields(summary: dict[str, Any] | None) -> dict[str, Any]:
    if not summary:
        return {"unreadCount": 0, "lastMessageAt": 0, "lastMessage": None}
    return {
        "unreadCount": max(0, _coerce_int(summary.get("unreadCount"))),
        "lastMessageAt": _coerce_int(summary.get("lastAt")),
        "lastMessage": summary.get("lastMessage"),
    }


def _recent_chat_sort_key(row: dict[str, Any], recency: dict[str, tuple[int, int]]):
    mid = str(row.get("mid") or "")
    rank, last_at = recency.get(mid, (1_000_000_000, 0))
    name = str(row.get("name") or "").casefold()
    return (last_at <= 0, -last_at, rank, name, mid)


def _contact_rows(api: OkLine) -> list[tuple[str, dict[str, Any]]]:
    ids = api.get_all_contact_ids() or []
    rows: list[tuple[str, dict[str, Any]]] = []
    if not ids:
        return rows
    result = api.get_contacts(ids)
    contacts = result.get("contacts", {}) if isinstance(result, dict) else {}
    for mid, wrapper in contacts.items():
        contact = wrapper.get("contact", wrapper) if isinstance(wrapper, dict) else {}
        if not isinstance(contact, dict):
            contact = {}
        name = contact.get("displayNameOverridden") or contact.get("displayName") or ""
        rows.append(
            (
                mid,
                {
                    "mid": mid,
                    "name": name,
                    "statusMessage": contact.get("statusMessage") or "",
                    "picturePath": contact.get("picturePath"),
                },
            )
        )
    rows.sort(key=lambda row: (row[1]["name"] or "").lower())
    return rows


def _contact_name_map(api: OkLine) -> dict[str, str]:
    return {mid: data["name"] for mid, data in _contact_rows(api)}


def _resolve_names(api: OkLine, mids: list[str], names: dict[str, str]) -> None:
    """Fill ``names`` with LINE display names for any mids not already known
    (e.g. group members who aren't in our own contact list)."""
    want = list(dict.fromkeys(m for m in mids if m and m not in names))
    for i in range(0, len(want), 100):
        try:
            result = api.get_contacts(want[i : i + 100])
        except Exception:
            continue
        contacts = result.get("contacts", {}) if isinstance(result, dict) else {}
        for mid, wrapper in contacts.items():
            contact = wrapper.get("contact", wrapper) if isinstance(wrapper, dict) else {}
            if not isinstance(contact, dict):
                contact = {}
            name = contact.get("displayNameOverridden") or contact.get("displayName") or ""
            if name:
                names[mid] = name


def _resolve_to(api: OkLine, value: str) -> str:
    value = value.strip()
    if not value:
        raise WebError(HTTPStatus.BAD_REQUEST, "target is required.")
    if is_mid(value):
        return value
    matches = [
        (mid, name)
        for mid, name in _contact_name_map(api).items()
        if value.lower() in name.lower()
    ]
    if len(matches) == 1:
        return matches[0][0]
    if not matches:
        raise WebError(HTTPStatus.BAD_REQUEST, f"No contact matching {value!r}.")
    names = ", ".join(name for _, name in matches[:6])
    raise WebError(HTTPStatus.BAD_REQUEST, f"{len(matches)} contacts match: {names}")


_LINE_MEDIA_HOST_SUFFIXES = ("line-scdn.net", "line-apps.com")
_MAX_MESSAGE_MEDIA_BYTES = 30 * 1024 * 1024
_MESSAGE_MEDIA_CONTENT_TYPES = frozenset({1, 2, 3, 5, 14, 21})


def _validated_line_media_url(url: str) -> str:
    parsed = urlparse(str(url or "").strip())
    try:
        port = parsed.port
    except ValueError as exc:
        raise RuntimeError("Invalid LINE media URL") from exc
    host = (parsed.hostname or "").rstrip(".").lower()
    trusted = any(
        host == suffix or host.endswith("." + suffix) for suffix in _LINE_MEDIA_HOST_SUFFIXES
    )
    if (
        parsed.scheme.lower() != "https"
        or not trusted
        or parsed.username
        or parsed.password
        or port not in (None, 443)
    ):
        raise RuntimeError("Untrusted LINE media URL")
    return parsed.geturl()


def _download_line_media_url(url: str, *, session: requests.Session | None = None) -> bytes:
    current = str(url or "")
    requester = session or requests
    for _ in range(4):
        current = _validated_line_media_url(current)
        response = None
        try:
            response = requester.get(
                current,
                timeout=25,
                stream=True,
                allow_redirects=False,
            )
            if response.status_code in {301, 302, 303, 307, 308}:
                location = response.headers.get("location")
                if not location:
                    raise RuntimeError("LINE media redirect has no destination")
                current = urljoin(current, location)
                continue
            response.raise_for_status()
            content_type = response.headers.get("content-type", "").lower().split(";", 1)[0]
            if content_type and not (
                content_type.startswith("image/")
                or content_type.startswith("video/")
                or content_type.startswith("audio/")
                or content_type.startswith("application/octet-stream")
                or content_type
                in {
                    "application/mp4",
                    "application/ogg",
                    "application/pdf",
                }
            ):
                raise RuntimeError(f"LINE media returned {content_type}")
            declared_size = int(response.headers.get("content-length") or 0)
            if declared_size > _MAX_MESSAGE_MEDIA_BYTES:
                raise RuntimeError("LINE media is too large")
            chunks: list[bytes] = []
            total = 0
            for chunk in response.iter_content(64 * 1024):
                if not chunk:
                    continue
                total += len(chunk)
                if total > _MAX_MESSAGE_MEDIA_BYTES:
                    raise RuntimeError("LINE media is too large")
                chunks.append(chunk)
            data = b"".join(chunks)
            if not data:
                raise RuntimeError("LINE media is empty")
            return data
        except requests.RequestException as exc:
            raise RuntimeError(f"LINE media download failed: {exc}") from exc
        finally:
            if response is not None:
                response.close()
    raise RuntimeError("Too many LINE media redirects")


def _safe_message_filename(value: Any) -> str:
    name = str(value or "").replace("\\", "/").rsplit("/", 1)[-1]
    name = name.replace("\r", "").replace("\n", "").strip()
    return name[:255] or "file"


def _download_message_payload(
    api: OkLine,
    message_id: str,
    chat_mid: str = "",
    *,
    preview: bool = False,
) -> tuple[bytes, str, int | None]:
    message = None
    if chat_mid:
        recent = api.get_recent_messages(chat_mid, 200) or []
        message = next(
            (
                item
                for item in recent
                if isinstance(item, dict) and str(item.get("id") or "") == message_id
            ),
            None,
        )
    content_type = None
    filename = ""
    if message:
        try:
            content_type = int(str(message.get("contentType")))
        except (TypeError, ValueError):
            content_type = None
    if message and not message.get("chunks"):
        raw_meta = message.get("contentMetadata")
        meta = raw_meta if isinstance(raw_meta, dict) else {}
        if content_type in {5, 14}:
            filename = str(meta.get("FILE_NAME") or "")
        if content_type in _MESSAGE_MEDIA_CONTENT_TYPES:
            preferred = (
                ("PREVIEW_URL", "DOWNLOAD_URL")
                if preview
                else (
                    "DOWNLOAD_URL",
                    "PREVIEW_URL",
                )
            )
            for key in preferred:
                media_url = str(meta.get(key) or "").strip()
                if not media_url:
                    continue
                try:
                    return (
                        _download_line_media_url(
                            media_url,
                            session=getattr(getattr(api, "transport", None), "session", None),
                        ),
                        filename,
                        content_type,
                    )
                except RuntimeError:
                    continue
    if not message or not message.get("chunks"):
        data = api.obs.download_object("talk", "m", message_id)
        return data, filename, content_type
    if not api.e2ee.is_ready():
        raise RuntimeError("E2EE keys are not available for this account")

    decrypted = api.decrypt_message(message)
    raw_meta = decrypted.get("contentMetadata")
    meta = raw_meta if isinstance(raw_meta, dict) else {}
    if content_type in {5, 14}:
        filename = str(meta.get("FILE_NAME") or "")
    key_material = str(meta.get("ENC_KM") or "")
    if not key_material:
        raise RuntimeError("Encrypted media key is not available")
    sid = str(meta.get("SID") or "m")
    oid = str(meta.get("OID") or message_id)
    encrypted = api.obs.download_object(
        "talk",
        sid,
        oid,
        talk_meta=encode_message_talk_meta(message_id),
    )
    data = e2ee_frame.decrypt_media_blob(encrypted, key_material)
    return data, filename, content_type


def _download_message_content(
    api: OkLine,
    message_id: str,
    chat_mid: str = "",
    *,
    preview: bool = False,
) -> bytes:
    data, _, _ = _download_message_payload(api, message_id, chat_mid, preview=preview)
    return data


def _chat_event_mids(msg: Any) -> list[str]:
    if not isinstance(msg, dict) or str(msg.get("contentType")) != "18":
        return []
    raw_meta = msg.get("contentMetadata")
    meta = raw_meta if isinstance(raw_meta, dict) else {}
    return [value for value in str(meta.get("LOC_ARGS") or "").split("\x1e") if is_mid(value)]


def _metadata_text(meta: dict[str, Any], *keys: str, limit: int = 500) -> str:
    for key in keys:
        value = meta.get(key)
        if value not in (None, ""):
            return str(value).strip()[:limit]
    return ""


def _message_contact_mid(msg: Any) -> str:
    if not isinstance(msg, dict) or str(msg.get("contentType")) != "13":
        return ""
    raw_meta = msg.get("contentMetadata")
    meta = raw_meta if isinstance(raw_meta, dict) else {}
    value = _metadata_text(meta, "mid", "MID", "contactMid", "CONTACT_MID", limit=80)
    return value if is_mid(value) else ""


def _message_location(msg: dict[str, Any]) -> dict[str, Any] | None:
    raw = msg.get("location")
    if not isinstance(raw, dict):
        return None

    def coordinate(*keys: str) -> float | None:
        for key in keys:
            value = raw.get(key)
            if value is None:
                continue
            try:
                return float(value)
            except (TypeError, ValueError):
                continue
        return None

    latitude = coordinate("latitude", "lat")
    longitude = coordinate("longitude", "lng", "lon")
    if latitude is not None and not -90 <= latitude <= 90:
        latitude = None
    if longitude is not None and not -180 <= longitude <= 180:
        longitude = None
    title = str(raw.get("title") or "").strip()[:300]
    address = str(raw.get("address") or "").strip()[:500]
    phone = str(raw.get("phone") or "").strip()[:80]
    if latitude is None and longitude is None and not title and not address and not phone:
        return None
    return {
        "title": title,
        "address": address,
        "phone": phone,
        "latitude": latitude,
        "longitude": longitude,
    }


def _message_link_url(meta: dict[str, Any], text: Any) -> str:
    candidates = [
        _metadata_text(meta, "URL", "LINK_URL", "URI", "PERMA_LINK", limit=2048),
        str(text or "").strip()[:2048],
    ]
    for candidate in candidates:
        if not candidate:
            continue
        parsed = urlparse(candidate)
        if (
            parsed.scheme.lower() in {"http", "https"}
            and parsed.hostname
            and not parsed.username
            and not parsed.password
        ):
            return candidate
    return ""


def _message_summary(api: OkLine, msg: Any, names: dict[str, str]) -> dict[str, Any]:
    if not isinstance(msg, dict):
        return {"text": str(msg)}
    resolved = msg
    text = msg.get("text")
    encrypted = bool(msg.get("chunks"))
    if encrypted:
        if api.e2ee.is_ready():
            try:
                resolved = api.decrypt_message(msg)
                text = resolved.get("text")
            except Exception:
                text = "[encrypted]"
        else:
            text = "[encrypted]"
    sender = msg.get("from") or ""
    raw_meta = resolved.get("contentMetadata")
    meta = raw_meta if isinstance(raw_meta, dict) else {}
    event_mids = _chat_event_mids(resolved)
    try:
        content_type = int(str(msg.get("contentType")))
    except (TypeError, ValueError):
        content_type = None
    contact_mid = _message_contact_mid(resolved)
    contact_name = _metadata_text(
        meta,
        "displayName",
        "DISPLAY_NAME",
        "contactName",
        "CONTACT_NAME",
        limit=300,
    )
    if contact_mid:
        contact_name = names.get(contact_mid) or contact_name or contact_mid
    duration_raw = _metadata_text(meta, "DURATION", "duration", limit=30)
    try:
        duration_ms = max(0, int(float(duration_raw))) if duration_raw else None
    except (TypeError, ValueError):
        duration_ms = None
    file_name = _metadata_text(meta, "FILE_NAME", "fileName", limit=255)
    file_size = _metadata_text(meta, "FILE_SIZE", "fileSize", limit=30)
    alt_text = _metadata_text(
        meta,
        "ALT_TEXT",
        "altText",
        "TITLE",
        "title",
        limit=1000,
    )
    media_type = content_type in _MESSAGE_MEDIA_CONTENT_TYPES
    return {
        "id": msg.get("id"),
        "from": sender,
        "fromName": names.get(sender) or sender,
        "to": msg.get("to"),
        "text": text,
        "contentType": content_type if content_type is not None else msg.get("contentType"),
        "stickerId": meta.get("STKID"),
        "fileName": file_name or None,
        "fileSize": file_size or None,
        "durationMs": duration_ms,
        "location": _message_location(resolved),
        "contactMid": contact_mid or None,
        "contactName": contact_name or None,
        "altText": alt_text or None,
        "linkUrl": (_message_link_url(meta, text) or None)
        if content_type in {4, 11, 12, 17, 22}
        else None,
        "eventKey": meta.get("LOC_KEY") if event_mids else None,
        "eventNames": [names.get(mid) or mid for mid in event_mids],
        "createdTime": msg.get("createdTime"),
        "encrypted": encrypted,
        "mediaReady": not media_type or not encrypted or bool(meta.get("ENC_KM")),
        "hasPreview": bool(meta.get("PREVIEW_URL")),
    }


def _json_default(value: Any) -> Any:
    if isinstance(value, (bytes, bytearray)):
        return {"base64": base64.b64encode(bytes(value)).decode("ascii")}
    return str(value)
